function ensureProfileReferralData(profile) {
  if (!profile) return profile;
  if (!profile.referralCode) {
    const cleanName = (profile.name || "USER").replace(/[^a-zA-Z0-9]/g, "").toUpperCase();
    const suffix = profile.id ? profile.id.replace(/[^a-zA-Z0-9]/g, "").substring(0, 4).toUpperCase() : Math.floor(1000 + Math.random() * 9000).toString();
    profile.referralCode = `SABI-${cleanName.substring(0, 6)}-${suffix}`;
  }
  if (profile.referredBy === undefined) profile.referredBy = null;
  if (profile.referredUsersCount === undefined) profile.referredUsersCount = 0;
  if (profile.referredActiveSubscribers === undefined) profile.referredActiveSubscribers = 0;
  if (profile.referredDriversCount === undefined) profile.referredDriversCount = 0;
  if (profile.referredActiveDrivers === undefined) profile.referredActiveDrivers = 0;
  if (profile.deliveryCredits === undefined) profile.deliveryCredits = 0.00;
  if (profile.freeSubDaysGranted === undefined) profile.freeSubDaysGranted = 0;
  if (!profile.referralsList) profile.referralsList = [];
  if (profile.identityId === undefined) profile.identityId = "";
  if (profile.identityDoc === undefined) profile.identityDoc = "";
  return profile;
}

function copyReferralLink() {
  const input = document.getElementById("referral-link-input");
  if (input) {
    input.select();
    input.setSelectionRange(0, 99999);
    navigator.clipboard.writeText(input.value).then(() => {
      showToast("¡Copiado!", "Enlace de referido copiado al portapapeles.");
    }).catch(err => {
      console.error("Could not copy: ", err);
    });
  }
}
window.copyReferralLink = copyReferralLink;

