// Helper para obtener la traducción del modal de Auto Import
function getSabíAutoImportI18n(lang) {
  // El usuario elige idioma con el combobox 🌐 ES/EN/NL/PAP
  const map = { 'es': 'es', 'en': 'en', 'nl': 'nl', 'pap': 'pap' };
  const code = map[lang] || map[(appState.lang || 'es')] || 'es';
  return SABI_AUTO_IMPORT_I18N[code] || SABI_AUTO_IMPORT_I18N.es;
}

