function calculateCustomsAndCouriers() {
  SoundEffects.playClick();
  const cat = document.getElementById("calc-category").value;
  const valUSD = parseFloat(document.getElementById("calc-value").value);
  const wt = parseFloat(document.getElementById("calc-weight").value);
  
  const len = parseFloat(document.getElementById("calc-length").value) || 0;
  const wd = parseFloat(document.getElementById("calc-width").value) || 0;
  const ht = parseFloat(document.getElementById("calc-height").value) || 0;

  if (isNaN(valUSD) || valUSD <= 0) return;

  // Customs calculations (Douane Aruba rules)
  const rateUSD_AWG = 1.80;
  const valueAWG = valUSD * rateUSD_AWG;

  // Insurance and Freight estimation
  let freightAWG = wt * 3.50 * rateUSD_AWG; // Estimate flete
  if (freightAWG < 15.00 * rateUSD_AWG) freightAWG = 15.00 * rateUSD_AWG; // base cargo
  let insuranceAWG = valueAWG * 0.015; // 1.5% insurance estimate

  // CIF Value = Cost + Insurance + Freight
  const cifAWG = valueAWG + insuranceAWG + freightAWG;

  // Customs duties based on category tariff
  const tariffObj = SABI_DATA.customsTariffs.find(t => t.category === cat);
  const dutyRate = tariffObj ? tariffObj.duty : 0.12;
  const dutyAWG = cifAWG * dutyRate;

  // Append border tax (BBO/BAVP/BAZV 7% combined)
  const borderTaxAWG = (cifAWG + dutyAWG) * 0.07;
  const totalTaxAWG = dutyAWG + borderTaxAWG;
  const sabiCommissionAWG = valueAWG * 0.04; // 4% Sabi Service Fee on product cost

  const lang = appState.language || 'es';
  const dict = SABI_TRANSLATIONS[lang];

  // Render customs breakdown
  document.getElementById("calc-results-section").style.display = "block";
  document.getElementById("customs-breakdown-box").innerHTML = `
    <div class="summary-row">
      <span>${dict['calc_summary_invoice'] || 'Valor de Factura'}:</span>
      <span>$${valUSD.toFixed(2)} USD / Fl. ${valueAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row">
      <span>${dict['calc_summary_cif'] || 'Valor CIF Declarado'}:</span>
      <span>Fl. ${cifAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row">
      <span>${dict['calc_summary_duty'] || 'Derechos de Aduana'} (${dutyRate*100}%):</span>
      <span>Fl. ${dutyAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row">
      <span>${dict['calc_summary_bbo'] || 'Impuesto Fronterizo (7% BBO)'}:</span>
      <span>Fl. ${borderTaxAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row">
      <span>${dict['calc_summary_total_tax'] || 'Impuestos Totales a Pagar en Aduana'}:</span>
      <span>Fl. ${totalTaxAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row" style="border-top:1px dashed var(--glass-border); padding-top:0.4rem; margin-top:0.4rem">
      <span>Comisión de Servicio Sabí (4%):</span>
      <span style="color:var(--neon-gold); font-weight:700">Fl. ${sabiCommissionAWG.toFixed(2)} AWG</span>
    </div>
  `;

  // Compare Couriers (Order by price)
  let courierResults = [];
  SABI_DATA.couriers.forEach(courier => {
    // Determine shipping weight (dimensional vs pure weight)
    let billableWeight = wt;
    let labelVol = "";
    if (courier.volumetric && len > 0 && wd > 0 && ht > 0) {
      let dimWt = (len * wd * ht) / 139;
      if (dimWt > wt) {
        billableWeight = dimWt;
        const volText = dict['calc_volumetric_weight'] || 'Volumétrico';
        labelVol = ` (${volText}: ${dimWt.toFixed(1)} lbs)`;
      }
    }

    let freightCostUSD = courier.baseFee + (billableWeight * courier.ratePerLb);
    let freightCostAWG = freightCostUSD * rateUSD_AWG;

    // Net Total (Courier charge + customs taxes + Sabi commission)
    let netTotalAWG = freightCostAWG + totalTaxAWG + sabiCommissionAWG;

    courierResults.push({
      id: courier.id,
      name: courier.name,
      freight: freightCostAWG,
      tax: totalTaxAWG,
      total: netTotalAWG,
      days: courier.deliveryDays,
      link: courier.link,
      labelVol
    });
  });

  // Sort cheapest first
  courierResults.sort((a,b) => a.total - b.total);

  const tbody = document.getElementById("courier-comparison-body");
  tbody.innerHTML = courierResults.map(res => `
    <tr>
      <td>
        <strong style="color:var(--text-main)">${res.name}</strong>
        <div style="font-size:0.7rem; color:var(--text-muted)">${res.labelVol}</div>
      </td>
      <td>Fl. ${res.freight.toFixed(2)}</td>
      <td>Fl. ${res.tax.toFixed(2)}</td>
      <td style="font-weight:700; color:var(--neon-cyan)">Fl. ${res.total.toFixed(2)}</td>
      <td>
        <span class="tag-courier">${dict[`courier_days_${res.id}`] || res.days}</span>
      </td>
    </tr>
  `).join('');

  // Add footnote explaining what total includes
  const savingsBox = document.getElementById("customs-savings-suggestion");
  if (savingsBox) {
    savingsBox.style.display = "block";
    savingsBox.innerHTML = `
      <p style="font-size:0.78rem; color:var(--text-muted); margin-top:0.75rem; text-align:center; line-height:1.4">
        💡 El <strong>Costo Total</strong> calculado incluye el flete neto del Courier, los impuestos de importación estimados en la aduana de Aruba y la <strong>Comisión de Servicio de Sabí (4% / Fl. ${sabiCommissionAWG.toFixed(2)} AWG)</strong>.
      </p>
    `;
  }
}

// ─── SABI AUTO IMPORT — Vehicle Import Calculator ──────────────────────────
// MVP: Manual inputs (no live API yet). Use AutoBidMaster + King Ocean defaults.
// Tariffs official DVW Aruba 2026: EV 12% | Hybrid 19% | Gas/Diesel 39%
// Border tax BBO 7% applied on (CIF + duty). Sabí fee 3-5% of CIF.
function calculateVehicleImport() {
  SoundEffects.playClick();

  // Pull inputs
  const winningBid      = parseFloat(document.getElementById('auto-winning-bid').value) || 0;
  const fuelType        = document.getElementById('auto-fuel-type').value;
  const copartFees      = parseFloat(document.getElementById('auto-copart-fees').value)     || 600;
  const inland          = parseFloat(document.getElementById('auto-inland-freight').value)  || 350;
  const ocean           = parseFloat(document.getElementById('auto-ocean-freight').value)   || 1800;
  const sabiPct         = parseFloat(document.getElementById('auto-sabi-fee').value)        || 4;
  const inspectionFeeUSD = parseFloat(document.getElementById('auto-inspection-fee').value)  || 200;

  if (winningBid <= 0) {
    showToast && showToast('Ingresa el Winning Bid de la subasta', 'warning');
    return;
  }

  // Tariffs lookup — DVW Aruba 2026
  const dutyMap = { ev: 0.12, hybrid: 0.19, gas: 0.39 };
  const dutyRate = dutyMap[fuelType] || 0.19;
  const rateUSD_AWG = 1.80;

  // CIF = Winning Bid + Copart Fees + Inland Freight + Ocean Freight
  const cifUSD = winningBid + copartFees + inland + ocean;
  const cifAWG = cifUSD * rateUSD_AWG;

  // Aruba import duty
  const dutyAWG = cifAWG * dutyRate;

  // Border tax BBO 7% on (CIF + duty)
  const borderTaxAWG = (cifAWG + dutyAWG) * 0.07;

  // Sabí professional fee (% of CIF)
  const sabiFeeAWG = cifAWG * (sabiPct / 100);

  // Pre-purchase inspection fee
  const inspectionFeeAWG = inspectionFeeUSD * rateUSD_AWG;

  // Total landed in Aruba
  const totalAWG = cifAWG + dutyAWG + borderTaxAWG + sabiFeeAWG + inspectionFeeAWG;
  const totalUSD = totalAWG / rateUSD_AWG;

  // Competitor comparison (15-25% of CIF)
  const competitorAvgAWG = cifAWG * 0.20;
  const savingsAWG = competitorAvgAWG - sabiFeeAWG;

  const fuelLabel = { ev: '100% Eléctrico (EV) — 12%', hybrid: 'Híbrido (HEV/PHEV) — 19%', gas: 'Gasolina/Diesel — 39%' }[fuelType];

  const target = document.getElementById('vehicle-results-section');
  if (!target) return;
  target.style.display = 'block';
  target.innerHTML = `
    <div class="summary-row">
      <span>Tipo de vehículo:</span>
      <span><strong>${fuelLabel}</strong></span>
    </div>
    <div class="summary-row">
      <span>Winning Bid (subasta):</span>
      <span>$${winningBid.toFixed(2)} USD</span>
    </div>
    <div class="summary-row">
      <span>Copart/Broker Fees:</span>
      <span>$${copartFees.toFixed(2)} USD</span>
    </div>
    <div class="summary-row">
      <span>US Inland Freight (yard → puerto FL):</span>
      <span>$${inland.toFixed(2)} USD</span>
    </div>
    <div class="summary-row">
      <span>Ocean Freight (Miami → Barcadera):</span>
      <span>$${ocean.toFixed(2)} USD</span>
    </div>
    <div class="summary-row">
      <span>Revisión por experto (pre-bid):</span>
      <span>$${inspectionFeeUSD.toFixed(2)} USD</span>
    </div>
    <div class="summary-row" style="border-top:1px solid var(--color-border); padding-top:8px; margin-top:8px">
      <strong>CIF (Puesto en Puerto Aruba):</strong>
      <strong>$${cifUSD.toFixed(2)} USD / Fl. ${cifAWG.toFixed(2)} AWG</strong>
    </div>
    <div class="summary-row">
      <span>Aruba Import Duty (${(dutyRate*100).toFixed(0)}%):</span>
      <span>Fl. ${dutyAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row">
      <span>Impuesto Fronterizo (7% BBO/BAVP/BAZV):</span>
      <span>Fl. ${borderTaxAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row">
      <span>Sabí Professional Fee (${sabiPct.toFixed(1)}% CIF):</span>
      <span>Fl. ${sabiFeeAWG.toFixed(2)} AWG</span>
    </div>
    <div class="summary-row" style="border-top:2px solid var(--neon-cyan); padding-top:12px; margin-top:12px; font-size:1.1em">
      <strong>💰 TOTAL LANDED IN ARUBA:</strong>
      <strong>$${totalUSD.toFixed(2)} USD / Fl. ${totalAWG.toFixed(2)} AWG</strong>
    </div>
    <div style="margin-top:16px; padding:12px; background:var(--accent-bg, rgba(0,255,200,0.08)); border:1px solid var(--neon-cyan); border-radius:8px; font-size:0.9em">
      💡 <strong>Ahorrás vs competencia local:</strong> Ellos cobran 15-25% (promedio 20%) = Fl. ${competitorAvgAWG.toFixed(2)}.<br>
      Sabí cobra ${sabiPct.toFixed(1)}% = Fl. ${sabiFeeAWG.toFixed(2)}.<br>
      <strong style="color:var(--neon-cyan)">Tu ahorro: Fl. ${savingsAWG.toFixed(2)} AWG (~$ ${(savingsAWG/rateUSD_AWG).toFixed(0)} USD)</strong>
    </div>
    <div style="margin-top:12px; padding:10px; background:rgba(255,200,0,0.06); border-left:3px solid #ffc800; border-radius:6px; font-size:0.85em">
      ℹ️ Tasas según <strong>Departamento di Aduana di Aruba (Douane Aruba)</strong>: EV 12% · Híbrido 19% · Gasolina/Diesel 39%. Aplican sobre el valor CIF.
    </div>
  `;

  // Smooth-scroll to results
  target.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

async function renderBoticasAndFuel() {
  const lang = appState.language || 'es';
  const dict = SABI_TRANSLATIONS[lang];

  const boticasCon = document.getElementById("boticas-container");
  if (boticasCon) {
    const todayStr = new Date().toISOString().split("T")[0];
    const calendario = SABI_DATA.boticasCalendario || [];
    const directorio = SABI_DATA.boticasDirectorio || {};

    const todayEntry = calendario.find(e => todayStr >= e.from && todayStr <= e.to);

    const renderBoticaInfo = (name) => {
      const info = directorio[name];
      if (!info) return `<strong>${name}</strong>`;
      return `<strong>Botica ${name}</strong> — 📞 ${info.phone} · 📍 ${info.address}`;
    };

    let html = "";

    if (todayEntry) {
      html += `
        <div class="league-box" style="margin-bottom:0.75rem; border:1.5px solid var(--neon-cyan)">
          <div style="font-weight:800; color:var(--neon-cyan); margin-bottom:0.5rem; text-transform:uppercase; font-size:0.75rem; letter-spacing:0.5px">
            🟢 ${dict['boticas_today'] || 'Botica de Turno Hoy'}
          </div>
          <div style="font-size:0.85rem; line-height:1.5">
            <div>${renderBoticaInfo(todayEntry.primary)}</div>
            ${todayEntry.secondary ? `<div style="margin-top:0.4rem; color:var(--text-muted)">${dict['boticas_alt'] || 'Alterna'}: ${renderBoticaInfo(todayEntry.secondary)}</div>` : ""}
          </div>
        </div>
      `;
    } else {
      html += `<div class="league-box" style="margin-bottom:0.75rem"><div style="color:var(--text-muted); font-size:0.85rem">${dict['boticas_no_data'] || 'No hay datos de turno para hoy. Verifica el calendario oficial de IVA.'}</div></div>`;
    }

    // Próximos turnos del mes (excluyendo el de hoy), máximo 4 próximos
    const upcoming = calendario
      .filter(e => e.from > todayStr)
      .slice(0, 4);

    if (upcoming.length > 0) {
      html += `<div style="font-size:0.7rem; color:var(--text-muted); text-transform:uppercase; letter-spacing:0.5px; margin:0.75rem 0 0.5rem">${dict['boticas_upcoming'] || 'Próximos turnos'}</div>`;
      html += upcoming.map(e => {
        const fromDate = new Date(e.from + "T00:00:00");
        const toDate = new Date(e.to + "T00:00:00");
        const fmt = (d) => d.toLocaleDateString(appState.language === 'en' ? 'en-US' : 'es-ES', { day: 'numeric', month: 'short' });
        const rangeLabel = e.from === e.to ? fmt(fromDate) : `${fmt(fromDate)} - ${fmt(toDate)}`;
        return `
          <div style="display:flex; justify-content:space-between; font-size:0.78rem; padding:0.4rem 0; border-bottom:1px solid var(--glass-border)">
            <span style="color:var(--text-muted)">${rangeLabel}</span>
            <span style="font-weight:700">Botica ${e.primary}</span>
          </div>
        `;
      }).join('');
    }

    boticasCon.innerHTML = html;
  }

  const fuelCon = document.getElementById("fuel-container");
  if (fuelCon) {
    const monthlyAdjustmentText = dict['fuel_vigente_desde'] || 'Vigente desde';
    const gasolineText = dict['fuel_gasoline'] || 'Gasolina';
    const dieselText = dict['fuel_diesel'] || 'Diesel';
    const changeText = dict['fuel_change'] || 'Cambio';

    const formatChange = (val) => {
      if (val === null || val === undefined) return "";
      const sign = val >= 0 ? "+" : "";
      return `${sign}${val.toFixed(2)} AWG`;
    };

    const renderFuelCard = (dateLabel, gasoline, diesel, changeLabel) => `
      <div class="league-box" style="margin-bottom:0.5rem; display:flex; justify-content:space-between; align-items:center">
        <div>
          <div style="font-weight:700">${dateLabel}</div>
          <div style="font-size:0.75rem; color:var(--text-muted)">${monthlyAdjustmentText}</div>
        </div>
        <div style="font-size:0.8rem; text-align:right">
          <div>${gasolineText}: <strong>Fl. ${gasoline}</strong></div>
          <div>${dieselText}: <strong>Fl. ${diesel}</strong></div>
          ${changeLabel ? `<div style="font-size:0.7rem; color:var(--neon-pink)">${changeText}: ${changeLabel}</div>` : ""}
        </div>
      </div>
    `;

    fuelCon.innerHTML = `<div style="text-align:center; color:var(--text-muted); font-size:0.8rem; padding:1rem 0">⌛ Cargando...</div>`;

    try {
      if (!supabaseClient) throw new Error("Supabase no inicializado");

      const { data, error } = await supabaseClient
        .from("fuel_prices")
        .select("*")
        .eq("id", 1)
        .single();

      if (error || !data || !data.gasoline) throw error || new Error("Sin datos");

      const effDate = new Date(data.effective_date + "T00:00:00");
      const dateLabel = effDate.toLocaleDateString(
        appState.language === 'en' ? 'en-US' : appState.language === 'nl' ? 'nl-NL' : 'es-ES',
        { day: 'numeric', month: 'long', year: 'numeric' }
      );

      fuelCon.innerHTML = renderFuelCard(
        dateLabel,
        Number(data.gasoline).toFixed(2),
        Number(data.diesel).toFixed(2),
        formatChange(data.gasoline_change)
      );
    } catch (e) {
      // Fallback: datos estáticos del array original si Supabase falla
      fuelCon.innerHTML = SABI_DATA.fuelPrices.map(f =>
        renderFuelCard(f.date, f.gasoline, f.diesel, f.change)
      ).join('');
    }
  }
}

