                    const magicVal = (magicDivision === undefined || magicDivision === null || magicDivision === "-")
                      ? "-" : magicDivision;
                    const magicIsClose = typeof magicVal === 'string' && /^\d+$/.test(magicVal) && parseInt(magicVal, 10) <= 10;
                    const playoffPctVal = playoffPct !== undefined && playoffPct !== null ? `${playoffPct}%` : "-";
                    const streakColor = typeof streak === 'string' && streak.startsWith('W')
                      ? 'var(--neon-emerald)' : typeof streak === 'string' && streak.startsWith('L')
                      ? 'var(--neon-pink)' : 'var(--text-muted)';
 
