// Comunidad sub-navigation switcher
function switchComunidadTab(tab) {
  if (!tab) return;
  appState.activeComunidadTab = tab;
  SoundEffects.playClick();
  
  document.querySelectorAll(".comunidad-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.comunidadTab === tab);
  });
  
  document.querySelectorAll(".comunidad-content").forEach(content => {
    const isThis = content.id === `comunidad-content-${tab}`;
    content.classList.toggle("active", isThis);
    content.style.display = isThis ? "block" : "none";
  });
  
  if (tab === 'market') {
    renderClassifieds();
  } else if (tab === 'delivery') {
    renderDeliveryRequestPortal();
  } else if (tab === 'live') {
    renderLiveStreams();
  } else if (tab === 'admin') {
    Promise.all([getSabiAdvancedMetrics(), getSabiDemandAnalytics()]).then(([metrics, demand]) => {
      appState.advancedMetrics = metrics;
      appState.demandAnalytics = demand;
      renderAdminDashboard();
    });
  } else if (tab === 'restaurantes') {
    renderVertical('restaurantes', VERTICAL_DEMOS.restaurantes, 'restaurante');
  } else if (tab === 'boticas') {
    renderVertical('boticas', VERTICAL_DEMOS.boticas, 'botica');
  } else if (tab === 'mercados') {
    renderVertical('mercados', VERTICAL_DEMOS.mercados, 'mercado');
  } else if (tab === 'panaderias') {
    renderVertical('panaderias', VERTICAL_DEMOS.panaderias, 'panaderia');
  } else if (tab === 'foodtrucks') {
    renderVertical('foodtrucks', VERTICAL_DEMOS.foodtrucks, 'foodtruck');
  } else if (tab === 'forrent') {
    renderVertical('forrent', VERTICAL_DEMOS.forrent, 'forrent');
  } else if (tab === 'housesale') {
    renderVertical('housesale', VERTICAL_DEMOS.housesale, 'housesale');
  } else if (tab === 'autos') {
    renderVertical('autos', VERTICAL_DEMOS.autos, 'auto');
  } else if (tab === 'vacations') {
    renderVacationRentalsTab();
  } else if (tab === 'empleos') {
    renderVertical('empleos', VERTICAL_DEMOS.empleos, 'empleo');
  } else if (tab === 'mitienda') {
    renderMitiendaTab();
  } else {
    // Si salimos de Mi Tienda, detener el simulador
    sabiSimulator.stop();
  }
}

// ==================== SABÍ STAYS (RENTAS VACACIONALES & STAYCATIONS) ====================

// Estado global para Sabí Stay
if (!appState.staysState) {
  appState.staysState = {
    mode: 'local', // 'local' (AWG + staycation discount) o 'tourist' (USD regular)
    activeSubTab: 'search', // 'search', 'host', 'turnover'
    socialFundAwg: 3450.00,
    rentals: [...(SABI_DATA.vacationRentals || [])],
    bookings: [],
    turnovers: [
      {
        id: "turn-01",
        propertyName: "🌴 Studio Anexo Independiente (Malmok)",
        checkoutDate: "2026-09-02",
        guestName: "John Smith (USA)",
        status: "pending_cleaning",
        assignedDriver: null
      },
      {
        id: "turn-02",
        propertyName: "🏡 Eagle Beach Coral Villa",
        checkoutDate: "2026-09-04",
        guestName: "Emma Watson (UK)",
        status: "pending_cleaning",
        assignedDriver: null
      }
    ]
  };
}

function renderVacationRentalsTab() {
  updateSocialFundDisplay();
  switchStaysSubTab(appState.staysState.activeSubTab);
  filterVacationRentals();
  updateHostEarningsCalculator();
  renderTurnoversList();
}

function updateSocialFundDisplay() {
  const el = document.getElementById("social-fund-display");
  if (el) {
    el.innerText = `Afl. ${appState.staysState.socialFundAwg.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} AWG`;
  }
}

function switchStaysSubTab(subtab) {
  appState.staysState.activeSubTab = subtab;
  
  const searchPanel = document.getElementById("stays-panel-search");
  const hostPanel = document.getElementById("stays-panel-host");
  const turnoverPanel = document.getElementById("stays-panel-turnover");

  if (searchPanel) searchPanel.style.display = (subtab === 'search') ? 'block' : 'none';
  if (hostPanel) hostPanel.style.display = (subtab === 'host') ? 'block' : 'none';
  if (turnoverPanel) turnoverPanel.style.display = (subtab === 'turnover') ? 'block' : 'none';

  document.querySelectorAll("#comunidad-content-vacations button[id^='stays-subtab-btn-']").forEach(btn => {
    const isThis = btn.id === `stays-subtab-btn-${subtab}`;
    btn.classList.toggle("btn-cyan", isThis);
    btn.classList.toggle("btn-secondary", !isThis);
    btn.classList.toggle("active", isThis);
  });
}

function toggleStaysMode(mode) {
  appState.staysState.mode = mode;
  const btnLocal = document.getElementById("stays-mode-btn-local");
  const btnTourist = document.getElementById("stays-mode-btn-tourist");

  if (btnLocal && btnTourist) {
    if (mode === 'local') {
      btnLocal.style.background = 'var(--neon-cyan)';
      btnLocal.style.color = '#000';
      btnTourist.style.background = 'transparent';
      btnTourist.style.color = 'var(--text-muted)';
    } else {
      btnTourist.style.background = 'var(--neon-cyan)';
      btnTourist.style.color = '#000';
      btnLocal.style.background = 'transparent';
      btnLocal.style.color = 'var(--text-muted)';
    }
  }
  filterVacationRentals();
}

function filterVacationRentals() {
  if (!appState.staysState.rentals || appState.staysState.rentals.length === 0) {
    if (typeof SABI_DATA !== 'undefined' && SABI_DATA.vacationRentals) {
      appState.staysState.rentals = [...SABI_DATA.vacationRentals];
    }
  }

  const district = document.getElementById("stays-filter-district") ? document.getElementById("stays-filter-district").value : 'all';
  const type = document.getElementById("stays-filter-type") ? document.getElementById("stays-filter-type").value : 'all';

  let list = appState.staysState.rentals || [];
  if (district !== 'all') {
    list = list.filter(r => r.district === district);
  }
  if (type !== 'all') {
    list = list.filter(r => r.propertyType === type);
  }

  renderVacationRentalsGrid(list);
}

function renderVacationRentalsGrid(rentals) {
  const container = document.getElementById("stays-grid-container");
  if (!container) return;

  if (rentals.length === 0) {
    container.innerHTML = `<div style="grid-column:1/-1; text-align:center; padding:3rem; color:var(--text-muted)">No se encontraron alojamientos con los filtros seleccionados.</div>`;
    return;
  }

  const isLocal = appState.staysState.mode === 'local';

  container.innerHTML = rentals.map(item => {
    let finalPriceStr = "";
    let originalPriceStr = "";
    let badgeHtml = "";

    if (isLocal) {
      const usdDiscounted = item.nightlyRateUsd * (1 - (item.localStaycationDiscountPct / 100));
      const awgRate = Math.round(usdDiscounted * 1.80);
      const originalAwg = Math.round(item.nightlyRateUsd * 1.80);
      
      finalPriceStr = `Afl. ${awgRate} AWG / noche`;
      originalPriceStr = `Afl. ${originalAwg} AWG`;
      badgeHtml = `<span style="background:rgba(0, 245, 212, 0.2); border:1px solid var(--neon-cyan); color:var(--neon-cyan); font-size:0.65rem; font-weight:800; padding:2px 8px; border-radius:10px; text-transform:uppercase">Staycation -${item.localStaycationDiscountPct}% OFF</span>`;
    } else {
      finalPriceStr = `$${item.nightlyRateUsd.toFixed(0)} USD / noche`;
      badgeHtml = `<span style="background:rgba(255, 255, 255, 0.1); border:1px solid var(--glass-border); color:var(--text-muted); font-size:0.65rem; font-weight:700; padding:2px 8px; border-radius:10px">Tarifa Turista</span>`;
    }

    const typeLabel = item.propertyType === 'annex_studio' ? '🌴 Anexo Studio Familiar' : (item.propertyType === 'entire_home' ? '🏡 Casa / Villa Completa' : '🌆 Departamento Executive');

    return `
      <div style="background:rgba(255,255,255,0.02); border:1px solid var(--glass-border); border-radius:20px; overflow:hidden; display:flex; flex-direction:column; transition:var(--transition-smooth);" onmouseover="this.style.borderColor='var(--neon-cyan)'" onmouseout="this.style.borderColor='var(--glass-border)'">
        <div style="position:relative; height:180px; overflow:hidden">
          <img src="${item.images[0]}" alt="${item.title}" style="width:100%; height:100%; object-fit:cover">
          <div style="position:absolute; top:10px; left:10px; display:flex; gap:6px; flex-wrap:wrap">
            ${badgeHtml}
          </div>
          <div style="position:absolute; bottom:10px; right:10px; background:rgba(0,0,0,0.75); color:var(--neon-gold); font-size:0.75rem; font-weight:800; padding:3px 8px; border-radius:8px">
            ★ ${item.rating} (${item.reviewsCount})
          </div>
        </div>

        <div style="padding:1.2rem; flex:1; display:flex; flex-direction:column; justify-content:space-between">
          <div>
            <div style="font-size:0.75rem; color:var(--neon-cyan); font-weight:700; margin-bottom:0.3rem">📍 ${item.district} • ${typeLabel}</div>
            <h3 style="font-size:1rem; font-weight:800; color:#fff; margin-bottom:0.5rem; line-height:1.3">${item.title}</h3>
            <p style="font-size:0.8rem; color:var(--text-muted); line-height:1.4; margin-bottom:1rem; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden">${item.description}</p>
            
            <div style="display:flex; gap:0.8rem; font-size:0.75rem; color:var(--text-muted); margin-bottom:1rem">
              <span>👥 ${item.maxGuests} huéspedes</span>
              <span>🛏️ ${item.bedrooms} dorm.</span>
              <span>🛁 ${item.bathrooms} baños</span>
            </div>
          </div>

          <div style="border-top:1px solid var(--glass-border); padding-top:0.8rem; display:flex; align-items:center; justify-content:space-between">
            <div>
              ${isLocal ? `<span style="font-size:0.7rem; text-decoration:line-through; color:var(--text-muted); display:block">${originalPriceStr}</span>` : ''}
              <span style="font-size:1.05rem; font-weight:800; color:#fff">${finalPriceStr}</span>
            </div>

            <button onclick="openStayBookingModal('${item.id}')" class="btn btn-sm btn-cyan" style="font-weight:800; border-radius:12px; padding:0.4rem 0.9rem">
              🗓️ Reservar
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function openStayBookingModal(rentalId) {
  const rental = (appState.staysState.rentals || []).find(r => r.id === rentalId);
  if (!rental) return;

  const isLocal = appState.staysState.mode === 'local';
  
  let nightlyRate = rental.nightlyRateUsd;
  let currencySymbol = "$";
  let currencyCode = "USD";

  if (isLocal) {
    nightlyRate = Math.round(rental.nightlyRateUsd * (1 - (rental.localStaycationDiscountPct / 100)) * 1.80);
    currencySymbol = "Afl. ";
    currencyCode = "AWG";
  }

  const modalHtml = `
    <div id="stay-booking-modal" style="position:fixed; inset:0; background:rgba(0,0,0,0.85); backdrop-filter:blur(8px); z-index:10000; display:flex; align-items:center; justify-content:center; padding:1rem;">
      <div style="background:#130e2c; border:1px solid var(--neon-cyan); border-radius:24px; max-width:540px; width:100%; padding:1.75rem; box-shadow:0 0 50px rgba(0,245,212,0.3); max-height:90vh; overflow-y:auto">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:1rem">
          <h3 style="font-size:1.2rem; font-weight:800; color:var(--neon-cyan); margin:0">🗓️ Confirmar Reserva de Estancia</h3>
          <button onclick="document.getElementById('stay-booking-modal').remove()" style="background:none; border:none; color:var(--text-muted); font-size:1.5rem; cursor:pointer">×</button>
        </div>

        <div style="display:flex; gap:1rem; align-items:center; background:rgba(255,255,255,0.03); border:1px solid var(--glass-border); border-radius:14px; padding:0.8rem; margin-bottom:1.25rem">
          <img src="${rental.images[0]}" style="width:70px; height:70px; border-radius:10px; object-fit:cover">
          <div>
            <div style="font-size:0.95rem; font-weight:800; color:#fff">${rental.title}</div>
            <div style="font-size:0.75rem; color:var(--text-muted)">📍 ${rental.address}</div>
            <div style="font-size:0.8rem; font-weight:700; color:var(--neon-gold); margin-top:0.2rem">${currencySymbol}${nightlyRate} ${currencyCode} / noche</div>
          </div>
        </div>

        <form id="stay-booking-form" onsubmit="event.preventDefault(); processStayBookingSubmit('${rental.id}', ${isLocal ? 'true' : 'false'}, ${nightlyRate});">
          <div style="display:flex; gap:0.8rem; margin-bottom:1rem">
            <div style="flex:1">
              <label style="font-size:0.75rem; color:var(--text-muted); font-weight:700; display:block; margin-bottom:0.3rem">Fecha Check-in</label>
              <input type="date" id="booking-checkin" required class="text-input" value="${new Date().toISOString().split('T')[0]}" onchange="calculateBookingCosts(${nightlyRate}, '${currencySymbol}')">
            </div>
            <div style="flex:1">
              <label style="font-size:0.75rem; color:var(--text-muted); font-weight:700; display:block; margin-bottom:0.3rem">Fecha Check-out</label>
              <input type="date" id="booking-checkout" required class="text-input" value="${new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0]}" onchange="calculateBookingCosts(${nightlyRate}, '${currencySymbol}')">
            </div>
          </div>

          <div id="booking-breakdown-box" style="background:rgba(0,0,0,0.4); border:1px solid var(--glass-border); border-radius:14px; padding:1rem; margin-bottom:1.25rem; font-size:0.85rem">
          </div>

          <button type="submit" class="btn btn-cyan btn-full" style="font-weight:800; padding:0.8rem; font-size:1rem; border-radius:14px">
            🚀 Confirmar Reserva &amp; Generar Subsidio
          </button>
        </form>
      </div>
    </div>
  `;

  document.body.insertAdjacentHTML('beforeend', modalHtml);
  calculateBookingCosts(nightlyRate, currencySymbol);
}

function calculateBookingCosts(nightlyRate, currencySymbol) {
  const checkinInput = document.getElementById("booking-checkin");
  const checkoutInput = document.getElementById("booking-checkout");
  const box = document.getElementById("booking-breakdown-box");
  if (!checkinInput || !checkoutInput || !box) return;

  const d1 = new Date(checkinInput.value);
  const d2 = new Date(checkoutInput.value);
  const diffTime = d2 - d1;
  const nights = Math.max(1, Math.ceil(diffTime / (1000 * 60 * 60 * 24)));

  const subtotal = nightlyRate * nights;
  const platformFee = Math.round(subtotal * 0.06);
  const socialContribution = Math.round(subtotal * 0.025);

  box.innerHTML = `
    <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem">
      <span style="color:var(--text-muted)">Noches de estancia:</span>
      <span style="font-weight:700; color:#fff">${nights} noche(s)</span>
    </div>
    <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem">
      <span style="color:var(--text-muted)">Subtotal (${currencySymbol}${nightlyRate} x ${nights}):</span>
      <span style="font-weight:700; color:#fff">${currencySymbol}${subtotal}</span>
    </div>
    <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem">
      <span style="color:var(--text-muted)">Comisión Sabí (6% total):</span>
      <span style="font-weight:700; color:var(--neon-cyan)">${currencySymbol}${platformFee}</span>
    </div>
    <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem; background:rgba(255, 224, 0, 0.1); border:1px solid var(--neon-gold); padding:0.4rem 0.6rem; border-radius:8px">
      <span style="color:var(--neon-gold); font-weight:700">🤝 Aporte al Fondo Comunitario (2.5%):</span>
      <span style="font-weight:800; color:var(--neon-gold)">+${currencySymbol}${socialContribution}</span>
    </div>
    <div style="display:flex; justify-content:space-between; margin-top:0.6rem; border-top:1px solid var(--glass-border); padding-top:0.6rem; font-size:1rem; font-weight:800">
      <span>Total a Pagar:</span>
      <span style="color:var(--neon-cyan)">${currencySymbol}${subtotal}</span>
    </div>
  `;
}

function processStayBookingSubmit(rentalId, isLocal, nightlyRate) {
  const modal = document.getElementById("stay-booking-modal");
  if (modal) modal.remove();

  const checkin = document.getElementById("booking-checkin") ? document.getElementById("booking-checkin").value : '';
  const checkout = document.getElementById("booking-checkout") ? document.getElementById("booking-checkout").value : '';

  const d1 = new Date(checkin);
  const d2 = new Date(checkout);
  const nights = Math.max(1, Math.ceil((d2 - d1) / (1000 * 60 * 60 * 24)));
  const subtotal = nightlyRate * nights;

  const socialContributionAwg = isLocal ? Math.round(subtotal * 0.025) : Math.round(subtotal * 1.80 * 0.025);
  appState.staysState.socialFundAwg += socialContributionAwg;
  updateSocialFundDisplay();

  SoundEffects.playJingle();
  showToast(
    "¡Reserva Confirmada!",
    `Reserva procesada exitosamente por ${nights} noche(s).\nSe han aportado Afl. ${socialContributionAwg} AWG al Fondo de Subsidio Comunitario de Sabí.`
  );

  if (supabaseClient) {
    supabaseClient.auth.getSession().then(res => {
      if (res.data?.session?.user) {
        supabaseClient.from('rental_bookings').insert({
          rental_id: rentalId,
          guest_id: res.data.session.user.id,
          check_in: checkin,
          check_out: checkout,
          is_local_resident: isLocal,
          total_price: subtotal,
          platform_fee: Math.round(subtotal * 0.06),
          social_fund_contribution: socialContributionAwg
        }).then(r => {
          if (r.error) console.warn("Error recording booking in Supabase:", r.error.message);
        });
      }
    });
  }
}

function updateHostEarningsCalculator() {
  const rateInput = document.getElementById("host-calc-rate");
  const nightsInput = document.getElementById("host-calc-nights");
  const box = document.getElementById("host-calc-results");

  if (!rateInput || !nightsInput || !box) return;

  const rate = parseFloat(rateInput.value) || 180;
  const nights = parseInt(nightsInput.value) || 18;

  const grossMonthly = rate * nights;
  const airbnbFee = grossMonthly * 0.15;
  const airbnbNet = grossMonthly - airbnbFee;

  const sabiFee = grossMonthly * 0.06;
  const sabiNet = grossMonthly - sabiFee;

  const extraMonthlyProfit = sabiNet - airbnbNet;
  const extraYearlyProfit = extraMonthlyProfit * 12;

  box.innerHTML = `
    <div style="display:grid; grid-template-columns:1fr 1fr; gap:0.8rem; margin-bottom:0.8rem">
      <div style="background:rgba(255,51,75,0.1); border:1px solid var(--neon-pink); border-radius:10px; padding:0.6rem; text-align:center">
        <div style="font-size:0.7rem; color:var(--text-muted); text-transform:uppercase">Airbnb / Vrbo (15% Fee)</div>
        <div style="font-size:1.1rem; font-weight:800; color:var(--neon-pink)">$${airbnbNet.toFixed(0)} USD</div>
        <div style="font-size:0.65rem; color:var(--text-muted)">Ingreso neto mensual</div>
      </div>

      <div style="background:rgba(0,245,212,0.1); border:1px solid var(--neon-cyan); border-radius:10px; padding:0.6rem; text-align:center">
        <div style="font-size:0.7rem; color:var(--neon-cyan); font-weight:800; text-transform:uppercase">Sabí Stay (6% Fee)</div>
        <div style="font-size:1.1rem; font-weight:800; color:var(--neon-cyan)">$${sabiNet.toFixed(0)} USD</div>
        <div style="font-size:0.65rem; color:var(--text-muted)">Ingreso neto mensual</div>
      </div>
    </div>

    <div style="background:linear-gradient(135deg, rgba(255, 224, 0, 0.15), rgba(0, 245, 212, 0.15)); border:1px solid var(--neon-gold); border-radius:12px; padding:0.75rem; text-align:center">
      <div style="font-size:0.75rem; font-weight:800; color:var(--neon-gold)">💰 Beneficio Extra para el Anfitrión en Sabí:</div>
      <div style="font-size:1.25rem; font-weight:800; color:#fff">+$${extraMonthlyProfit.toFixed(0)} USD / mes <span style="font-size:0.85rem; color:var(--neon-cyan)">(+$${extraYearlyProfit.toFixed(0)} USD al año)</span></div>
      <div style="font-size:0.7rem; color:var(--text-muted); margin-top:0.2rem">¡Ganas un +10.6% de ganancia neta extra sin cambiar tus precios!</div>
    </div>
  `;
}

function handleICalImportSubmit() {
  const urlInput = document.getElementById("ical-url-input");
  const nameInput = document.getElementById("ical-property-name");
  if (!urlInput || !nameInput) return;

  const icalUrl = urlInput.value.trim();
  const propertyName = nameInput.value.trim();

  if (!icalUrl || !propertyName) {
    showToast("Datos Faltantes", "Por favor ingresa el enlace iCal y el nombre de la propiedad.");
    return;
  }

  showToast("Sincronizando iCal...", "Analizando feed iCal de Airbnb/Vrbo...", 2000);

  setTimeout(() => {
    const newRental = {
      id: "stay-user-" + Date.now(),
      ownerId: appState.userProfile ? appState.userProfile.id : 'user-01',
      ownerName: appState.userProfile ? appState.userProfile.name : 'Usuario Anfitrión',
      ownerPhoto: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80",
      title: propertyName,
      propertyType: "apartment",
      district: "Noord",
      address: "Aruba Local Property",
      nightlyRateUsd: 150.00,
      localStaycationDiscountPct: 25.00,
      maxGuests: 4,
      bedrooms: 2,
      bathrooms: 1.0,
      images: ["https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80"],
      icalFeedUrl: icalUrl,
      rating: 5.0,
      reviewsCount: 1,
      amenities: ["iCal Auto-Sync", "WiFi", "Aire Acondicionado"],
      autoCleaningService: true,
      description: "Propiedad importada vía iCal con sincronización de calendario bidireccional activada."
    };

    appState.staysState.rentals.unshift(newRental);
    urlInput.value = "";
    nameInput.value = "";

    SoundEffects.playJingle();
    showToast("¡Anuncio Importado!", `La propiedad "${propertyName}" ha sido publicada en Sabí Stay con sincronización iCal activa.`);
    switchStaysSubTab('search');
    filterVacationRentals();
  }, 2000);
}

function renderTurnoversList() {
  const container = document.getElementById("turnovers-list-container");
  if (!container) return;

  const turnovers = appState.staysState.turnovers || [];
  if (turnovers.length === 0) {
    container.innerHTML = `<div style="color:var(--text-muted); font-size:0.85rem">No hay limpiezas pendientes de check-out.</div>`;
    return;
  }

  container.innerHTML = turnovers.map((item) => `
    <div style="background:rgba(255,255,255,0.03); border:1px solid var(--glass-border); border-radius:14px; padding:1rem; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:1rem">
      <div>
        <div style="font-size:0.9rem; font-weight:800; color:#fff">${item.propertyName}</div>
        <div style="font-size:0.75rem; color:var(--text-muted)">Check-out: <strong>${item.checkoutDate}</strong> • Huésped: ${item.guestName}</div>
        <div style="font-size:0.75rem; color:var(--neon-gold); margin-top:0.2rem">
          ${item.assignedDriver ? `✅ Asignado a: ${item.assignedDriver}` : '⏳ Pendiente de asignación de personal de limpieza local'}
        </div>
      </div>

      <div style="display:flex; gap:0.5rem; flex-wrap:wrap">
        <button onclick="dispatchCleaningService('${item.id}')" class="btn btn-sm btn-cyan" style="font-weight:700; font-size:0.75rem">
          🧹 Solicitar Limpieza Sabí
        </button>
        <button onclick="dispatchWelcomeGroceryBox('${item.id}')" class="btn btn-sm btn-secondary" style="font-weight:700; font-size:0.75rem">
          📦 Pedir Welcome Box Insumos
        </button>
      </div>
    </div>
  `).join('');
}

function dispatchCleaningService(turnoverId) {
  const turnover = (appState.staysState.turnovers || []).find(t => t.id === turnoverId);
  if (!turnover) return;

  turnover.assignedDriver = "María Gómez (Servicios Sabí Noord)";
  renderTurnoversList();

  SoundEffects.playClick();
  showToast("Limpieza Despachada", `Se ha asignado a María Gómez para la limpieza pre-checkin de ${turnover.propertyName}.`);
}

function dispatchWelcomeGroceryBox(turnoverId) {
  SoundEffects.playJingle();
  showToast("Canasta Solicitada", `Se ha generado un pedido de delivery de víveres iniciales para el próximo huésped.`);
}

