function handleCreatePropertySubmit() {
  const title = document.getElementById("prop-title").value.trim();
  const type = document.getElementById("prop-type").value;
  const district = document.getElementById("prop-district").value;
  const address = document.getElementById("prop-address").value.trim();
  const rate = parseFloat(document.getElementById("prop-rate").value) || 120;
  const discount = parseFloat(document.getElementById("prop-discount").value) || 25;
  const guests = parseInt(document.getElementById("prop-guests").value) || 2;
  const bedrooms = parseInt(document.getElementById("prop-bedrooms").value) || 1;
  const bathrooms = parseFloat(document.getElementById("prop-bathrooms").value) || 1;
  const image = document.getElementById("prop-image").value.trim() || "https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80";
  const desc = document.getElementById("prop-desc").value.trim();

  if (!title || !address || !desc) {
    showToast("Campos Faltantes", "Por favor completa el título, dirección y descripción.");
    return;
  }

  const modal = document.getElementById("new-property-modal");
  if (modal) modal.remove();

  const newProp = {
    id: "stay-owner-" + Date.now(),
    ownerId: appState.userProfile ? appState.userProfile.id : 'owner-local',
    ownerName: appState.userProfile ? appState.userProfile.name : 'Propietario Local',
    ownerPhoto: appState.userProfile ? appState.userProfile.photo : "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80",
    title: title,
    propertyType: type,
    district: district,
    address: address,
    nightlyRateUsd: rate,
    localStaycationDiscountPct: discount,
    maxGuests: guests,
    bedrooms: bedrooms,
    bathrooms: bathrooms,
    images: [image],
    rating: 5.0,
    reviewsCount: 1,
    amenities: ["WiFi HD", "Aire Acondicionado", "Cocineta"],
    autoCleaningService: true,
    description: desc
  };

  if (!appState.staysState.rentals) appState.staysState.rentals = [];
  appState.staysState.rentals.unshift(newProp);

  if (supabaseClient) {
    supabaseClient.auth.getSession().then(res => {
      if (res.data?.session?.user) {
        supabaseClient.from('vacation_rentals').insert({
          owner_id: res.data.session.user.id,
          title: title,
          property_type: type,
          description: desc,
          address: address,
          district: district,
          nightly_rate_usd: rate,
          local_staycation_discount_pct: discount,
          max_guests: guests,
          bedrooms: bedrooms,
          bathrooms: bathrooms,
          images: [image]
        }).then(r => {
          if (r.error) console.warn("Error inserting property to Supabase:", r.error.message);
        });
      }
    });
  }

  SoundEffects.playJingle();
  showToast("¡Propiedad Publicada!", `Tu inmueble "${title}" ya está disponible en Sabí Stay.`);
  switchStaysSubTab('search');
  filterVacationRentals();
}

