// ==================== SABI TIENDAS: SIMULADOR EN VIVO ====================
// Genera eventos fake (ventas, clicks PPC, cambios de stock) para que Mi Tienda
// muestre datos dinámicos sin necesidad de backend.
//
// HOOK (Supabase): reemplazar cada `sabiSimulator._fire*()` por un listener
// de Supabase Realtime que escuche cambios en `orders`, `ppc_events`, etc.
const sabiSimulator = {
  // Timer principal
  _saleTimer: null,
  _ppcTimer: null,
  _isRunning: false,

  // Configuración
  config: {
    saleIntervalMin: 30,    // segundos mínimos entre ventas
    saleIntervalMax: 90,    // segundos máximos
    ppcInterval:    20,     // PPC tick cada 20s
    saleNotificationMs: 4000 // duración del toast "¡Venta!"
  },

  start() {
    if (this._isRunning) return;
    this._isRunning = true;
    this._scheduleNextSale();
    this._schedulePpcTick();
    console.log('🟢 sabiSimulator: started');
  },

  stop() {
    if (this._saleTimer) clearTimeout(this._saleTimer);
    if (this._ppcTimer)  clearTimeout(this._ppcTimer);
    this._isRunning = false;
    console.log('🔴 sabiSimulator: stopped');
  },

  _scheduleNextSale() {
    const delay = (this.config.saleIntervalMin + Math.random() * (this.config.saleIntervalMax - this.config.saleIntervalMin)) * 1000;
    this._saleTimer = setTimeout(() => {
      this._fireSale();
      this._scheduleNextSale();
    }, delay);
  },

  _schedulePpcTick() {
    this._ppcTimer = setTimeout(() => {
      this._firePpcTick();
      this._schedulePpcTick();
    }, this.config.ppcInterval * 1000);
  },

  // HOOK (Supabase): reemplazar por `supabase.from('orders').on('INSERT', ...)`
  _fireSale() {
    const shop = appState.userShop || JSON.parse(localStorage.getItem('sabi_user_shop') || 'null');
    if (!shop) return;

    const myProducts = (appState.marketplaceAds || []).filter(ad => ad.shopId === shop.id && ad.active !== false && (ad.stock || 0) > 0);
    if (myProducts.length === 0) return;

    const product = myProducts[Math.floor(Math.random() * myProducts.length)];
    const qty = Math.min(Math.floor(Math.random() * 3) + 1, product.stock || 1);
    const gross = product.price * qty;
    const sabiFee = gross * SABI_COMMISSIONS.localSale;
    const net = gross - sabiFee;

    // 1. Bajar stock
    product.stock = (product.stock || 0) - qty;

    // 2. Actualizar shop totals
    shop.totalSales = (shop.totalSales || 0) + gross;
    shop.pendingPayout = (shop.pendingPayout || 0) + net;
    shop.lastSaleAt = new Date().toISOString();
    shop.lastSaleProduct = product.title;
    shop.lastSaleAmount = gross;

    // 3. Rating (sube un poquito con cada venta)
    shop.rating = Math.min(5.0, (shop.rating || 4.5) + 0.01);

    // 4. Registrar comisión al admin (antes se cobraba pero no se registraba)
    appState.adminEarnings = (appState.adminEarnings || 0) + sabiFee;
    localStorage.setItem('sabi_admin_earnings', appState.adminEarnings.toFixed(2));

    // 4b. Registrar ingreso bruto para el fondo social (1%)
    if (typeof recordSabíIncome === 'function') recordSabíIncome('sale', gross, sabiFee);

    // 5. Persistir
    localStorage.setItem('sabi_user_shop', JSON.stringify(shop));
    localStorage.setItem('sabi_marketplace_ads', JSON.stringify(appState.marketplaceAds));
    appState.userShop = shop;

    // 6. Capitalizar fondo de préstamos (50% de ganancias hasta 30k)
    if (typeof capitalizeLendingPool === 'function') {
      setTimeout(capitalizeLendingPool, 50);
    }

    // 7. Notificar visualmente
    showToast(`🛒 ¡Venta! +AWG ${gross.toFixed(2)}`, `${qty}× ${product.title} (Sabí cobró AWG ${sabiFee.toFixed(2)} de comisión)`);

    // 6. Refrescar vista si estamos en Mi Tienda
    if (appState.activeComunidadTab === 'mitienda') {
      this._refreshMitiendaView();
    }
  },

  // HOOK (Supabase): reemplazar por `supabase.from('ppc_events').on('INSERT', ...)`
  _firePpcTick() {
    const shop = appState.userShop || JSON.parse(localStorage.getItem('sabi_user_shop') || 'null');
    if (!shop) return;

    const activePpc = (appState.marketplaceAds || []).filter(ad => ad.shopId === shop.id && ad.ppcActive);
    if (activePpc.length === 0) return;

    // Simular 5-25 impressions y 0-2 clicks
    const impressions = Math.floor(Math.random() * 20) + 5;
    const clicks = Math.random() < 0.15 ? Math.floor(Math.random() * 2) + 1 : 0;
    const spend = impressions * 0.025; // AWG 0.025 por impression

    shop.ppcImpressions = (shop.ppcImpressions || 0) + impressions;
    shop.ppcClicks = (shop.ppcClicks || 0) + clicks;
    shop.ppcSpend = (shop.ppcSpend || 0) + spend;
    shop.lastPpcTickAt = new Date().toISOString();

    localStorage.setItem('sabi_user_shop', JSON.stringify(shop));
    appState.userShop = shop;

    // Refrescar silenciosamente si estamos en la tab PPC
    if (appState.activeComunidadTab === 'mitienda' && mitiendaActiveSubTab === 'marketing') {
      this._refreshMitiendaView();
    }
  },

  _refreshMitiendaView() {
    // Re-render solo el sub-tab activo (sin re-bind events)
    const shop = appState.userShop || {};
    document.getElementById('mitienda-name').textContent = shop.name || 'Mi Tienda';
    const productCount = (appState.marketplaceAds || []).filter(ad => ad.shopId === shop.id).length;
    document.getElementById('mitienda-stats').textContent =
      `${productCount} productos · ⭐ ${(shop.rating || 0).toFixed(1)} · AWG ${(shop.totalSales || 0).toFixed(2)} vendidos`;
    document.getElementById('mitienda-live-indicator').textContent =
      `🔴 En vivo · Última venta: ${shop.lastSaleAt ? this._timeAgo(shop.lastSaleAt) : '—'}`;
    renderMitiendaSubTab(mitiendaActiveSubTab);
  },

  _timeAgo(iso) {
    const diff = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
    if (diff < 60) return `hace ${diff}s`;
    if (diff < 3600) return `hace ${Math.floor(diff/60)}m`;
    return `hace ${Math.floor(diff/3600)}h`;
  }
};

// ==================== SABI: REVIEWS SYSTEM (Capa 1 - Schema) ====================
// Modelo de datos para reseñas con mecanismo de seguridad:
// - Verified purchase obligatorio (orderId)
// - Anti-duplicado via unique constraint en (targetId, authorId, orderId)
// - Anti-spam: ventana mínima entre reseñas
// - Reputación ponderada por trust score del autor
// - Reporte y soft-delete (auditoría preservada)
//
// HOOK (Supabase): crear tabla `reviews` con:
//   PRIMARY KEY (id), UNIQUE (target_id, author_id, order_id),
//   INDEX idx_reviews_target (target_id, type, hidden),
//   INDEX idx_reviews_author (author_id, created_at)
//   Y triggers para validar orderId existe + completed status
//
// Tipos de reseña: 'product' (comprador→producto), 'seller' (comprador→vendedor),
//                  'buyer'  (vendedor→comprador),   'driver' (usuario→chofer)

const SABI_REVIEWS_CONFIG = {
  // Ventana mínima entre reseñas del mismo author (anti-spam)
  minIntervalHours: 1,

  // Mínimo de palabras en el texto (anti-reviews vacías tipo "ok")
  minTextLength: 10,
  maxTextLength: 500,

  // Mínimo de reviews para que un rating se considere "estable"
  minReviewsForTrusted: 3,

  // Reportes antes de ocultar revisión para revisión admin
  reportThreshold: 3,

  // Trust score mínimo para que la reseña cuente como "verified"
  minAuthorTrustScore: 20,

  // Ventana para editar/eliminar la propia reseña (después es inmutable)
  editWindowHours: 24
};

function getAllReviews() {
  try { return JSON.parse(localStorage.getItem('sabi_reviews') || '[]'); }
  catch (e) { return []; }
}

function setAllReviews(arr) {
  localStorage.setItem('sabi_reviews', JSON.stringify(arr));
}

function getReviewsFor(targetId, type) {
  return getAllReviews().filter(r => r.targetId === targetId && r.type === type && !r.hidden);
}

// Crea una reseña validando TODAS las reglas de seguridad
function createReview(reviewData) {
  // Validación 1: datos completos
  if (!reviewData.targetId || !reviewData.type || !reviewData.authorId) {
    return { ok: false, error: 'Faltan datos requeridos (targetId, type, authorId).' };
  }
  if (!reviewData.orderId) {
    return { ok: false, error: 'Necesitás haber completado una compra para dejar una reseña (verified purchase).' };
  }
  if (!['product', 'seller', 'buyer', 'driver'].includes(reviewData.type)) {
    return { ok: false, error: 'Tipo de reseña inválido.' };
  }
  if (!Number.isInteger(reviewData.rating) || reviewData.rating < 1 || reviewData.rating > 5) {
    return { ok: false, error: 'Rating debe ser 1-5 estrellas.' };
  }
  const text = (reviewData.text || '').trim();
  if (text.length < SABI_REVIEWS_CONFIG.minTextLength) {
    return { ok: false, error: `La reseña debe tener al menos ${SABI_REVIEWS_CONFIG.minTextLength} caracteres.` };
  }
  if (text.length > SABI_REVIEWS_CONFIG.maxTextLength) {
    return { ok: false, error: `La reseña no puede tener más de ${SABI_REVIEWS_CONFIG.maxTextLength} caracteres.` };
  }

  // Validación 2: anti-duplicado
  const all = getAllReviews();
  const dup = all.find(r =>
    r.targetId === reviewData.targetId &&
    r.authorId === reviewData.authorId &&
    r.orderId === reviewData.orderId
  );
  if (dup) {
    return { ok: false, error: 'Ya dejaste una reseña para esta compra.' };
  }

  // Validación 3: anti-spam (ventana mínima)
  const myLast = all
    .filter(r => r.authorId === reviewData.authorId)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))[0];
  if (myLast) {
    const hoursSince = (Date.now() - new Date(myLast.createdAt).getTime()) / 3600000;
    if (hoursSince < SABI_REVIEWS_CONFIG.minIntervalHours) {
      return { ok: false, error: `Esperá ${SABI_REVIEWS_CONFIG.minIntervalHours}h entre reseñas.` };
    }
  }

  // Validación 4: orden existe y está completada
  const order = getOrderById(reviewData.orderId);
  if (!order) {
    return { ok: false, error: 'La orden no existe.' };
  }
  if (order.status !== 'completed') {
    return { ok: false, error: 'La orden no está completada todavía.' };
  }

  // Validación 5: el target coincide con la orden
  if (reviewData.type === 'product' && order.productId !== reviewData.targetId) {
    return { ok: false, error: 'El producto no coincide con la orden.' };
  }
  if (reviewData.type === 'seller' && order.sellerId !== reviewData.targetId) {
    return { ok: false, error: 'El vendedor no coincide con la orden.' };
  }
  if (reviewData.type === 'buyer' && order.buyerId !== reviewData.targetId) {
    return { ok: false, error: 'El comprador no coincide con la orden.' };
  }
  if (reviewData.type === 'driver' && order.driverId !== reviewData.targetId) {
    return { ok: false, error: 'El chofer no coincide con la orden.' };
  }

  // Crear reseña
  const review = {
    id: 'rev_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
    type: reviewData.type,
    targetId: reviewData.targetId,
    authorId: reviewData.authorId,
    orderId: reviewData.orderId,
    rating: reviewData.rating,
    text: text,
    pros: (reviewData.pros || '').slice(0, 60),
    cons: (reviewData.cons || '').slice(0, 60),
    photos: Array.isArray(reviewData.photos) ? reviewData.photos.slice(0, 4) : [],
    wouldRecommend: reviewData.wouldRecommend !== false,
    createdAt: new Date().toISOString(),
    reported: false,
    reportCount: 0,
    reportReasons: [],
    hidden: false,
    hiddenReason: null,
    authorTrustScore: calculateTrustScore(reviewData.authorId)
  };
  all.unshift(review);
  setAllReviews(all);

  // Actualizar rating agregado del target
  recalculateTargetRating(reviewData.targetId, reviewData.type);

  return { ok: true, review };
}

// Trust score del autor (0-100). Se calcula desde:
//   +1 por cada review dejada
//   +5 por cada mes de antigüedad en la plataforma
//   +10 si la cuenta está verificada (email/teléfono)
//   -10 por cada review reportada oculta
function calculateTrustScore(userId) {
  if (!userId) return 0;
  const reviews = getAllReviews();
  const myReviews = reviews.filter(r => r.authorId === userId);
  const profile = JSON.parse(localStorage.getItem('sabi_user_profile') || '{}');
  const accountAgeMonths = profile.createdAt
    ? Math.floor((Date.now() - new Date(profile.createdAt).getTime()) / (30 * 86400000))
    : 0;
  const verified = profile.verified ? 10 : 0;
  const hiddenMine = myReviews.filter(r => r.hidden).length * 10;
  return Math.max(0, Math.min(100, myReviews.length + accountAgeMonths * 5 + verified - hiddenMine));
}

// Recalcula el rating promedio + count del target y lo guarda
function recalculateTargetRating(targetId, type) {
  const reviews = getReviewsFor(targetId, type);
  if (reviews.length === 0) return { avg: 0, count: 0 };
  const sum = reviews.reduce((s, r) => s + r.rating, 0);
  const avg = sum / reviews.length;
  const result = { avg: Math.round(avg * 10) / 10, count: reviews.length };

  // Persistir según el tipo
  if (type === 'product') {
    const ad = appState.marketplaceAds.find(a => a.id === targetId);
    if (ad) { ad.rating = result.avg; ad.reviewCount = result.count; localStorage.setItem('sabi_marketplace_ads', JSON.stringify(appState.marketplaceAds)); }
  } else if (type === 'seller' || type === 'shop') {
    const shop = (appState.userShop && appState.userShop.id === targetId) ? appState.userShop
                : JSON.parse(localStorage.getItem('sabi_user_shop') || 'null');
    if (shop && shop.id === targetId) { shop.rating = result.avg; shop.reviewCount = result.count; localStorage.setItem('sabi_user_shop', JSON.stringify(shop)); }
  } else if (type === 'driver') {
    // Guardar en drivers store
    const drivers = JSON.parse(localStorage.getItem('sabi_registered_drivers') || '[]');
    const d = drivers.find(x => x.id === targetId);
    if (d) { d.rating = result.avg; d.reviewCount = result.count; localStorage.setItem('sabi_registered_drivers', JSON.stringify(drivers)); }
  } else if (type === 'buyer') {
    // Guardar en user_profiles store
    const profiles = JSON.parse(localStorage.getItem('sabi_all_profiles') || '{}');
    if (profiles[targetId]) { profiles[targetId].rating = result.avg; profiles[targetId].reviewCount = result.count; localStorage.setItem('sabi_all_profiles', JSON.stringify(profiles)); }
  }
  return result;
}

// Reportar una reseña (anti-fraude colaborativo)
function reportReview(reviewId, reason) {
  const all = getAllReviews();
  const r = all.find(x => x.id === reviewId);
  if (!r) return { ok: false, error: 'Reseña no encontrada.' };
  r.reportCount = (r.reportCount || 0) + 1;
  r.reportReasons = r.reportReasons || [];
  r.reportReasons.push({ reason, reportedAt: new Date().toISOString(), reporterId: appState.userProfile?.id || 'anonymous' });
  if (r.reportCount >= SABI_REVIEWS_CONFIG.reportThreshold && !r.hidden) {
    r.hidden = true;
    r.hiddenReason = `Auto-ocultada por ${r.reportCount} reportes`;
  }
  setAllReviews(all);
  recalculateTargetRating(r.targetId, r.type);
  return { ok: true, hidden: r.hidden };
}

// Editar reseña propia (solo dentro de la ventana de edición)
function editReview(reviewId, updates) {
  const all = getAllReviews();
  const idx = all.findIndex(x => x.id === reviewId);
  if (idx === -1) return { ok: false, error: 'Reseña no encontrada.' };
  const r = all[idx];
  if (r.authorId !== (appState.userProfile?.id || 'me')) {
    return { ok: false, error: 'Solo podés editar tus propias reseñas.' };
  }
  const hoursOld = (Date.now() - new Date(r.createdAt).getTime()) / 3600000;
  if (hoursOld > SABI_REVIEWS_CONFIG.editWindowHours) {
    return { ok: false, error: 'La ventana de edición expiró. Las reseñas son inmutables.' };
  }
  // Validar campos editables
  if (updates.rating !== undefined) {
    if (!Number.isInteger(updates.rating) || updates.rating < 1 || updates.rating > 5) {
      return { ok: false, error: 'Rating inválido.' };
    }
    r.rating = updates.rating;
  }
  if (updates.text !== undefined) {
    const t = updates.text.trim();
    if (t.length < SABI_REVIEWS_CONFIG.minTextLength) return { ok: false, error: 'Texto muy corto.' };
    r.text = t;
  }
  if (updates.pros !== undefined) r.pros = updates.pros.slice(0, 60);
  if (updates.cons !== undefined) r.cons = updates.cons.slice(0, 60);
  r.editedAt = new Date().toISOString();
  all[idx] = r;
  setAllReviews(all);
  recalculateTargetRating(r.targetId, r.type);
  return { ok: true, review: r };
}

// Eliminar reseña propia (solo dentro de la ventana)
function deleteReview(reviewId) {
  const all = getAllReviews();
  const idx = all.findIndex(x => x.id === reviewId);
  if (idx === -1) return { ok: false, error: 'Reseña no encontrada.' };
  const r = all[idx];
  if (r.authorId !== (appState.userProfile?.id || 'me')) {
    return { ok: false, error: 'Solo podés eliminar tus propias reseñas.' };
  }
  const hoursOld = (Date.now() - new Date(r.createdAt).getTime()) / 3600000;
  if (hoursOld > SABI_REVIEWS_CONFIG.editWindowHours) {
    return { ok: false, error: 'La ventana de borrado expiró. Contactá a soporte.' };
  }
  all.splice(idx, 1);
  setAllReviews(all);
  recalculateTargetRating(r.targetId, r.type);
  return { ok: true };
}

// ==================== SABI: REVIEWS UI (Capa 2) ====================
// Componentes visuales: modal de reseña, review card, review list, botones de reporte/edición

// Modal para dejar reseña (estrellas + texto + pros/cons + fotos)
function openReviewModal(targetId, type, orderId, targetName) {
  let existing = document.getElementById('review-modal');
  if (existing) existing.remove();

  const modal = document.createElement('div');
  modal.id = 'review-modal';
  modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:10000; display:flex; align-items:center; justify-content:center; padding:1rem; backdrop-filter:blur(8px);';

  modal.innerHTML = `
    <div style="background:#130e2c; border:1px solid var(--neon-cyan); border-radius:18px; padding:1.5rem; max-width:520px; width:100%; max-height:90vh; overflow-y:auto; box-shadow:0 0 40px rgba(0,245,212,0.3)">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:1rem">
        <h3 style="margin:0; color:var(--neon-cyan)">⭐ Dejar reseña</h3>
        <button id="rv-close" style="background:none; border:none; color:var(--text-muted); font-size:1.5rem; cursor:pointer">×</button>
      </div>
      <div style="background:rgba(81,207,102,0.08); border:1px solid #51cf66; border-radius:8px; padding:0.65rem 0.85rem; font-size:0.78rem; color:#51cf66; margin-bottom:1rem">
        ✅ <strong>Compra verificada</strong> · Tu reseña solo puede ser sobre una compra real completada
      </div>
      <p style="color:var(--text-muted); font-size:0.85rem; margin:0 0 1rem">Reseñando: <strong style="color:var(--text-main)">${escapeHtml(targetName || 'target')}</strong></p>

      <form id="rv-form">
        <label style="display:block; font-size:0.8rem; color:var(--text-muted); margin-bottom:0.5rem">Tu calificación *</label>
        <div id="rv-stars" style="display:flex; gap:0.5rem; margin-bottom:1rem; font-size:2rem; cursor:pointer">
          ${[1, 2, 3, 4, 5].map(n => `<span data-star="${n}" style="color:#444; transition:color 0.15s">★</span>`).join('')}
        </div>
        <input type="hidden" id="rv-rating" required value="0" />

        <label style="display:block; font-size:0.8rem; color:var(--text-muted); margin-bottom:0.3rem">Tu reseña (mín 10 caracteres) *</label>
        <textarea id="rv-text" rows="3" required minlength="10" maxlength="500" placeholder="Contá tu experiencia honesta. ¿Qué te gustó? ¿Qué podría mejorar?" style="width:100%; padding:0.7rem; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.15); border-radius:8px; color:var(--text-main); font-family:inherit; font-size:0.9rem; margin-bottom:0.5rem; resize:vertical"></textarea>
        <div style="display:flex; justify-content:space-between; font-size:0.7rem; color:var(--text-muted); margin-bottom:0.85rem">
          <span>Sé específico y respetuoso</span>
          <span><span id="rv-char-count">0</span> / 500</span>
        </div>

        <div style="display:grid; grid-template-columns:1fr 1fr; gap:0.5rem; margin-bottom:0.85rem">
          <div>
            <label style="display:block; font-size:0.78rem; color:#51cf66; margin-bottom:0.3rem">👍 Pros (opcional)</label>
            <input type="text" id="rv-pros" maxlength="60" placeholder="Lo mejor..." style="width:100%; padding:0.55rem 0.7rem; background:rgba(81,207,102,0.05); border:1px solid rgba(81,207,102,0.3); border-radius:6px; color:var(--text-main); font-family:inherit; font-size:0.85rem" />
          </div>
          <div>
            <label style="display:block; font-size:0.78rem; color:#ff6b6b; margin-bottom:0.3rem">👎 Contras (opcional)</label>
            <input type="text" id="rv-cons" maxlength="60" placeholder="A mejorar..." style="width:100%; padding:0.55rem 0.7rem; background:rgba(255,107,107,0.05); border:1px solid rgba(255,107,107,0.3); border-radius:6px; color:var(--text-main); font-family:inherit; font-size:0.85rem" />
          </div>
        </div>

        <label style="display:flex; align-items:center; gap:0.5rem; font-size:0.9rem; cursor:pointer; margin-bottom:0.85rem">
          <input type="checkbox" id="rv-recommend" checked style="width:18px; height:18px" />
          👍 Recomiendo este ${type === 'product' ? 'producto' : type === 'driver' ? 'chofer' : type === 'seller' ? 'vendedor' : 'comprador'}
        </label>

        <div style="background:rgba(255,224,0,0.08); border:1px solid var(--neon-gold); border-radius:8px; padding:0.65rem; font-size:0.75rem; color:var(--neon-gold); margin-bottom:1rem">
          💡 Tu reseña es pública. Podés editarla o eliminarla en las próximas ${SABI_REVIEWS_CONFIG.editWindowHours}h, después será inmutable.
        </div>

        <div style="display:flex; gap:0.75rem; justify-content:flex-end">
          <button type="button" class="btn-secondary" id="rv-cancel">Cancelar</button>
          <button type="submit" class="cta-button" id="rv-submit">📤 Publicar reseña</button>
        </div>
      </form>
    </div>
  `;
  document.body.appendChild(modal);

  // Star interaction
  let selectedRating = 0;
  const stars = document.querySelectorAll('#rv-stars span');
  const updateStars = (n, hover = false) => {
    stars.forEach(s => {
      const star = parseInt(s.dataset.star);
      s.style.color = star <= n ? 'var(--neon-gold)' : '#444';
      s.style.textShadow = star <= n ? '0 0 8px rgba(255,224,0,0.6)' : 'none';
    });
  };
  stars.forEach(s => {
    s.onmouseenter = () => updateStars(parseInt(s.dataset.star), true);
    s.onmouseleave = () => updateStars(selectedRating);
    s.onclick = () => {
      selectedRating = parseInt(s.dataset.star);
      document.getElementById('rv-rating').value = selectedRating;
      updateStars(selectedRating);
    };
  });

  // Char counter
  const textArea = document.getElementById('rv-text');
  textArea.oninput = () => {
    document.getElementById('rv-char-count').textContent = textArea.value.length;
  };

  // Submit
  const cleanup = () => modal.remove();
  document.getElementById('rv-close').onclick  = cleanup;
  document.getElementById('rv-cancel').onclick = cleanup;
  document.getElementById('rv-form').onsubmit = (e) => {
    e.preventDefault();
    const rating = parseInt(document.getElementById('rv-rating').value);
    if (rating === 0) { showToast('⚠️ Falta rating', 'Seleccioná entre 1 y 5 estrellas.'); return; }
    const result = createReview({
      targetId, type,
      orderId,
      authorId: appState.userProfile?.id || 'me',
      rating,
      text: textArea.value.trim(),
      pros: document.getElementById('rv-pros').value.trim(),
      cons: document.getElementById('rv-cons').value.trim(),
      wouldRecommend: document.getElementById('rv-recommend').checked
    });
    if (!result.ok) { showToast('❌ Error', result.error); return; }
    showToast('✅ ¡Reseña publicada!', 'Gracias por tu feedback honesto.');
    cleanup();
    // Re-render la lista si está visible
    const list = document.getElementById(`reviews-list-${targetId}-${type}`);
    if (list) list.innerHTML = renderReviewList(targetId, type);
  };
}

// Renderizar una review card (reutilizable)
function renderReviewCard(review) {
  const date = new Date(review.createdAt);
  const dateStr = date.toLocaleDateString('es-AW', { day: 'numeric', month: 'short', year: 'numeric' });
  const stars = '★★★★★'.slice(0, review.rating) + '☆☆☆☆☆'.slice(0, 5 - review.rating);
  const isOwn = review.authorId === (appState.userProfile?.id || 'me');
  const hoursOld = (Date.now() - date.getTime()) / 3600000;
  const canEdit = isOwn && hoursOld < SABI_REVIEWS_CONFIG.editWindowHours;
  const trustBadge = review.authorTrustScore >= SABI_REVIEWS_CONFIG.minAuthorTrustScore
    ? `<span title="Trust score ${review.authorTrustScore}/100" style="background:rgba(81,207,102,0.15); color:#51cf66; padding:0.1rem 0.4rem; border-radius:6px; font-size:0.65rem; font-weight:600">✓ Confiable</span>`
    : '';
  const recommendBadge = review.wouldRecommend ? `<span style="background:rgba(0,245,212,0.1); color:var(--neon-cyan); padding:0.1rem 0.4rem; border-radius:6px; font-size:0.65rem; font-weight:600">👍 Recomienda</span>` : '';
  const editedBadge = review.editedAt ? `<span style="color:var(--text-muted); font-size:0.65rem; font-style:italic" title="${new Date(review.editedAt).toLocaleString('es-AW')}">(editada)</span>` : '';

  return `
    <div style="background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.08); border-radius:10px; padding:0.85rem; margin-bottom:0.6rem">
      <div style="display:flex; align-items:center; gap:0.5rem; margin-bottom:0.4rem; flex-wrap:wrap">
        <div style="color:var(--neon-gold); font-size:0.95rem; letter-spacing:2px">${stars}</div>
        <div style="font-size:0.75rem; color:var(--text-muted)">${dateStr}</div>
        ${trustBadge}
        ${recommendBadge}
        ${editedBadge}
      </div>
      <div style="font-size:0.9rem; line-height:1.5; margin-bottom:0.5rem">${escapeHtml(review.text)}</div>
      ${(review.pros || review.cons) ? `
      <div style="display:flex; gap:0.75rem; font-size:0.78rem; margin-bottom:0.5rem">
        ${review.pros ? `<div style="flex:1; padding:0.4rem 0.6rem; background:rgba(81,207,102,0.05); border-left:2px solid #51cf66; border-radius:4px"><strong style="color:#51cf66">👍</strong> ${escapeHtml(review.pros)}</div>` : ''}
        ${review.cons ? `<div style="flex:1; padding:0.4rem 0.6rem; background:rgba(255,107,107,0.05); border-left:2px solid #ff6b6b; border-radius:4px"><strong style="color:#ff6b6b">👎</strong> ${escapeHtml(review.cons)}</div>` : ''}
      </div>` : ''}
      ${review.photos && review.photos.length > 0 ? `
      <div style="display:flex; gap:0.4rem; margin-bottom:0.5rem">
        ${review.photos.map(p => `<img src="${p}" style="width:60px; height:60px; object-fit:cover; border-radius:6px; border:1px solid rgba(255,255,255,0.1)" />`).join('')}
      </div>` : ''}
      <div style="display:flex; gap:0.5rem; align-items:center; padding-top:0.4rem; border-top:1px solid rgba(255,255,255,0.05); font-size:0.75rem">
        ${canEdit ? `<button class="btn-secondary" style="font-size:0.7rem; padding:0.2rem 0.5rem" onclick="editOwnReview('${review.id}', '${review.targetId}', '${review.type}')">✏️ Editar</button><button class="btn-secondary" style="font-size:0.7rem; padding:0.2rem 0.5rem; color:#ff6b6b" onclick="deleteOwnReview('${review.id}', '${review.targetId}', '${review.type}')">🗑️</button>` : ''}
        <button class="btn-secondary" style="font-size:0.7rem; padding:0.2rem 0.5rem; color:#ff6b6b; margin-left:auto" onclick="openReportModal('${review.id}')">⚠️ Reportar</button>
      </div>
    </div>
  `;
}

// Renderizar lista de reseñas para un target
function renderReviewList(targetId, type) {
  const reviews = getReviewsFor(targetId, type);
  if (reviews.length === 0) {
    return `<p style="color:var(--text-muted); text-align:center; padding:1.5rem; font-size:0.85rem">Aún no hay reseñas. ¡Sé el primero en dejar tu opinión!</p>`;
  }
  // Ordenar: más recientes primero
  const sorted = [...reviews].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  return sorted.map(renderReviewCard).join('');
}

// Header con stats agregados (rating promedio + distribución)
function renderReviewSummary(targetId, type) {
  const reviews = getReviewsFor(targetId, type);
  if (reviews.length === 0) return '';
  const avg = reviews.reduce((s, r) => s + r.rating, 0) / reviews.length;
  const dist = [5, 4, 3, 2, 1].map(stars => ({
    stars,
    count: reviews.filter(r => r.rating === stars).length,
    pct: (reviews.filter(r => r.rating === stars).length / reviews.length) * 100
  }));
  const recommendPct = (reviews.filter(r => r.wouldRecommend).length / reviews.length) * 100;
  return `
    <div style="background:rgba(0,245,212,0.05); border:1px solid var(--neon-cyan); border-radius:12px; padding:1rem; margin-bottom:1rem">
      <div style="display:grid; grid-template-columns:auto 1fr; gap:1rem; align-items:center">
        <div style="text-align:center">
          <div style="font-size:2.5rem; font-weight:700; color:var(--neon-gold); line-height:1">${avg.toFixed(1)}</div>
          <div style="color:var(--neon-gold); font-size:1.1rem; letter-spacing:2px">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5 - Math.round(avg))}</div>
          <div style="font-size:0.75rem; color:var(--text-muted); margin-top:0.25rem">${reviews.length} reseña${reviews.length !== 1 ? 's' : ''}</div>
        </div>
        <div>
          ${dist.map(d => `
            <div style="display:flex; align-items:center; gap:0.5rem; font-size:0.78rem; margin-bottom:0.2rem">
              <span style="width:30px; color:var(--neon-gold)">${d.stars}★</span>
              <div style="flex:1; height:6px; background:rgba(255,255,255,0.05); border-radius:3px; overflow:hidden">
                <div style="height:100%; background:linear-gradient(90deg, var(--neon-gold), var(--neon-cyan)); width:${d.pct}%"></div>
              </div>
              <span style="width:30px; text-align:right; color:var(--text-muted)">${d.count}</span>
            </div>
          `).join('')}
        </div>
      </div>
      ${recommendPct > 0 ? `<div style="text-align:center; margin-top:0.75rem; padding-top:0.75rem; border-top:1px solid rgba(255,255,255,0.08); font-size:0.85rem"><strong style="color:#51cf66">${recommendPct.toFixed(0)}%</strong> recomienda</div>` : ''}
    </div>
  `;
}

// Modal de reporte de reseña
function openReportModal(reviewId) {
  let existing = document.getElementById('report-modal');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'report-modal';
  modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:10001; display:flex; align-items:center; justify-content:center; padding:1rem; backdrop-filter:blur(8px);';
  modal.innerHTML = `
    <div style="background:#130e2c; border:1px solid #ff6b6b; border-radius:18px; padding:1.5rem; max-width:440px; width:100%; box-shadow:0 0 40px rgba(255,107,107,0.3)">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:1rem">
        <h3 style="margin:0; color:#ff6b6b">⚠️ Reportar reseña</h3>
        <button id="rm-close" style="background:none; border:none; color:var(--text-muted); font-size:1.5rem; cursor:pointer">×</button>
      </div>
      <p style="font-size:0.85rem; color:var(--text-muted); margin-bottom:1rem">¿Por qué querés reportar esta reseña? Tu reporte es anónimo.</p>
      <form id="rm-form">
        <select id="rm-reason" required style="width:100%; padding:0.7rem; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.15); border-radius:8px; color:var(--text-main); font-family:inherit; font-size:0.9rem; margin-bottom:0.85rem">
          <option value="spam">Spam o publicidad</option>
          <option value="false_info">Información falsa</option>
          <option value="offensive">Lenguaje ofensivo</option>
          <option value="not_buyer">No compró el producto</option>
          <option value="competitor">Reseña de competencia</option>
          <option value="other">Otro</option>
        </select>
        <textarea id="rm-notes" rows="2" maxlength="200" placeholder="Detalles adicionales (opcional)" style="width:100%; padding:0.65rem; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.15); border-radius:8px; color:var(--text-main); font-family:inherit; font-size:0.85rem; margin-bottom:0.85rem; resize:vertical"></textarea>
        <div style="background:rgba(255,255,255,0.03); border-radius:8px; padding:0.65rem; font-size:0.75rem; color:var(--text-muted); margin-bottom:1rem">
          Si esta reseña recibe ${SABI_REVIEWS_CONFIG.reportThreshold} reportes, se ocultará automáticamente para revisión del equipo Sabí.
        </div>
        <div style="display:flex; gap:0.75rem; justify-content:flex-end">
          <button type="button" class="btn-secondary" id="rm-cancel">Cancelar</button>
          <button type="submit" class="cta-button" style="background:linear-gradient(135deg, #ff6b6b, #cc4444); color:#fff">Enviar reporte</button>
        </div>
      </form>
    </div>
  `;
  document.body.appendChild(modal);
  const cleanup = () => modal.remove();
  document.getElementById('rm-close').onclick  = cleanup;
  document.getElementById('rm-cancel').onclick = cleanup;
  document.getElementById('rm-form').onsubmit = (e) => {
    e.preventDefault();
    const reason = document.getElementById('rm-reason').value;
    const notes = document.getElementById('rm-notes').value.trim();
    const fullReason = notes ? `${reason}: ${notes}` : reason;
    const result = reportReview(reviewId, fullReason);
    if (result.ok) {
      showToast(result.hidden ? '⚠️ Reseña ocultada' : '✅ Reporte enviado', result.hidden ? 'Recibió suficientes reportes. Será revisada.' : 'El equipo Sabí la revisará.');
    } else {
      showToast('❌ Error', result.error);
    }
    cleanup();
    // Re-render visible list
    const allReviews = getAllReviews();
    allReviews.forEach(r => {
      const list = document.getElementById(`reviews-list-${r.targetId}-${r.type}`);
      if (list) list.innerHTML = renderReviewList(r.targetId, r.type);
    });
  };
}

// Editar reseña propia
function editOwnReview(reviewId, targetId, type) {
  const all = getAllReviews();
  const r = all.find(x => x.id === reviewId);
  if (!r) return;
  // Reusar el modal pero precargado
  openReviewModal(targetId, type, r.orderId, 'Editar reseña');
  setTimeout(() => {
    document.getElementById('rv-rating').value = r.rating;
    document.querySelectorAll('#rv-stars span').forEach(s => {
      const star = parseInt(s.dataset.star);
      s.style.color = star <= r.rating ? 'var(--neon-gold)' : '#444';
    });
    document.getElementById('rv-text').value = r.text;
    document.getElementById('rv-char-count').textContent = r.text.length;
    document.getElementById('rv-pros').value = r.pros || '';
    document.getElementById('rv-cons').value = r.cons || '';
    document.getElementById('rv-recommend').checked = r.wouldRecommend;
    // Cambiar el handler de submit
    document.getElementById('rv-form').onsubmit = (e) => {
      e.preventDefault();
      const updates = {
        rating: parseInt(document.getElementById('rv-rating').value),
        text: document.getElementById('rv-text').value.trim(),
        pros: document.getElementById('rv-pros').value.trim(),
        cons: document.getElementById('rv-cons').value.trim()
      };
      const result = editReview(reviewId, updates);
      if (!result.ok) { showToast('❌ Error', result.error); return; }
      showToast('✅ Reseña actualizada', '');
      document.getElementById('review-modal').remove();
      const list = document.getElementById(`reviews-list-${targetId}-${type}`);
      if (list) list.innerHTML = renderReviewList(targetId, type);
    };
  }, 100);
}

// Eliminar reseña propia
function deleteOwnReview(reviewId, targetId, type) {
  if (!confirm('¿Eliminar tu reseña? Esta acción no se puede deshacer.')) return;
  const result = deleteReview(reviewId);
  if (!result.ok) { showToast('❌ Error', result.error); return; }
  showToast('🗑️ Reseña eliminada', '');
  const list = document.getElementById(`reviews-list-${targetId}-${type}`);
  if (list) list.innerHTML = renderReviewList(targetId, type);
}

// Helper: encontrar una orden completada del usuario para un target específico
function findCompletedOrderFor(targetId, type) {
  const myId = appState.userProfile?.id || 'me';
  return getAllOrders().find(o => {
    if (o.buyerId !== myId || o.status !== 'completed') return false;
    if (type === 'product' && o.productId === targetId) return true;
    if (type === 'seller'  && o.sellerId  === targetId) return true;
    if (type === 'driver'  && o.driverId  === targetId) return true;
    return false;
  });
}

// Componente principal: muestra lista + botón "Dejar reseña" si el usuario puede
function renderReviewsSection(targetId, type, targetName) {
  const order = findCompletedOrderFor(targetId, type);
  const myId = appState.userProfile?.id || 'me';
  const alreadyReviewed = order && getAllReviews().some(r => r.targetId === targetId && r.authorId === myId && r.orderId === order.id);

  return `
    <div style="margin-top:1.5rem">
      <h4 style="margin:0 0 0.75rem; color:var(--neon-cyan)">⭐ Reseñas</h4>
      ${renderReviewSummary(targetId, type)}
      <div id="reviews-list-${targetId}-${type}">
        ${renderReviewList(targetId, type)}
      </div>
      <div style="margin-top:1rem">
        ${order
          ? (alreadyReviewed
              ? `<p style="text-align:center; color:var(--text-muted); font-size:0.85rem">✓ Ya dejaste tu reseña para esta compra</p>`
              : `<button class="cta-button" style="width:100%" onclick="openReviewModal('${targetId}', '${type}', '${order.id}', '${escapeHtml(targetName)}')">⭐ Dejar reseña</button>`)
          : `<p style="text-align:center; color:var(--text-muted); font-size:0.8rem; padding:0.75rem; background:rgba(255,255,255,0.03); border-radius:8px">🔒 Solo podés dejar reseña después de una compra verificada</p>`
        }
      </div>
    </div>
  `;
}

// ==================== SABI: REVIEWS — CAPA 3 (Doble ciego + Disputas + Sort) ====================

// ── Doble ciego ──────────────────────────────────────────────────────────
// Una reseña "doble ciego" no se hace pública hasta que la contraparte
// también dejó su reseña, O pasaron 14 días. Esto previene represalias:
// "te dejo 1 estrella si me dejás 1 estrella".

const SABI_BLIND_CONFIG = {
  windowDays: 14,            // Días máximos de espera
  notifyOnExpiry: true        // Notificar al otro lado cuando se libera
};

// Estado de "pending" → "revealed" para reseñas doble ciego
function getBlindState(orderId) {
  try { return JSON.parse(localStorage.getItem(`sabi_blind_${orderId}`) || '{}'); }
  catch (e) { return {}; }
}

function setBlindState(orderId, state) {
  localStorage.setItem(`sabi_blind_${orderId}`, JSON.stringify(state));
}

// Determina si una reseña es doble ciego según la orden
function isBlindReview(order) {
  if (!order) return false;
  // Doble ciego: cuando vendedor y comprador se reseñan mutuamente
  return (order.status === 'completed') &&
         // Solo órdenes donde hay relación bilateral (product + seller)
         (order.productId && order.sellerId && order.buyerId);
}

// Crear reseña doble ciego: guarda la reseña, pero la marca como "pending"
// hasta que la contraparte también reseñe (o expire el window)
function createBlindReview(reviewData) {
  const order = getOrderById(reviewData.orderId);
  if (!order) return { ok: false, error: 'Orden no encontrada.' };

  // Crear la reseña normalmente (con todas las validaciones)
  const result = createReview(reviewData);
  if (!result.ok) return result;

  if (!isBlindReview(order)) return result; // no aplica doble ciego

  // Marcar como pending en blind state
  const blind = getBlindState(order.id);
  blind[reviewData.authorId] = { reviewId: result.review.id, createdAt: new Date().toISOString() };
  blind.createdAt = blind.createdAt || new Date().toISOString();
  setBlindState(order.id, blind);

  // Si la contraparte ya tiene reseña pendiente, revelar ambas
  tryRevealBlindReviews(order);

  // Programar auto-reveal al expiry
  setTimeout(() => tryRevealBlindReviews(order, true), 1000);

  return { ok: true, review: result.review, blindPending: true };
}

// Intenta revelar las reseñas doble ciego (cuando ambas existen o expira el plazo)
function tryRevealBlindReviews(order, forceExpire = false) {
  if (!isBlindReview(order)) return;
  const blind = getBlindState(order.id);
  if (!blind.createdAt) return;

  const createdAt = new Date(blind.createdAt);
  const daysSince = (Date.now() - createdAt.getTime()) / 86400000;
  const expired = daysSince >= SABI_BLIND_CONFIG.windowDays;

  if (forceExpire || expired) {
    // Reveal todas las reseñas pendientes de esta orden
    const all = getAllReviews();
    all.forEach(r => {
      if (r.orderId === order.id && r.hidden) r.hidden = false;
    });
    setAllReviews(all);
    setBlindState(order.id, { ...blind, revealed: true, revealedAt: new Date().toISOString(), reason: expired ? 'expired' : 'both_published' });
  } else {
    // Si ambos lados (buyer y seller) ya dejaron reseña, revelar
    const hasBuyer  = blind[order.buyerId];
    const hasSeller = blind[order.sellerId];
    if (hasBuyer && hasSeller) {
      const all = getAllReviews();
      all.forEach(r => {
        if (r.orderId === order.id && r.hidden) r.hidden = false;
      });
      setAllReviews(all);
      setBlindState(order.id, { ...blind, revealed: true, revealedAt: new Date().toISOString(), reason: 'both_published' });
    }
  }
}

// Crear reseña con soporte para doble ciego (wrapper)
function createReviewWithBlind(reviewData) {
  return createBlindReview(reviewData);
}

// ── Disputas ─────────────────────────────────────────────────────────────
// Si una reseña es reportada N veces o tiene rating 1-2 con texto ofensivo,
// se abre un ticket de disputa que va al panel admin.

const SABI_DISPUTES_KEY = 'sabi_disputes';

function getAllDisputes() {
  try { return JSON.parse(localStorage.getItem(SABI_DISPUTES_KEY) || '[]'); }
  catch (e) { return []; }
}

function setAllDisputes(arr) {
  localStorage.setItem(SABI_DISPUTES_KEY, JSON.stringify(arr));
}

function openDispute(targetId, type, reason, evidence) {
  const myId = appState.userProfile?.id || 'me';
  const dispute = {
    id: 'dsp_' + Date.now(),
    targetId, type, reason,
    evidence: evidence || '',     // Texto/url de evidencia
    openedBy: myId,
    openedAt: new Date().toISOString(),
    status: 'open',               // open → investigating → resolved
    resolution: null,
    resolvedBy: null,
    resolvedAt: null
  };
  const all = getAllDisputes();
  all.unshift(dispute);
  setAllDisputes(all);
  return dispute;
}

// Auto-apertura de disputa cuando una reseña es oculta por reportes
function autoOpenDisputeForReview(review) {
  if (!review.hidden) return;
  openDispute(
    review.targetId,
    `${review.type}_review_#${review.id}`,
    `Reseña ocultada por ${review.reportCount} reportes`,
    `Reportes: ${(review.reportReasons || []).map(r => r.reason).join(' | ')}`
  );
}

// ── Sort por rating con peso de confianza ───────────────────────────────
// El "sort" en marketplace/verticales no debe ser solo por avg rating.
// Tiene que pesar:
//   - Promedio de reseñas (50%)
//   - Cantidad de reseñas (30%) - "Ley de los grandes números"
//   - Recencia (10%) - Reseñas recientes pesan más
//   - Trust score del autor promedio (10%)
function calculateWeightedRating(targetId, type) {
  const reviews = getReviewsFor(targetId, type);
  if (reviews.length === 0) return { score: 0, avg: 0, count: 0 };
  const avg = reviews.reduce((s, r) => s + r.rating, 0) / reviews.length;

  // Cantidad: Bayesian shrinkage hacia 3.5 (rating promedio neutral)
  // m = 5 (mínimo de reviews para confiar)
  const m = 5;
  const globalAvg = 3.5;
  const bayesian = (reviews.length / (reviews.length + m)) * avg + (m / (reviews.length + m)) * globalAvg;

  // Recencia: boost a reseñas de los últimos 90 días
  const now = Date.now();
  const recencyBoost = reviews.filter(r => (now - new Date(r.createdAt).getTime()) < 90 * 86400000).length / reviews.length;

  // Trust score promedio
  const trustAvg = reviews.reduce((s, r) => s + (r.authorTrustScore || 50), 0) / reviews.length;

  // Score compuesto (0-5)
  const score = (bayesian * 0.6) + (recencyBoost * 0.2 * 5) + ((trustAvg / 100) * 0.2 * 5);

  return { score: Math.round(score * 10) / 10, avg, count: reviews.length };
}

// ── Página "Mis reseñas" (perfil del usuario) ────────────────────────────
function renderMyReviewsSection() {
  const myId = appState.userProfile?.id || 'me';
  const all = getAllReviews();
  const mine = all.filter(r => r.authorId === myId && !r.hidden);
  const aboutMe = all.filter(r => r.targetId === myId && r.type === 'buyer' && !r.hidden);

  return `
    <div style="display:grid; grid-template-columns:1fr 1fr; gap:1rem; margin-bottom:1rem">
      <div class="card-mini" style="text-align:center">
        <div style="font-size:0.75rem; color:var(--text-muted)">Reseñas que dejé</div>
        <div style="font-size:1.5rem; color:var(--neon-cyan)">${mine.length}</div>
      </div>
      <div class="card-mini" style="text-align:center">
        <div style="font-size:0.75rem; color:var(--text-muted)">Reseñas sobre mí</div>
        <div style="font-size:1.5rem; color:var(--neon-cyan)">${aboutMe.length}</div>
      </div>
    </div>
    ${mine.length > 0 ? `
    <h4 style="margin:0.5rem 0; color:var(--neon-cyan)">📤 Reseñas que dejé</h4>
    <div style="max-height:200px; overflow-y:auto">
      ${mine.slice(0, 5).map(r => `<div style="font-size:0.78rem; padding:0.4rem 0; border-bottom:1px solid rgba(255,255,255,0.05)"><span style="color:var(--neon-gold)">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span> <span style="color:var(--text-muted)">${escapeHtml(r.text.slice(0, 80))}${r.text.length > 80 ? '…' : ''}</span></div>`).join('')}
    </div>` : ''}
    ${aboutMe.length > 0 ? `
    <h4 style="margin:0.5rem 0; color:var(--neon-cyan)">📥 Reseñas sobre mí</h4>
    <div style="max-height:200px; overflow-y:auto">
      ${aboutMe.slice(0, 5).map(r => `<div style="font-size:0.78rem; padding:0.4rem 0; border-bottom:1px solid rgba(255,255,255,0.05)"><span style="color:var(--neon-gold)">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span> <span style="color:var(--text-muted)">${escapeHtml(r.text.slice(0, 80))}${r.text.length > 80 ? '…' : ''}</span></div>`).join('')}
    </div>` : ''}
  `;
}

// ── Wrapper: admin puede ver reseñas ocultas ────────────────────────────
function renderHiddenReviewsList() {
  const hidden = getAllReviews().filter(r => r.hidden);
  if (hidden.length === 0) return '<p style="color:var(--text-muted); text-align:center; padding:1rem; font-size:0.85rem">✅ No hay reseñas ocultas</p>';
  return hidden.map(r => {
    const rrs = (r.reportReasons || []).map(rr => `<li>${escapeHtml(rr.reason)} <span style="color:var(--text-muted); font-size:0.7rem">(${new Date(rr.reportedAt).toLocaleDateString('es-AW')})</span></li>`).join('');
    return `
      <div style="background:rgba(255,107,107,0.05); border:1px solid #ff6b6b; border-radius:8px; padding:0.75rem; margin-bottom:0.5rem">
        <div style="display:flex; align-items:center; gap:0.5rem; margin-bottom:0.4rem">
          <div style="color:var(--neon-gold)">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div>
          <div style="font-size:0.7rem; color:var(--text-muted)">${new Date(r.createdAt).toLocaleDateString('es-AW')}</div>
          <span style="background:rgba(255,107,107,0.2); color:#ff6b6b; padding:0.1rem 0.4rem; border-radius:4px; font-size:0.7rem; font-weight:600">${r.reportCount} reportes</span>
        </div>
        <div style="font-size:0.85rem; margin-bottom:0.4rem">${escapeHtml(r.text)}</div>
        <div style="font-size:0.75rem; color:var(--text-muted); margin-bottom:0.4rem"><strong>Razón:</strong> ${escapeHtml(r.hiddenReason || '—')}</div>
        <details style="font-size:0.78rem">
          <summary style="cursor:pointer; color:var(--text-muted)">Ver reportes (${(r.reportReasons || []).length})</summary>
          <ul style="margin:0.3rem 0 0; padding-left:1.25rem">${rrs}</ul>
        </details>
        <div style="display:flex; gap:0.4rem; margin-top:0.5rem">
          <button class="btn-secondary" style="font-size:0.7rem; padding:0.2rem 0.5rem; color:#51cf66" onclick="adminRestoreReview('${r.id}')">↩️ Restaurar</button>
          <button class="btn-secondary" style="font-size:0.7rem; padding:0.2rem 0.5rem; color:#ff6b6b" onclick="adminConfirmHide('${r.id}')">✓ Confirmar ocultamiento</button>
        </div>
      </div>
    `;
  }).join('');
}

function adminRestoreReview(reviewId) {
  const all = getAllReviews();
  const r = all.find(x => x.id === reviewId);
  if (r) {
    r.hidden = false;
    r.hiddenReason = null;
    r.restoredBy = appState.userProfile?.id || 'admin';
    r.restoredAt = new Date().toISOString();
    setAllReviews(all);
    recalculateTargetRating(r.targetId, r.type);
    showToast('↩️ Reseña restaurada', 'Visible públicamente de nuevo.');
  }
}

function adminConfirmHide(reviewId) {
  const all = getAllReviews();
  const r = all.find(x => x.id === reviewId);
  if (r) {
    r.confirmedByAdmin = true;
    r.confirmedAt = new Date().toISOString();
    setAllReviews(all);
    showToast('✓ Confirmado', 'La reseña queda oculta permanentemente.');
  }
}

// ==================== SABI: CART (Carrito de compras) ====================
// Modal con lista de items, totales, y botón "Ir a pagar" que crea orden pendiente.
// Aplica a productos del marketplace, verticales (restaurantes/boticas/mercados).
//
// HOOK (Supabase): tabla `cart_items` con FK a user_id, products, orders.
// Cuando user click "Ir a pagar" → crear order con status='pending' y vaciar cart.

function getCart() {
  try { return JSON.parse(localStorage.getItem('sabi_cart') || '[]'); }
  catch (e) { return []; }
}

function setCart(arr) {
  localStorage.setItem('sabi_cart', JSON.stringify(arr));
}

function addToCart(item) {
  // item = { productId, title, price, emoji, shopId, shopName, vertical, source, qty }
  const cart = getCart();
  const existing = cart.find(c => c.productId === item.productId);
  if (existing) {
    existing.qty = (existing.qty || 1) + (item.qty || 1);
  } else {
    cart.push({ ...item, qty: item.qty || 1, addedAt: new Date().toISOString() });
  }
  setCart(cart);
  updateCartBadge();
  return cart;
}

function removeFromCart(productId) {
  setCart(getCart().filter(c => c.productId !== productId));
  updateCartBadge();
}

function updateCartItemQty(productId, qty) {
  const cart = getCart();
  const item = cart.find(c => c.productId === productId);
  if (item) {
    if (qty <= 0) return removeFromCart(productId);
    item.qty = qty;
    setCart(cart);
  }
  updateCartBadge();
}

function clearCart() {
  setCart([]);
  updateCartBadge();
}

function cartTotals() {
  const cart = getCart();
  const subtotal = cart.reduce((s, i) => s + (i.price * i.qty), 0);
  const sabiFee = subtotal * SABI_COMMISSIONS.localSale;
  const total = subtotal;
  const count = cart.reduce((s, i) => s + i.qty, 0);
  return { subtotal, sabiFee, total, count };
}

// Badge en el header (ícono 🛒 con número)
function updateCartBadge() {
  const badge = document.getElementById('sabi-cart-badge');
  if (!badge) return;
  const { count } = cartTotals();
  badge.textContent = count > 99 ? '99+' : count;
  badge.style.display = count > 0 ? 'flex' : 'none';
}

// Modal del carrito
function openCartModal() {
  let existing = document.getElementById('cart-modal');
  if (existing) existing.remove();

  const modal = document.createElement('div');
  modal.id = 'cart-modal';
  modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:10000; display:flex; align-items:center; justify-content:center; padding:1rem; backdrop-filter:blur(8px);';

  document.body.appendChild(modal);   // ← primero al DOM
  renderCartBody();                   // ← después pintar contenido
}

function renderCartBody() {
  const modal = document.getElementById('cart-modal');
  if (!modal) return;

  const cart = getCart();
  const { subtotal, sabiFee, total, count } = cartTotals();
  const isEmpty = cart.length === 0;

  modal.innerHTML = `
    <div style="background:#0f092b; color:#ffffff; border:2px solid var(--neon-cyan); border-radius:18px; padding:1.5rem; max-width:520px; width:100%; max-height:90vh; display:flex; flex-direction:column; box-shadow:0 0 40px rgba(0,245,212,0.4)">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:1rem; flex-shrink:0">
        <h3 style="margin:0; color:var(--neon-cyan)">🛒 Tu carrito (${count})</h3>
        <button id="cart-close" style="background:none; border:none; color:#b0a8e3; font-size:1.5rem; cursor:pointer; padding:0; line-height:1">×</button>
      </div>

      <div id="cart-items" style="flex:1; overflow-y:auto; margin-bottom:1rem; min-height:120px">
        ${isEmpty ? `
          <div style="text-align:center; padding:2.5rem 1rem; color:#b0a8e3">
            <div style="font-size:3.5rem; margin-bottom:0.5rem; opacity:0.5">🛒</div>
            <div style="font-weight:600; margin-bottom:0.25rem">Tu carrito está vacío</div>
            <div style="font-size:0.8rem">Explorá el marketplace o las verticales para empezar</div>
          </div>
        ` : cart.map(item => `
          <div style="display:flex; align-items:center; gap:0.75rem; padding:0.75rem; background:#1b144c; border:1px solid #2f2575; border-radius:8px; margin-bottom:0.5rem; box-shadow:0 2px 8px rgba(0,0,0,0.3)">
            <div style="font-size:2rem; flex-shrink:0">${item.emoji || '📦'}</div>
            <div style="flex:1; min-width:0">
              <div style="font-weight:700; font-size:0.95rem; color:#ffffff; overflow:hidden; text-overflow:ellipsis; white-space:nowrap">${escapeHtml(item.title)}</div>
              <div style="font-size:0.8rem; color:#b0a8e3">${item.shopName ? escapeHtml(item.shopName) : ''} ${item.vertical ? '· ' + item.vertical : ''}</div>
              <div style="font-size:0.95rem; color:var(--neon-cyan); font-weight:800; margin-top:0.2rem">AWG ${(item.price * item.qty).toFixed(2)}</div>
            </div>
            <div style="display:flex; align-items:center; gap:0.25rem; flex-shrink:0">
              <button class="btn-secondary" style="padding:0.25rem 0.55rem; font-size:0.85rem; min-width:30px; background:#2f2575; border-color:#2f2575; color:#ffffff" onclick="changeCartQty('${item.productId}', -1)">−</button>
              <span style="min-width:24px; text-align:center; font-weight:700; color:#ffffff">${item.qty}</span>
              <button class="btn-secondary" style="padding:0.25rem 0.55rem; font-size:0.85rem; min-width:30px; background:#2f2575; border-color:#2f2575; color:#ffffff" onclick="changeCartQty('${item.productId}', 1)">+</button>
            </div>
            <button class="btn-secondary" style="padding:0.35rem 0.55rem; font-size:0.9rem; color:#ff6b6b; background:#2f2575; border-color:#2f2575" onclick="removeFromCartUI('${item.productId}')" title="Quitar">🗑️</button>
          </div>
        `).join('')}
      </div>

      ${!isEmpty ? `
      <div style="background:rgba(0,245,212,0.05); border:1px solid var(--neon-cyan); border-radius:10px; padding:0.75rem; margin-bottom:0.85rem; flex-shrink:0; color:#ffffff">
        <div style="display:flex; justify-content:space-between; margin-bottom:0.3rem; font-size:0.85rem"><span>Subtotal (${count} ${count === 1 ? 'item' : 'items'}):</span><strong>AWG ${subtotal.toFixed(2)}</strong></div>
        <div style="display:flex; justify-content:space-between; margin-bottom:0.3rem; font-size:0.8rem; color:#b0a8e3"><span>Comisión Sabí (3%):</span><span>incluida</span></div>
        <div style="display:flex; justify-content:space-between; padding-top:0.4rem; border-top:1px solid rgba(255,255,255,0.1); font-size:1rem"><strong>Total a pagar:</strong><strong style="color:var(--neon-cyan)">AWG ${total.toFixed(2)}</strong></div>
        <div style="font-size:0.7rem; color:#b0a8e3; margin-top:0.4rem">Delivery se calcula en el siguiente paso según tu dirección</div>
      </div>

      <div style="display:flex; gap:0.5rem; flex-shrink:0">
        <button class="btn-secondary" onclick="clearCartUI()" style="font-size:0.85rem; background:#1b144c; border-color:#2f2575; color:#ffffff">🗑️ Vaciar</button>
        <button class="cta-button" style="flex:1" onclick="goToCheckout()">💳 Ir a pagar · AWG ${total.toFixed(2)}</button>
      </div>
      ` : `
      <button class="cta-button" onclick="closeCartModal()" style="flex-shrink:0">Seguir comprando</button>
      `}
    </div>
  `;

  document.getElementById('cart-close').onclick = closeCartModal;
}

function changeCartQty(productId, delta) {
  const cart = getCart();
  const item = cart.find(c => c.productId === productId);
  if (!item) return;
  updateCartItemQty(productId, item.qty + delta);
  renderCartBody();
}

function removeFromCartUI(productId) {
  removeFromCart(productId);
  renderCartBody();
}

function clearCartUI() {
  if (!confirm('¿Vaciar el carrito?')) return;
  clearCart();
  renderCartBody();
}

function closeCartModal() {
  const modal = document.getElementById('cart-modal');
  if (modal) modal.remove();
}

// Checkout: crea orden pendiente + vacía carrito + muestra resumen
function goToCheckout() {
  const cart = getCart();
  if (cart.length === 0) return;
  const { total, sabiFee } = cartTotals();

  // Agrupar por shopId (cada shop genera una orden separada)
  const byShop = {};
  cart.forEach(item => {
    const key = item.shopId || 'misc';
    if (!byShop[key]) byShop[key] = { shopId: key, shopName: item.shopName || 'Sabí', items: [] };
    byShop[key].items.push(item);
  });

  const createdOrders = [];
  Object.values(byShop).forEach(group => {
    const groupTotal = group.items.reduce((s, i) => s + i.price * i.qty, 0);
    const order = createOrder({
      productId: group.items[0].productId,  // simplificado: 1er item
      sellerId: group.shopId,
      buyerId: appState.userProfile?.id || 'me',
      amount: groupTotal,
      items: group.items.map(i => ({ productId: i.productId, qty: i.qty, price: i.price }))
    });
    createdOrders.push(order);
  });

  showToast('✅ Orden creada', `${createdOrders.length} orden${createdOrders.length > 1 ? 'es' : ''} pendiente${createdOrders.length > 1 ? 's' : ''} · Total AWG ${total.toFixed(2)}`);
  clearCart();
  closeCartModal();
}

// Hook desde verticales/marketplace: add to cart + toast + badge update
function quickAddToCart(productData) {
  addToCart(productData);
  showToast('🛒 Agregado al carrito', `${productData.title} · AWG ${productData.price}`);
  // Animar el badge
  const badge = document.getElementById('sabi-cart-badge');
  if (badge) {
    badge.style.transform = 'scale(1.4)';
    setTimeout(() => { badge.style.transform = 'scale(1)'; }, 200);
  }
}

// Reemplaza el orderFromVertical antiguo para que vaya al carrito en vez de solo toast
window.orderFromVertical = function(vertical, business, product, price) {
  quickAddToCart({
    productId: 'v_' + vertical + '_' + business + '_' + product,
    title: product,
    price: price,
    emoji: '🍔',
    shopId: business,
    shopName: business,
    vertical: vertical,
    source: vertical
  });
};

// Exponer funciones del carrito a window (para onclick inline en HTML)
window.openCartModal       = openCartModal;
window.closeCartModal      = closeCartModal;
window.changeCartQty       = changeCartQty;
window.removeFromCartUI    = removeFromCartUI;
window.clearCartUI         = clearCartUI;
