  modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:10001; display:flex; align-items:center; justify-content:center; padding:1rem; backdrop-filter:blur(8px);';
  
  const date = new Date(o.createdAt);
