// ==================== AUTO 1: AUTO-RESTOCK MONITOR ====================
// Detecta productos de la tienda del usuario con stock ≤ 2 y notifica
// (si el toggle autoRestock está activo). NO agrega stock solo —
// solo notifica para que el usuario decida.
const autoRestockMonitor = {
  _timer: null,
  _lastAlerted: {},   // productId → timestamp (evita spam)
  _cooldownMs: 60000, // 1 min entre alertas del mismo producto

  start() {
    if (this._timer) return;
    this._timer = setInterval(() => this._check(), 30000); // cada 30s
    this._check(); // chequeo inmediato
  },

  stop() {
    if (this._timer) { clearInterval(this._timer); this._timer = null; }
  },

  _check() {
    const shop = appState.userShop || JSON.parse(localStorage.getItem('sabi_user_shop') || 'null');
    if (!shop || !shop.autoRestock) return;
    const myProducts = (appState.marketplaceAds || []).filter(ad => ad.shopId === shop.id);
    const lowStock = myProducts.filter(p => (p.stock || 0) > 0 && (p.stock || 0) <= 2);

    lowStock.forEach(p => {
      const last = this._lastAlerted[p.id] || 0;
      if (Date.now() - last < this._cooldownMs) return;
      this._lastAlerted[p.id] = Date.now();

      showToast(
        '🧠 Auto-restock alert',
        `"${p.title}" tiene solo ${p.stock} unidad${p.stock === 1 ? '' : 'es'}. Click para reponer.`,
        5000
      );

      // Opcional: actualizar el badge del header de Mi Tienda
      const dashboard = document.getElementById('mitienda-dashboard');
      if (dashboard && dashboard.style.display !== 'none') {
        renderMitiendaSubTab('inventario');
      }
    });
  }
};

// ==================== AUTO 4: ORDER AUTO-ADVANCE ====================
// Para simular el flujo real: pending → paid (5s) → in_transit (10s) → completed (15s).
// En producción, el backend real marcaría cada estado.
const orderAutoAdvance = {
  _timers: new Map(),  // orderId → setTimeout handle

  start() {
    // Hook en createOrder: auto-programar el avance
    const originalCreate = window.createOrder || createOrder;
    // Como createOrder no está en window, monkey-patch el localStorage check
    this._watchOrders();
  },

  _watchOrders() {
    // Poll cada 2s para detectar órdenes nuevas en pending
    setInterval(() => {
      const orders = getAllOrders().filter(o => o.status === 'pending');
      orders.forEach(o => {
        if (!this._timers.has(o.id)) {
          this._scheduleAdvance(o);
        }
      });
      // Limpiar timers de órdenes canceladas/completed
      const activeIds = new Set(getAllOrders().filter(o => ['pending','paid','in_transit'].includes(o.status)).map(o => o.id));
      for (const [orderId, timer] of this._timers) {
        if (!activeIds.has(orderId)) {
          clearTimeout(timer);
          this._timers.delete(orderId);
        }
      }
    }, 2000);
  },

  _scheduleAdvance(order) {
    // Simular pagos en 5s, tránsito 10s después, completado 15s después
    const t1 = setTimeout(() => {
      const o = getOrderById(order.id);
      if (o && o.status === 'pending') {
        updateOrderStatus(order.id, 'paid');
        showToast('💰 Pago confirmado', `Orden #${order.id.slice(-8)} → Pagado`, 3000);
        this._refreshUI();
      }
    }, 5000);
    this._timers.set(order.id + '_paid', t1);

    const t2 = setTimeout(() => {
      const o = getOrderById(order.id);
      if (o && o.status === 'paid') {
        updateOrderStatus(order.id, 'in_transit');
        showToast('🚚 En camino', `Tu pedido #${order.id.slice(-8)} está en camino`, 3000);
        this._refreshUI();
      }
    }, 15000);
    this._timers.set(order.id + '_transit', t2);

    const t3 = setTimeout(() => {
      const o = getOrderById(order.id);
      if (o && o.status === 'in_transit') {
        updateOrderStatus(order.id, 'completed');
        showToast('🎉 ¡Entregado!', `Pedido #${order.id.slice(-8)} completado. ¡Dejanos tu reseña!`, 5000);
        // AUTO 3: push de reseña automático
        this._pushReviewPrompt(order.id);
        this._refreshUI();
        this._timers.delete(order.id + '_paid');
        this._timers.delete(order.id + '_transit');
      }
    }, 30000);
    this._timers.set(order.id + '_completed', t3);
  },

  _refreshUI() {
    // Si la tab Mis Pedidos está abierta, refrescar
    const modal = document.getElementById('my-orders-modal');
    if (modal) renderMyOrdersBody();
  },

  // AUTO 3: Push de reseña cuando orden se completa
  _pushReviewPrompt(orderId) {
    const o = getOrderById(orderId);
    if (!o || !o.items || o.items.length === 0) return;
    const productId = o.items[0].productId;
    const alreadyReviewed = getAllReviews().some(r => r.orderId === orderId && r.authorId === (appState.userProfile?.id || 'me'));
    if (alreadyReviewed) return;

    // Esperar 2s para que se vea el toast de "Entregado" primero
    setTimeout(() => {
      const reviewNow = confirm(`🎉 ¡Tu pedido fue entregado!\n\n¿Querés dejar una reseña ahora?`);
      if (reviewNow) {
        const ad = (appState.marketplaceAds || []).find(a => a.id === productId);
        const targetName = ad ? ad.title : o.items[0].productId;
        openReviewModal(productId, 'product', orderId, targetName);
      } else {
        // Guardar que dejamos pendiente la reseña
        const pending = JSON.parse(localStorage.getItem('sabi_pending_reviews') || '[]');
        if (!pending.includes(orderId)) {
          pending.push(orderId);
          localStorage.setItem('sabi_pending_reviews', JSON.stringify(pending));
          showToast('💡', 'Reseña pendiente. Hacela desde Mis Pedidos cuando quieras.', 4000);
        }
      }
    }, 2000);
  }
};

