// ==================== FONDO DE MICROPRÉSTAMOS SABÍ CRÉDITO ====================
// Regla: TODO el dinero que se genera de Sabí Crédito se reinvierte en el mismo fondo.
// Interés compuesto: cada AWG 500 de profit acumulado = 1 nuovo fundo disponible.
//
// El fondo opera así:
//   - 用户 paga intereses → 100% vuelve al fondo (no se distribuye)
//   - El fondo crece solo, sin inyecciones externas
//   - Cada AWG 500 de profit acumulado = 1 nuovo fundo (cupo)
//   - El número de cupos disponibles = floor(profit_acumulado / 500)

const LENDING_POOL_TARGET = 30000;          // Objetivo inicial: 30k AWG
const PROFIT_THRESHOLD_FOR_NEW_SLOT = 500;   // Cada 500 de profit = 1 novo fundo
const MAX_CUPOS_INITIAL = 50;                // Cupos iniciales con 30k (30k/600 ≈ 50)

// Estado: profit acumulado para calcular cupos nuovi (se carga desde localStorage al iniciar)
let lendingProfitAccumulated = window.__lendingProfitAccumulated || 0;

function getLendingPoolStatus() {
  const current = appState.lendingPool || 10000;
  const profitAcc = typeof lendingProfitAccumulated !== 'undefined' ? lendingProfitAccumulated : window.__lendingProfitAccumulated;
  return {
    current,
    target: LENDING_POOL_TARGET,
    percent: (current / LENDING_POOL_TARGET * 100).toFixed(1),
    remaining: Math.max(0, LENDING_POOL_TARGET - current),
    reached: current >= LENDING_POOL_TARGET,
    profitAccumulated: profitAcc,
    cuposDisponibles: Math.floor(profitAcc / PROFIT_THRESHOLD_FOR_NEW_SLOT),
    profitToNextCupo: PROFIT_THRESHOLD_FOR_NEW_SLOT - (profitAcc % PROFIT_THRESHOLD_FOR_NEW_SLOT)
  };
}

// ==================== SINCRONIZACIÓN CON SUPABASE ====================

async function syncCreditPoolToSupabase() {
  const client = supabaseClient;
  if (!client) return;
  
  try {
    const poolStatus = getLendingPoolStatus();
    
    // Upsert al pool principal
    await client.from('credit_pools').upsert({
      pool_name: 'main',
      total_amount: appState.lendingPool || 10000,
      profit_accumulated: poolStatus.profitAccumulated,
      cupos_activos: 50 + poolStatus.cuposDisponibles,
      social_fund: appState.sabiSocialFund || 0,
      updated_at: new Date().toISOString()
    }, { onConflict: 'pool_name' });
  } catch (e) {
    console.error('[Sabí Crédito] Error sincronizando pool:', e);
  }
}

async function syncCreditTransaction(type, amount, description, loanId = null, userId = null) {
  const client = supabaseClient;
  if (!client) return;
  
  try {
    await client.from('credit_pool_transactions').insert({
      pool_name: 'main',
      transaction_type: type,
      amount: amount,
      description: description,
      loan_id: loanId,
      user_id: userId
    });
  } catch (e) {
    console.error('[Sabí Crédito] Error sincronizando transacción:', e);
  }
}

async function syncUserCreditProfile(userId) {
  const client = supabaseClient;
  if (!client || !userId) return;
  
  try {
    await client.from('profiles').update({
      credit_tier: appState.creditTier || 1,
      credit_score: appState.creditScore || 650,
      on_time_payments: appState.onTimePayments || 0,
      total_loans_taken: appState.totalLoansTaken || 0,
      total_loans_repaid: appState.totalLoansRepaid || 0,
      credit_blocked_until: appState.creditBlockedUntil || null
    }).eq('id', userId);
  } catch (e) {
    console.error('[Sabí Crédito] Error sincronizando perfil:', e);
  }
}

function recordLendingProfit(amount) {
  // Registrar profit del fondo: todo vuelve al fondo (interés compuesto)
  if (amount <= 0) return;
  
  // Sincronizar con Supabase
  syncCreditPoolToSupabase();
  
  // Sincronizar transacciones
  syncCreditTransaction('interest_earned', amount, 'Interés compuesto reinvertido');
  
  // Usar variable global
  if (typeof lendingProfitAccumulated === 'undefined') {
    lendingProfitAccumulated = window.__lendingProfitAccumulated || 0;
  }
  
  lendingProfitAccumulated += amount;
  window.__lendingProfitAccumulated = lendingProfitAccumulated;
  
  // Guardar en localStorage
  localStorage.setItem('sabi_lending_profit_accumulated', lendingProfitAccumulated.toFixed(2));
  
  // Agregar al fondo (reinversión automática)
  appState.lendingPool = (appState.lendingPool || 10000) + amount;
  localStorage.setItem('sabi_lending_pool', appState.lendingPool.toFixed(2));
  
  // Calcular cupos ganados
  const cuposGanados = Math.floor(lendingProfitAccumulated / PROFIT_THRESHOLD_FOR_NEW_SLOT);
  const cuposAntes = Math.floor((lendingProfitAccumulated - amount) / PROFIT_THRESHOLD_FOR_NEW_SLOT);
  
  if (cuposGanados > cuposAntes) {
    const nuevosCupos = cuposGanados - cuposAntes;
    console.log(`[Sabí Crédito] +${nuevosCupos} nuovo fundo! Profit accumulato: ${lendingProfitAccumulated.toFixed(2)} / Cupos: ${cuposGanados}`);
    showToast(
      '💰 Fondo grown!',
      `Interés composto: +${nuevosCupos} fundo${nuevosCupos > 1 ? 's' : ''}. Prossimo in ${(PROFIT_THRESHOLD_FOR_NEW_SLOT - (lendingProfitAccumulated % PROFIT_THRESHOLD_FOR_NEW_SLOT)).toFixed(0)} AWG.`,
      6000
    );
  }
}

function getAvailableCupos() {
  // Cupos disponibles = cupos ganados por profit - cupos ya usados
  const cuposGanados = Math.floor(lendingProfitAccumulated / PROFIT_THRESHOLD_FOR_NEW_SLOT);
  const cuposUsados = appState.usedCupos || 0;
  return Math.max(0, cuposGanados - cuposUsados);
}

window.recordLendingProfit = recordLendingProfit;
window.getLendingPoolStatus = getLendingPoolStatus;
window.getAvailableCupos = getAvailableCupos;

// Se llama cada vez que hay una transacción que genera comisión
function capitalizeLendingPool() {
  if (!appState.adminEarnings || appState.adminEarnings <= 0) return;

  const poolStatus = getLendingPoolStatus();
  if (poolStatus.reached) return; // Ya llegamos al objetivo

  // Calcular cuánto se aporta: 50% de las ganancias actuales
  const contribution = appState.adminEarnings * LENDING_POOL_CONTRIBUTION_PCT;

// ==================== FONDO SOCIAL (1% DEL INGRESO TOTAL) ====================
// Fondo separado del pool de préstamos. Se usa para:
//   - Becas escolares / inscripciones
//   - Cursos / capacitaciones
//   - Atención médica especializada
// Regla: 1% del ingreso bruto total de Sabí va al fondo social.
const SOCIAL_FUND_CONTRIBUTION_PCT = 0.01;

// Registra un ingreso bruto a Sabí y aporta el 1% al fondo social.
function recordSabíIncome(source, grossAmount, sabíShare) {
  if (grossAmount <= 0) return;
  appState.sabiTotalIncome = (appState.sabiTotalIncome || 0) + grossAmount;
  localStorage.setItem('sabi_total_income', appState.sabiTotalIncome.toFixed(2));

  // 1% del ingreso bruto va al fondo social
  const socialContribution = grossAmount * SOCIAL_FUND_CONTRIBUTION_PCT;
  appState.sabiSocialFund = (appState.sabiSocialFund || 0) + socialContribution;
  localStorage.setItem('sabi_social_fund', appState.sabiSocialFund.toFixed(2));

  console.log(`[Sabí Income] +${grossAmount.toFixed(2)} (${source}) | Sabí recibe ${sabíShare.toFixed(2)} | Fondo social +${socialContribution.toFixed(2)} (total ${appState.sabiSocialFund.toFixed(2)})`);
}

function getSocialFundStatus() {
  const balance = appState.sabiSocialFund || 0;
  const totalIncome = appState.sabiTotalIncome || 0;
  const expectedFromFormula = totalIncome * SOCIAL_FUND_CONTRIBUTION_PCT;
  return {
    balance,
    totalIncome,
    expectedFromFormula,
    pct: SOCIAL_FUND_CONTRIBUTION_PCT
  };
}

window.recordSabíIncome = recordSabíIncome;
window.getSocialFundStatus = getSocialFundStatus;

  // No exceder el objetivo
  const maxContribution = poolStatus.remaining;
  const actualContribution = Math.min(contribution, maxContribution);

  if (actualContribution < 1) return; // No aportar si es menos de 1 AWG

  // Actualizar fondo
  appState.lendingPool = (appState.lendingPool || 10000) + actualContribution;
  localStorage.setItem('sabi_lending_pool', appState.lendingPool.toFixed(2));

  // Registrar en log (para debug/admin)
  console.log(`[Lending Pool] +${actualContribution.toFixed(2)} AWG (50% de ganancias). Total: ${appState.lendingPool.toFixed(2)} / ${LENDING_POOL_TARGET}`);

  // Notificar si llegamos al objetivo
  if (appState.lendingPool >= LENDING_POOL_TARGET) {
    showToast('🎉 Objetivo alcanzado', `El fondo de micropréstamos llegó a AWG ${LENDING_POOL_TARGET.toLocaleString()}!`, 8000);
  }
}

// Hook: interceptar funciones que generan ganancias y llamar a capitalizeLendingPool después
function hookGainsToLendingPool() {
  const originalDriverComplete = window.completeDriverTripWithEarnings;
  if (originalDriverComplete) {
    window.completeDriverTripWithEarnings = function(...args) {
      const result = originalDriverComplete.apply(this, args);
      // Después de completar un trip (que suma a adminEarnings), capitalizar
      setTimeout(capitalizeLendingPool, 100);
      return result;
    };
  }
}
