function handleShopAvatar(event) {
  const file = event.target.files[0];
  if (!file) return;
  if (file.size > 2 * 1024 * 1024) { showToast('⚠️ Imagen muy grande', 'Máx 2MB.'); return; }
  const reader = new FileReader();
  reader.onload = (e) => {
    resizeImage(e.target.result, 200, (resized) => {
      document.getElementById('sc-avatar-data').value = resized;
      const preview = document.getElementById('sc-avatar-preview');
      preview.style.backgroundImage = `url('${resized}')`;
      preview.style.backgroundSize = 'cover';
      preview.style.backgroundPosition = 'center';
      preview.textContent = '';
    });
  };
  reader.readAsDataURL(file);
}

function submitShopCreate() {
  const name = document.getElementById('sc-name').value.trim();
  const category = document.getElementById('sc-category').value;
  const desc = document.getElementById('sc-desc').value.trim();
  const avatar = document.getElementById('sc-avatar-data').value;

  if (name.length < 2) { showToast('Error', 'Nombre muy corto (mín 2 caracteres).'); return; }
  if (!category) { showToast('Error', 'Elegí una categoría.'); return; }

  const shop = {
    id: 'shop_' + Date.now(),
    name, category, desc, avatar,
    rating: 0, totalSales: 0, pendingPayout: 0,
    ppcSpend: 0, ppcClicks: 0, ppcImpressions: 0,
    createdAt: new Date().toISOString()
  };
  localStorage.setItem('sabi_user_shop', JSON.stringify(shop));
  appState.userShop = shop;
  showToast('🏪 ¡Tienda creada!', `"${shop.name}" está lista. Agregá tu primer producto.`);
  closeShopCreateModal();
  renderMitiendaTab();
}

function closeShopCreateModal() {
  const modal = document.getElementById('shop-create-modal');
  if (modal) modal.remove();
}

