// Active Trip HTML view
function renderDriverActiveTripHtml() {
  const trip = appState.activeTrip;
  if (!trip) {
    return `
      <div style="padding: 2.5rem; text-align: center; color: var(--text-muted);">
        <span style="font-size: 2.5rem; display: block; margin-bottom: 0.75rem">📦</span>
        No tienes entregas activas en este momento. ¡Activa tu estado y espera un pedido!
      </div>
    `;
  }
  
  let statusText = "";
  let actionButtonHtml = "";
  
  if (trip.status === 'accepted') {
    statusText = "📍 En camino a recoger el paquete...";
    actionButtonHtml = `
      <button class="btn btn-cyan btn-full" disabled style="opacity: 0.6; cursor: not-allowed;">
        🚗 Viajando a Punto de Recogida...
      </button>
    `;
  } else if (trip.status === 'pickup') {
    statusText = "✅ Llegaste al punto de recogida. Solicita el paquete al vendedor.";
    actionButtonHtml = `
      <button class="btn btn-cyan btn-full" style="background: var(--neon-gold); border-color: var(--neon-gold); color: #000;" onclick="window.driverPickupPackage()">
        📦 Paquete Recogido - Iniciar Entrega
      </button>
    `;
  } else if (trip.status === 'delivery') {
    statusText = "📍 En camino a entregar el paquete...";
    actionButtonHtml = `
      <button class="btn btn-cyan btn-full" disabled style="opacity: 0.6; cursor: not-allowed;">
        🚗 Viajando a Punto de Entrega...
      </button>
    `;
  } else if (trip.status === 'reached_delivery') {
    statusText = "✅ Receptáculo de entrega alcanzado. Entrega el paquete y toma confirmación.";
    actionButtonHtml = `
      <button class="btn btn-cyan btn-full" onclick="window.openPhotoVerification()">
        📷 Tomar Foto de Confirmación
      </button>
    `;
  }
  
  return `
    <div style="margin-top:1.5rem">
      <div class="map-sim-card" style="margin-bottom: 1.25rem;">
        <canvas id="gps-canvas" width="400" height="180" class="gps-canvas-map"></canvas>
      </div>
      
      <div style="background:rgba(255,255,255,0.02); border:1px solid var(--glass-border); padding:1.25rem; border-radius:14px; margin-bottom:1.25rem">
        <div style="font-weight:800; font-size:1.05rem; color:var(--text-main); margin-bottom:0.75rem">Información del Envío:</div>
        <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem; font-size:0.85rem">
          <span style="color:var(--text-muted)">Artículo:</span>
          <span style="font-weight:700">${trip.itemTitle}</span>
        </div>
        <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem; font-size:0.85rem">
          <span style="color:var(--text-muted)">Recogida en:</span>
          <span style="font-weight:700">📍 ${trip.pickupDistrict}</span>
        </div>
        <div style="display:flex; justify-content:space-between; margin-bottom:0.4rem; font-size:0.85rem">
          <span style="color:var(--text-muted)">Entregar en:</span>
          <span style="font-weight:700">🏠 ${trip.deliveryDistrict}</span>
        </div>
        <div style="display:flex; justify-content:space-between; font-size:0.85rem">
          <span style="color:var(--text-muted)">Pago del Viaje (${((1 - getDriverCommissionRate()) * 100).toFixed(0)}%):</span>
          <span style="font-weight:800; color:var(--neon-gold)">Afl. ${trip.driverEarnings.toFixed(2)}</span>
        </div>
      </div>
      
      <div style="font-size:0.9rem; font-weight:700; color:var(--neon-cyan); margin-bottom:1rem; text-align:center">
        ${statusText}
      </div>
      
      ${actionButtonHtml}
    </div>
  `;
}

// Driver registration handlers
function handleDriverRegister() {
  const name = document.getElementById("driver-reg-name").value.trim();
  const car = document.getElementById("driver-reg-car").value.trim();
  const license = document.getElementById("driver-reg-license").value.trim();
  const photo = document.getElementById("driver-reg-photo").value;
  
  if (!name || !car || !license) {
    showToast("Error", "Por favor completa todos los campos del registro.");
    return;
  }
  
  if (!photo) {
    showToast("Error", "Por favor sube una foto de tu licencia (simulada).");
    return;
  }
  
  SoundEffects.playJingle();
  
  const driverInfo = { name, car, license, photo };
  appState.driverInfo = driverInfo;
  appState.driverStatus = 'pending';
  
  localStorage.setItem('sabi_driver_status', 'pending');
  localStorage.setItem('sabi_driver_info', JSON.stringify(driverInfo));
  
  // Save to pending list for Admin Dashboard
  let pendingList = appState.pendingDrivers || [];
  pendingList.push({
    id: `driver-${Date.now()}`,
    ...driverInfo
  });
  appState.pendingDrivers = pendingList;
  localStorage.setItem('sabi_pending_drivers', JSON.stringify(pendingList));
  
  showToast("Registro Enviado", "Tu registro se ha enviado a revisión.");
  renderDriverPortal();
}

function simulateLicenseUpload() {
  SoundEffects.playClick();
  const label = document.getElementById("driver-license-upload-label");
  const photoInput = document.getElementById("driver-reg-photo");
  if (label && photoInput) {
    label.innerText = "⏳ Cifrando y subiendo licencia...";
    setTimeout(() => {
      photoInput.value = "licencia_simulada.jpg";
      label.innerHTML = "🔒 <strong>licencia_simulada.jpg</strong> subida y resguardada";
      showToast("Archivo Cargado", "Licencia cargada de forma segura bajo cifrado.");
    }, 1200);
  }
}

function handleProfileTaxDocSelected(event) {
  const file = event.target.files[0];
  if (!file) return;
  
  const taxId = document.getElementById("profile-tax-id").value.trim();
  const label = document.getElementById("profile-tax-doc-upload-label");
  const valueInput = document.getElementById("profile-tax-doc-value");
  
  if (!taxId) {
    showToast("⚠️ Campo Requerido", "Por favor ingresa primero tu número de Persoonnummer para poder validarlo contra el documento.");
    event.target.value = '';
    return;
  }
  
  // Rule: must be exactly 8 digits of numbers
  const isEightDigits = /^\d{8}$/.test(taxId);
  if (!isEightDigits) {
    if (SoundEffects.playError) SoundEffects.playError();
    showToast("❌ Validación Fallida", "El Persoonnummer debe consistir de exactamente 8 dígitos numéricos (ej: 10029348).");
    if (label) label.innerHTML = `<span style="color:#ff6b6b">❌ Formato inválido</span>`;
    event.target.value = '';
    return;
  }
  
  SoundEffects.playClick();
  
  // Show animated scanning overlay on the dropzone
  if (label) {
    label.innerHTML = `<span class="spinner" style="width:14px; height:14px; border:2px solid rgba(255,255,255,0.1); border-top-color:var(--neon-cyan); border-radius:50%; display:inline-block; animation: spin 1s linear infinite; vertical-align:middle; margin-right:4px;"></span> 🔍 Analizando firma DIMP/SIAD...`;
  }
  
  setTimeout(() => {
    if (label) label.innerHTML = `🔍 Verificando registro en Base Fiscal...`;
    setTimeout(() => {
      if (valueInput) valueInput.value = file.name;
      if (label) label.innerHTML = `🔒 <strong>${file.name}</strong> verificado y cifrado con éxito`;
      if (SoundEffects.playJingle) SoundEffects.playJingle();
      showToast("✅ Validación SIAD Exitosa", `El documento "${file.name}" coincide con el registro del Persoonnummer ${taxId}.`);
    }, 1500);
  }, 1200);
}
window.handleProfileTaxDocSelected = handleProfileTaxDocSelected;

function handleProfileIdentityDocSelected(event) {
  const file = event.target.files[0];
  if (!file) return;
  
  const identityId = document.getElementById("profile-identity-id").value.trim();
  const label = document.getElementById("profile-identity-doc-upload-label");
  const valueInput = document.getElementById("profile-identity-doc-value");
  
  if (!identityId) {
    showToast("⚠️ Campo Requerido", "Por favor ingresa primero tu número de ID / Cédula para validarlo.");
    event.target.value = '';
    return;
  }
  
  // Format check: at least 6 characters
  if (identityId.length < 6) {
    if (SoundEffects.playError) SoundEffects.playError();
    showToast("❌ Validación Fallida", "El número de ID debe tener al menos 6 caracteres oficiales (ej: A-1002934).");
    if (label) label.innerHTML = `<span style="color:#ff6b6b">❌ ID muy corto</span>`;
    event.target.value = '';
    return;
  }
  
  SoundEffects.playClick();
  
  if (label) {
    label.innerHTML = `<span class="spinner" style="width:14px; height:14px; border:2px solid rgba(255,255,255,0.1); border-top-color:var(--neon-cyan); border-radius:50%; display:inline-block; animation: spin 1s linear infinite; vertical-align:middle; margin-right:4px;"></span> 🔍 Leyendo campos ID (OCR)...`;
  }
  
  setTimeout(() => {
    if (label) label.innerHTML = `🔍 Validando coincidencia titular...`;
    setTimeout(() => {
      if (valueInput) valueInput.value = file.name;
      if (label) label.innerHTML = `🔒 <strong>${file.name}</strong> verificado y cifrado con éxito`;
      if (SoundEffects.playJingle) SoundEffects.playJingle();
      showToast("✅ Identidad Confirmada", `ID "${identityId}" validado correctamente contra el registro civil de Aruba.`);
    }, 1500);
  }, 1200);
}
window.handleProfileIdentityDocSelected = handleProfileIdentityDocSelected;

function handleProfilePhotoUploaded(event) {
  const file = event.target.files[0];
  if (!file) return;
  
  const reader = new FileReader();
  reader.onload = function(e) {
    const dataUrl = e.target.result;
    appState.userProfile.photo = dataUrl;
    
    // Guardar en local storage
    localStorage.setItem('sabi_user_profile', JSON.stringify(appState.userProfile));
    
    // Reproducir jingle de éxito
    if (typeof SoundEffects !== 'undefined' && SoundEffects.playJingle) {
      SoundEffects.playJingle();
    }
    showToast("Foto Actualizada", "Tu foto de perfil ha sido cambiada correctamente.");
    
    // Renderizar de nuevo el modal de perfil
    renderAccountModal();
  };
  reader.readAsDataURL(file);
}
window.handleProfilePhotoUploaded = handleProfilePhotoUploaded;

function handleDriverDocSelected(event, type) {
  const file = event.target.files[0];
  if (!file) return;
  
  let labelId, valId, filePrefix, toastMsg, verifyMsg;
  if (type === 'id') {
    const driverId = document.getElementById("driver-reg-id").value.trim();
    if (!driverId) {
      showToast("⚠️ Campo Requerido", "Ingresa primero tu número de ID.");
      event.target.value = '';
      return;
    }
    if (driverId.length < 6) {
      if (SoundEffects.playError) SoundEffects.playError();
      showToast("❌ Validación Fallida", "El ID debe tener al menos 6 caracteres.");
      event.target.value = '';
      return;
    }
    labelId = "driver-reg-id-label";
    valId = "driver-reg-id-val";
    filePrefix = file.name;
    toastMsg = "Copia de ID / Cédula subida de forma segura.";
    verifyMsg = "Verificando consistencia titular SIAD...";
  } else if (type === 'lic') {
    const lic = document.getElementById("driver-reg-license").value.trim();
    if (!lic) {
      showToast("⚠️ Campo Requerido", "Ingresa primero tu número de Licencia.");
      event.target.value = '';
      return;
    }
    labelId = "driver-reg-lic-label";
    valId = "driver-reg-lic-val";
    filePrefix = file.name;
    toastMsg = "Copia de Licencia de Conducir subida de forma segura.";
    verifyMsg = "Escaneando licencia oficial de conducir...";
  } else if (type === 'tax') {
    const tax = document.getElementById("driver-reg-tax").value.trim();
    if (!tax) {
      showToast("⚠️ Campo Requerido", "Ingresa primero tu número de Persoonnummer.");
      event.target.value = '';
      return;
    }
    if (!/^\d{8}$/.test(tax)) {
      if (SoundEffects.playError) SoundEffects.playError();
      showToast("❌ Validación Fallida", "El Persoonnummer debe tener exactamente 8 dígitos.");
      event.target.value = '';
      return;
    }
    labelId = "driver-reg-tax-label";
    valId = "driver-reg-tax-val";
    filePrefix = file.name;
    toastMsg = "Comprobante de Persoonnummer subido de forma segura.";
    verifyMsg = "Validando registro fiscal de transporte en Aruba (SIAD)...";
  }
  
  const label = document.getElementById(labelId);
  const valInput = document.getElementById(valId);
  if (label && valInput) {
    SoundEffects.playClick();
    label.innerHTML = `<span class="spinner" style="width:14px; height:14px; border:2px solid rgba(255,255,255,0.1); border-top-color:var(--neon-cyan); border-radius:50%; display:inline-block; animation: spin 1s linear infinite; vertical-align:middle; margin-right:4px;"></span> ${verifyMsg}`;
    setTimeout(() => {
      valInput.value = filePrefix;
      label.innerHTML = `🔒 <strong>${filePrefix}</strong> verificado y guardado`;
      if (SoundEffects.playJingle) SoundEffects.playJingle();
      showToast("✅ Archivo Cargado", toastMsg);
    }, 1500);
  }
}
window.handleDriverDocSelected = handleDriverDocSelected;

function saveMerchantLogistics() {
  const sellerType = document.getElementById("logistics-seller-type").value;
  const hoursStart = document.getElementById("logistics-hours-start").value;
  const hoursEnd = document.getElementById("logistics-hours-end").value;
  const prepTime = parseInt(document.getElementById("logistics-prep-time").value, 10) || 30;
  const priceMin = parseFloat(document.getElementById("logistics-price-min").value) || 1;
  const priceMax = parseFloat(document.getElementById("logistics-price-max").value) || 10000;
  
  const checkedZones = Array.from(document.querySelectorAll('input[name="logistics-zones"]:checked')).map(cb => cb.value);
  
  appState.merchantConfig = {
    sellerType,
    hoursStart,
    hoursEnd,
    prepTime,
    priceMin,
    priceMax,
    deliveryZones: checkedZones
  };
  
  localStorage.setItem('sabi_merchant_config', JSON.stringify(appState.merchantConfig));
  
  if (appState.userShop) {
    appState.userShop.sellerType = sellerType;
    localStorage.setItem('sabi_user_shop', JSON.stringify(appState.userShop));
  }
  
  if (SoundEffects.playJingle) SoundEffects.playJingle();
  showToast("Configuración Guardada", "Tus reglas de logística y parámetros de venta se han actualizado.");
  renderAccountModal();
}
