// ==================== DYNAMIC PASSENGER & ARRIVALS ESTIMATION ENGINE ====================

function estimateFlightPax(airline, origin, flightNo) {
  const a = (airline || '').toLowerCase();
  const o = (origin || '').toLowerCase();
  const fn = (flightNo || '').toUpperCase();
  
  // 1. Inter-island hopper flights (Curacao, Bonaire, St. Maarten)
  // Divi Divi Air (3R), Winair (WM), EZ Air / Z-Air (7Z), Aruba Airlines island hops
  // Aeronaves: DHC-6 Twin Otter (19 asientos), Britten-Norman BN-2 (9 asientos)
  if (
    a.includes('divi divi') || a.includes('ez air') || a.includes('z-air') || a.includes('winair') ||
    fn.startsWith('3R') || fn.startsWith('WM') || fn.startsWith('7Z') ||
    o.includes('curacao') || o.includes('cur') || o.includes('bonaire') || o.includes('bon') ||
    o.includes('hato') || o.includes('flamingo') || o.includes('sxm')
  ) {
    return 18;
  }

  // 2. Aviación privada, ejecutiva o chárter
  if (a.includes('private') || a.includes('privado') || a.includes('charter') || a.includes('executive')) {
    return 8;
  }

  // 3. Vuelos transatlánticos europeos de fuselaje ancho (Amsterdam, Frankfurt, París)
  // KLM, TUI fly Netherlands, Air France, Lufthansa, Condor
  // Aeronaves: Boeing 777-200/300ER, Boeing 787 Dreamliner, Airbus A330 (280-340 asientos, ocupación ~88%)
  if (
    a.includes('klm') || a.includes('tui') || a.includes('lufthansa') || a.includes('air france') || a.includes('condor') ||
    fn.startsWith('KL') || fn.startsWith('OR') || fn.startsWith('AF') || fn.startsWith('LH') ||
    o.includes('amsterdam') || o.includes('ams') || o.includes('frankfurt') || o.includes('fra') ||
    o.includes('schiphol') || o.includes('paris') || o.includes('cdg')
  ) {
    return 265;
  }

  // 4. Aerolíneas de Norteamérica (EE.UU. y Canadá)
  // American Airlines, Delta, United, JetBlue, Southwest, Air Canada, WestJet, Sunwing, Spirit, Frontier
  // Aeronaves: A320/A321, B737-800/900ER/MAX 8/9. Factor de ocupación oficial ATA ~88%.
  if (
    a.includes('american') || a.includes('delta') || a.includes('united') || a.includes('jetblue') ||
    a.includes('southwest') || a.includes('air canada') || a.includes('westjet') || a.includes('sunwing') ||
    a.includes('spirit') || a.includes('frontier') || a.includes('alaska') ||
    fn.startsWith('AA') || fn.startsWith('DL') || fn.startsWith('UA') || fn.startsWith('B6') ||
    fn.startsWith('WN') || fn.startsWith('AC') || fn.startsWith('WS') || fn.startsWith('NK') ||
    o.includes('jfk') || o.includes('mia') || o.includes('atl') || o.includes('ewr') || o.includes('bos') ||
    o.includes('clt') || o.includes('iah') || o.includes('ord') || o.includes('mco') || o.includes('fll') ||
    o.includes('phl') || o.includes('dfw') || o.includes('bwi') || o.includes('yyz') || o.includes('yul') || o.includes('usa')
  ) {
    return 155;
  }

  // 5. Aerolíneas de Sudamérica y Caribe Regional (fuselaje angosto)
  // Copa, Avianca, LATAM, GOL, Aerolíneas Argentinas, Wingo, Arajet, Sky High, Surinam Airways
  // Aeronaves: B737-800/MAX 8, A320neo, Embraer E190
  if (
    a.includes('copa') || a.includes('avianca') || a.includes('latam') || a.includes('gol') ||
    a.includes('aerolineas') || a.includes('wingo') || a.includes('arajet') || a.includes('sky high') || a.includes('surinam') ||
    fn.startsWith('CM') || fn.startsWith('AV') || fn.startsWith('LA') || fn.startsWith('G3') ||
    fn.startsWith('AR') || fn.startsWith('P5') || fn.startsWith('PY') || fn.startsWith('DM') ||
    o.includes('bogota') || o.includes('bog') || o.includes('panama') || o.includes('pty') ||
    o.includes('lima') || o.includes('lim') || o.includes('medellin') || o.includes('mde') ||
    o.includes('buenos aires') || o.includes('eze') || o.includes('sao paulo') || o.includes('gru') ||
    o.includes('santo domingo') || o.includes('sdq')
  ) {
    return 138;
  }

  // 6. Promedio comercial estándar
  return 140;
}
window.estimateFlightPax = estimateFlightPax;

function calculateFlightMetrics(flights) {
  if (!flights || flights.length === 0) {
    return {
      totalFlights: 0,
      totalPax: 0,
      usFlights: 0,
      usMarketPct: 0,
      peakHour: '12:00 PM - 03:00 PM'
    };
  }

  let totalPax = 0;
  let usFlights = 0;
  const hourCounts = {};

  flights.forEach(f => {
    const pax = estimateFlightPax(f.airline, f.origin, f.flightNo || f.flight_number);
    totalPax += pax;

    const a = (f.airline || '').toLowerCase();
    const o = (f.origin || '').toLowerCase();
    const fn = (f.flightNo || f.flight_number || '').toUpperCase();
    const isUs = a.includes('american') || a.includes('delta') || a.includes('united') || a.includes('jetblue') ||
                 a.includes('southwest') || a.includes('spirit') || a.includes('frontier') || a.includes('alaska') ||
                 fn.startsWith('AA') || fn.startsWith('DL') || fn.startsWith('UA') || fn.startsWith('B6') || fn.startsWith('WN') ||
                 o.includes('usa') || o.includes('jfk') || o.includes('mia') || o.includes('atl') ||
                 o.includes('ewr') || o.includes('bos') || o.includes('clt') || o.includes('iah') ||
                 o.includes('ord') || o.includes('mco') || o.includes('fll') || o.includes('phl') ||
                 o.includes('dfw') || o.includes('bwi');
    if (isUs) usFlights++;

    const t = f.time || f.scheduled_time || '';
    let h = NaN;
    if (t.includes(':')) {
      const parts = t.split(':');
      h = parseInt(parts[0], 10);
      if (t.toUpperCase().includes('PM') && h < 12) h += 12;
      if (t.toUpperCase().includes('AM') && h === 12) h = 0;
    }
    if (!isNaN(h) && h >= 0 && h <= 23) {
      hourCounts[h] = (hourCounts[h] || 0) + 1;
    }
  });

  const usMarketPct = flights.length > 0 ? Math.round((usFlights / flights.length) * 100) : 0;

  // Franja pico de 3 horas continuas con mayor cantidad de vuelos
  let maxWindowFlights = 0;
  let peakStartHour = 12;
  for (let h = 6; h <= 21; h++) {
    const count = (hourCounts[h] || 0) + (hourCounts[h + 1] || 0) + (hourCounts[h + 2] || 0);
    if (count > maxWindowFlights) {
      maxWindowFlights = count;
      peakStartHour = h;
    }
  }

  const formatHour = (h) => {
    const ampm = h >= 12 ? 'PM' : 'AM';
    const hour12 = h % 12 === 0 ? 12 : h % 12;
    return `${hour12.toString().padStart(2, '0')}:00 ${ampm}`;
  };
  const peakHour = `${formatHour(peakStartHour)} - ${formatHour(peakStartHour + 3)}`;

  return {
    totalFlights: flights.length,
    totalPax,
    usFlights,
    usMarketPct,
    peakHour
  };
}
window.calculateFlightMetrics = calculateFlightMetrics;

function calculateCruiseMetrics(cruises) {
  if (!cruises || cruises.length === 0) {
    return {
      totalShips: 0,
      totalPax: 0,
      econImpact: '$0 USD',
      avgSpend: '$120.00 USD'
    };
  }
  const totalPax = cruises.reduce((sum, c) => sum + (c.passengers || 0), 0);
  const econImpact = totalPax * 120; // $120 USD gasto medio por crucerista en Aruba (ATA)
  return {
    totalShips: cruises.length,
    totalPax,
    econImpact: `$${econImpact.toLocaleString()} USD`,
    avgSpend: '$120.00 USD'
  };
}
window.calculateCruiseMetrics = calculateCruiseMetrics;

