async function checkAndRenderShopStatus() {
  if (!supabaseClient) return;
  const sessionRes = await supabaseClient.auth.getSession();
  const session = sessionRes.data.session;
  if (!session || !session.user) return;
  
  try {
    const { data: shop, error } = await supabaseClient
      .from('shops')
      .select('*')
      .eq('id', session.user.id)
      .maybeSingle();

    if (error) throw error;

    if (shop) {
      appState.userShop = shop;
      const sectionContainer = document.getElementById("shop-management-section");
      if (sectionContainer) {
        if (shop.is_approved) {
          sectionContainer.innerHTML = `
            <div style="text-align: center; padding: 1rem;">
              <div style="font-size: 2rem; margin-bottom: 0.5rem;">🎉</div>
              <h4 style="color: var(--neon-gold); font-weight: 700; margin: 0 0 4px 0;">¡Tu Tienda está Activa!</h4>
              <p style="font-size: 0.8rem; color: var(--text-light); margin: 0 0 10px 0;">Comercio: <strong>${shop.name}</strong> (${shop.category.toUpperCase()})</p>
              <div style="font-size: 0.7rem; background: rgba(0,255,128,0.1); border: 1px solid rgba(0,255,128,0.2); color: #00ff80; padding: 6px; border-radius: 8px; display: inline-block;">
                ✔️ Transacciones en Custodia y Envíos Automatizados Habilitados
              </div>
            </div>
          `;
        } else {
          sectionContainer.innerHTML = `
            <div style="text-align: center; padding: 1rem;">
              <div style="font-size: 2rem; margin-bottom: 0.5rem;">⏳</div>
              <h4 style="color: #ffcc00; font-weight: 700; margin: 0 0 4px 0;">Tienda bajo Revisión</h4>
              <p style="font-size: 0.8rem; color: var(--text-muted); margin: 0 0 10px 0;">Estamos validando fiscalmente tu Persoonnummer <strong>${shop.persoonnummer}</strong> ante la DIMP.</p>
              <div style="font-size: 0.7rem; background: rgba(255,204,0,0.1); border: 1px solid rgba(255,204,0,0.2); color: #ffcc00; padding: 6px; border-radius: 8px; display: inline-block;">
                La verificación toma menos de 24 horas hábiles.
              </div>
            </div>
          `;
        }
      } else {
        renderAccountModal();
      }
    }
  } catch (err) {
    console.error("Error al renderizar el estado de la tienda:", err);
  }
}

window.checkAndRenderShopStatus = checkAndRenderShopStatus;

function adminApproveShop(shopId) {
  SoundEffects.playClick();
  
  if (!supabaseClient) {
    const shop = appState.adminCRMShops ? appState.adminCRMShops.find(s => s.id === shopId) : null;
    if (shop) {
      shop.is_approved = true;
      if (appState.userShop && appState.userShop.id === shopId) {
        appState.userShop.is_approved = true;
      }
      showToast("Comercio Aprobado", `Tienda ${shop.name} aprobada con éxito.`);
      renderAccountModal();
    }
    return;
  }
  
  supabaseClient
    .from("shops")
    .update({ is_approved: true })
    .eq("id", shopId)
    .then(({ error }) => {
      if (error) {
        console.error("Error approving shop:", error);
        showToast("Error", "Error al aprobar comercio: " + error.message);
      } else {
        showToast("Comercio Aprobado", "El comercio ha sido aprobado con éxito.");
        if (appState.adminCRMShops) {
          const shop = appState.adminCRMShops.find(s => s.id === shopId);
          if (shop) shop.is_approved = true;
        }
        if (appState.userShop && appState.userShop.id === shopId) {
          appState.userShop.is_approved = true;
        }
        renderAccountModal();
      }
    });
}
window.adminApproveShop = adminApproveShop;


function toggleDriverActiveState(checkbox) {
  appState.driverActive = checkbox.checked;
  localStorage.setItem('sabi_driver_active', appState.driverActive.toString());
  SoundEffects.playClick();
  renderAccountModal();
}

function handleDriverAcceptTrip(tripId, price, title, name, address, coords) {
  SoundEffects.playJingle();

  const parentDel = appState.customDeliveries.find(d => d.id === tripId);
  const escrowAmt = parentDel ? parentDel.escrowAmount : 0;

  appState.driverActiveTrip = {
    id: tripId,
    price,
    title,
    name,
    address,
    coords,
    escrowAmount: escrowAmt,
    status: 'assigned'
  };

  localStorage.setItem('sabi_driver_active_trip', JSON.stringify(appState.driverActiveTrip));

  // If it is one of the custom deliveries, update its status in the pool
  const idx = appState.customDeliveries.findIndex(d => d.id === tripId);
  if (idx !== -1) {
    appState.customDeliveries[idx].status = 'assigned';
    localStorage.setItem('sabi_custom_deliveries', JSON.stringify(appState.customDeliveries));
    if (appState.activeComunidadTab === 'delivery') {
      renderDeliveryRequestPortal();
    }
  }

  showToast("Viaje Aceptado", `Has tomado la entrega: "${title}". Dirígete al punto de recogida.`);
  renderAccountModal();
}

function handleDriverPickupPackage(tripId) {
  if (!appState.driverActiveTrip || appState.driverActiveTrip.id !== tripId) return;

  SoundEffects.playClick();
  appState.driverActiveTrip.status = 'transit';
  localStorage.setItem('sabi_driver_active_trip', JSON.stringify(appState.driverActiveTrip));

  const idx = appState.customDeliveries.findIndex(d => d.id === tripId);
  if (idx !== -1) {
    appState.customDeliveries[idx].status = 'transit';
    localStorage.setItem('sabi_custom_deliveries', JSON.stringify(appState.customDeliveries));
    if (appState.activeComunidadTab === 'delivery') {
      renderDeliveryRequestPortal();
    }
  }

  showToast("Paquete Recogido", "Cargamento asegurado. Dirígete a la dirección de entrega.");
  renderAccountModal();
}

function handleDriverCompleteTrip(tripId) {
  if (!appState.driverActiveTrip || appState.driverActiveTrip.id !== tripId) return;

  SoundEffects.playJingle();
  const trip = appState.driverActiveTrip;
  
  // Earn based on dynamic commission rate
  const earnings = trip.price * (1 - getDriverCommissionRate());
  appState.driverWallet += earnings;
  localStorage.setItem('sabi_driver_wallet', appState.driverWallet.toString());

  const commission = trip.price * getDriverCommissionRate();
  appState.adminEarnings += commission;
  localStorage.setItem('sabi_admin_earnings', appState.adminEarnings.toString());

  // Increment distance in evaluation period
  let currentDistance = parseFloat(localStorage.getItem('sabi_driver_distance_period') || '0');
  currentDistance += 8.5;
  localStorage.setItem('sabi_driver_distance_period', currentDistance.toString());

  // Release Escrow Amount to the Seller (demo: add to user profile wallet)
  if (trip.escrowAmount && trip.escrowAmount > 0) {
    appState.userWallet += trip.escrowAmount;
    localStorage.setItem('sabi_user_wallet', appState.userWallet.toString());
    showToast("¡Dinero Liberado!", `Se han liberado Afl. ${trip.escrowAmount.toFixed(2)} AWG de la custodia y enviado al vendedor por la entrega.`);
  }

  const idx = appState.customDeliveries.findIndex(d => d.id === tripId);
  if (idx !== -1) {
    appState.customDeliveries[idx].status = 'delivered';
    localStorage.setItem('sabi_custom_deliveries', JSON.stringify(appState.customDeliveries));
    if (appState.activeComunidadTab === 'delivery') {
      renderDeliveryRequestPortal();
    }
  }

  appState.driverActiveTrip = null;
  localStorage.removeItem('sabi_driver_active_trip');

  // Also clear buyer's active trip if it was a checkout trip
  if (appState.activeTrip) {
    appState.activeTrip = null;
    localStorage.removeItem('sabi_active_trip');
  }

  // Referral Activation for Drivers (on first trip completed)
  if (!appState.userProfile.driverFirstTripCompleted) {
    appState.userProfile.driverFirstTripCompleted = true;
    localStorage.setItem('sabi_user_profile', JSON.stringify(appState.userProfile));
    
    if (supabaseClient) {
      supabaseClient.from('profiles').update({ driver_first_trip_completed: true }).eq('id', appState.userProfile.id);
    }
    
    const refBy = appState.userProfile.referredBy;
    if (refBy) {
      if (supabaseClient) {
        supabaseClient.from('profiles').select('*').eq('id', refBy).single().then(referrerRes => {
          if (!referrerRes.error && referrerRes.data) {
            const referrerData = referrerRes.data;
            let list = referrerData.referrals_list || [];
            
            const existingDriverIndex = list.findIndex(r => r.userId === appState.userProfile.id && r.type === 'driver');
            if (existingDriverIndex === -1) {
              list.push({
                userId: appState.userProfile.id,
                date: new Date().toISOString(),
                type: 'driver',
                active: true
              });
              
              const activeDrivers = list.filter(r => r.active && r.type === 'driver').length;
              
              supabaseClient.from('profiles').update({
                referred_drivers_count: (referrerData.referred_drivers_count || 0) + 1,
                referred_active_drivers: activeDrivers,
                referrals_list: list
              }).eq('id', referrerData.id).then(() => {
                console.log("Supabase: referrer active driver count updated.");
              });
            }
          }
        });
      } else {
        // Offline mode
        let accounts = [];
        try {
          const saved = localStorage.getItem('sabi_registered_accounts');
          if (saved) accounts = JSON.parse(saved);
        } catch(e) {}
        
        accounts.forEach(acc => {
          if (acc.profile) acc.profile = ensureProfileReferralData(acc.profile);
        });
        
        const referrerAcc = accounts.find(acc => acc.profile.id === refBy);
        if (referrerAcc) {
          const existingDriver = referrerAcc.profile.referralsList.find(r => r.userId === appState.userProfile.id && r.type === 'driver');
          if (!existingDriver) {
            referrerAcc.profile.referralsList.push({
              userId: appState.userProfile.id,
              date: new Date().toISOString(),
              type: 'driver',
              active: true
            });
            referrerAcc.profile.referredDriversCount = (referrerAcc.profile.referredDriversCount || 0) + 1;
            referrerAcc.profile.referredActiveDrivers = (referrerAcc.profile.referredActiveDrivers || 0) + 1;
            
            localStorage.setItem('sabi_registered_accounts', JSON.stringify(accounts));
            showToast("¡Referido Activado! 🎉", "Tu primer viaje activó el bono para quien te refirió.");
          }
        }
      }
    }
  }

  showToast("¡Viaje Completado!", `Has entregado con éxito el pedido. Recibiste Afl. ${earnings.toFixed(2)} AWG.`);
  renderAccountModal();
}

function handleUserProductUpload() {
  // Verificación mandatoria para Vendedores (Sellers)
  if (!appState.userProfile.persoonnummer || !appState.userProfile.persoonnummerDoc || 
      !appState.userProfile.bankAccount || !appState.userProfile.identityId || !appState.userProfile.identityDoc) {
    showToast(
      "Verificación Requerida", 
      "Para vender en el marketplace de Sabí, debes completar tu Configuración Bancaria, de Identidad y Fiscal (Persoonnummer + ID + Documentos) en la sección 'Perfil'.",
      8000
    );
    window.switchAccountTab('profile');
    return;
  }

  const title = document.getElementById("ad-modal-title").value.trim();
  const category = document.getElementById("ad-modal-category").value;
  const price = parseFloat(document.getElementById("ad-modal-price").value);
  const desc = document.getElementById("ad-modal-desc").value.trim();
  const contact = document.getElementById("ad-modal-contact").value.trim();
  const deliveryEnabled = document.getElementById("ad-modal-delivery-enabled").checked;

  if (!title || isNaN(price) || price <= 0 || !desc || !contact) {
    showToast("Error", "Completa todos los campos obligatorios.");
    return;
  }

  if (!validateProductIntellectualProperty(title, desc)) {
    return;
  }

  const presets = {
    "trabajo": "https://images.unsplash.com/photo-1521737711867-e3b904737d88?auto=format&fit=crop&w=400&q=80",
    "alquileres": "https://images.unsplash.com/photo-1568605114967-8130f3a36994?auto=format&fit=crop&w=400&q=80",
    "vehiculos": "https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=400&q=80",
    "ropa": "https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=400&q=80",
    "electronica": "https://images.unsplash.com/photo-1468436139062-f60a71c5c892?auto=format&fit=crop&w=400&q=80",
    "joyeria": "https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?auto=format&fit=crop&w=400&q=80",
    "hogar": "https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=400&q=80"
  };

  const customImgUrl = document.getElementById("ad-modal-image-url") ? document.getElementById("ad-modal-image-url").value.trim() : '';
  const adImg = customImgUrl || presets[category] || presets["electronica"];

  const metadata = readCategorySpecificFields(category);

  const newAd = {
    id: `ad-user-${Date.now()}`,
    category,
    title,
    price,
    desc,
    contact,
    image: adImg,
    date: new Date().toISOString().split('T')[0],
    user: appState.userProfile.name,
    sponsored: false,
    cpcBid: 0,
    clicks: 0,
    deliveryEnabled,
    metadata
  };

  appState.marketplaceAds.unshift(newAd);
  localStorage.setItem('sabi_marketplace_ads', JSON.stringify(appState.marketplaceAds));

  appState.userProducts.unshift(newAd);
  localStorage.setItem('sabi_user_products', JSON.stringify(appState.userProducts));

  SoundEffects.playJingle();
  showToast("Producto Publicado", `Has subido "${title}" a la Comunidad con éxito.`);

  if (appState.activeComunidadTab === 'market') {
    renderClassifieds();
  }

  appState.activeAccountTab = 'products';
  renderAccountModal();
}

