// ==========================================================================
// 🎫 SABÍ CRÉDITO (MICROLOANS PORTAL) - LÓGICA DE NEGOCIO Y RENDERIZADO
// ==========================================================================

// ==================== ETAPAS DE CRÉDITO SABÍ ====================
// Regla: cada etapa desbloquea la siguiente solo si el préstamo anterior se
// paga a tiempo y completo. Si el usuario paga tarde o no completa, vuelve a E1.
//
// Ejemplo: para llegar a AWG 5,000 tienes que haber pagado a tiempo:
//   - 1 préstamo completo en E1 (250–500)
//   - 1 préstamo completo en E2 (501–1,500)
//   - 1 préstamo completo en E3 (1,501–3,000)
// Recién entonces desbloqueas E4 (3,001–5,000).
const SABI_LOAN_STAGES = [
  { stage: 1, name: 'E1: Inicial',     min: 250,  max: 500,   maxTerm: 3,  apr: 0.06 },
  { stage: 2, name: 'E2: Probada',     min: 501,  max: 1500,  maxTerm: 6,  apr: 0.08 },
  { stage: 3, name: 'E3: Confiable',   min: 1501, max: 3000,  maxTerm: 9,  apr: 0.07 },
  { stage: 4, name: 'E4: Leal',        min: 3001, max: 5000,  maxTerm: 12, apr: 0.06 },
  { stage: 5, name: 'E5: Embajador/a', min: 5001, max: 10000, maxTerm: 24, apr: 0.05 }
];

const SABI_CREDIT_MIN_AMOUNT = SABI_LOAN_STAGES[0].min;
const SABI_CREDIT_MAX_AMOUNT = SABI_LOAN_STAGES[SABI_LOAN_STAGES.length - 1].max;
const SABI_CREDIT_LONG_TERM_THRESHOLD = 3000;

function getUnlockedStage() {
  // Etapa desbloqueada = current credit tier (1..5). Se asume que ya subió
  // escalonado tras cada pago completo a tiempo.
  return Math.min(5, Math.max(1, parseInt(appState.creditTier || 1, 10)));
}

function getStageForAmount(amount) {
  // Etapa a la que pertenece un monto dado (no necesariamente desbloqueada).
  return SABI_LOAN_STAGES.find(s => amount >= s.min && amount <= s.max) || null;
}

function getCurrentStageConfig() {
  return SABI_LOAN_STAGES[getUnlockedStage() - 1];
}

function getAllowedLoanTermsForStage(stageIndex) {
  const stage = SABI_LOAN_STAGES[stageIndex];
  if (!stage) return [];
  // Ofrecemos divisores comunes hasta el máximo de la etapa
  const base = [1, 2, 3];
  if (stage.maxTerm >= 6) base.push(6);
  if (stage.maxTerm >= 9) base.push(9);
  if (stage.maxTerm >= 12) base.push(12);
  if (stage.maxTerm >= 18) base.push(18);
  if (stage.maxTerm >= 24) base.push(24);
  return base.filter(t => t <= stage.maxTerm);
}

function getAllowedLoanTerms(amount) {
  // Compatibilidad: si la cantidad cae dentro de la etapa desbloqueada,
  // mostramos los plazos de esa etapa. Si no, permitimos plazos más cortos
  // para que el usuario explore.
  const unlockedIdx = getUnlockedStage() - 1;
  const stage = getStageForAmount(amount);
  if (!stage) return [1, 2, 3];
  if (stage.stage <= getUnlockedStage()) {
    return getAllowedLoanTermsForStage(stage.stage - 1);
  }
  // Monto fuera de etapa desbloqueada → solo plazos cortos de E1
  return getAllowedLoanTermsForStage(unlockedIdx).filter(t => t <= 3);
}

function getMaxLoanTermForAmount(amount) {
  const terms = getAllowedLoanTerms(amount);
  return terms[terms.length - 1];
}

function renderLoanTermOptions(amount, selectedTerm = 3) {
  const terms = getAllowedLoanTerms(amount);
  const safeSelected = terms.includes(parseInt(selectedTerm, 10)) ? parseInt(selectedTerm, 10) : terms[terms.length - 1] || 3;
  return terms.map(term => `<option value="${term}" ${term === safeSelected ? 'selected' : ''}>${term} ${term === 1 ? 'Mes' : 'Meses'}</option>`).join('');
}

function getStageAPR(stageIdx, purpose) {
  const base = SABI_LOAN_STAGES[stageIdx]?.apr ?? 0.06;
  // Ajuste pequeño por propósito (mantener la lógica social)
  let adj = 0;
  if (purpose === 'education') adj = -0.01;
  else if (purpose === 'personal') adj = 0.01;
  else if (purpose === 'refinance') adj = 0.00;
  return Math.max(0.04, base + adj);
}

// Mantenemos la firma getCreditTierDetails para no romper otras partes del código.
// Devuelve un objeto con los datos de la etapa actual.
function getCreditTierDetails(tier) {
  const idx = Math.min(5, Math.max(1, parseInt(tier, 10) || 1)) - 1;
  const stage = SABI_LOAN_STAGES[idx];
  return {
    name: stage.name,
    limit: stage.max,
    aprDiscount: 0, // ya no se usa como descuento; la tasa vive en la etapa
    maxTerm: stage.maxTerm,
    min: stage.min,
    apr: stage.apr,
    stage: stage.stage
  };
}

// ==================== CREDIT SCORE (FICO-style 300-850) ====================
// Calcula score basado en: tier (base), pagos a tiempo, uso, antigüedad
function calculateCreditScore() {
  const tier = appState.creditTier || 1;
  const onTimePayments = appState.onTimePayments || 0;
  const latePayments = appState.latePayments || 0;
  const activeLoan = appState.activeLoan;

  // Base score por tier (300-600)
  let baseScore = 300 + ((tier - 1) * 75); // T1=300, T2=375, T3=450, T4=525, T5=600

  // Pagos a tiempo (+10 c/u, max +100)
  const paymentBonus = Math.min(onTimePayments * 10, 100);

  // Pagos tardíos (-20 c/u)
  const latePenalty = latePayments * 20;

  // Préstamo activo: uso responsable (+50 si está al día, -50 si mora)
  let activeLoanBonus = 0;
  if (activeLoan) {
    const remainingPct = activeLoan.remainingRepayment / activeLoan.totalRepayment;
    if (remainingPct < 0.5) {
      activeLoanBonus = 50; // Más de 50% pagado = muy bien
    } else if (remainingPct > 0.9) {
      activeLoanBonus = -30; // Casi sin pagar = mal
    }
  } else {
    // Si nunca tuvo préstamo, pero tiene historial de tienda/compras = +50
    if (appState.userShop || (appState.marketplaceAds && appState.marketplaceAds.length > 0)) {
      activeLoanBonus = 30;
    }
  }

  // Antigüedad de cuenta (simulada por ahora)
  const accountAgeBonus = Math.min(onTimePayments * 5, 50);

  // Calcular final
  let finalScore = baseScore + paymentBonus - latePenalty + activeLoanBonus + accountAgeBonus;

  // Clamp a 300-850
  finalScore = Math.max(300, Math.min(850, finalScore));

  return finalScore;
}

function getCreditScoreColor(score) {
  if (score >= 750) return 'var(--neon-emerald)';
  if (score >= 700) return 'var(--neon-cyan)';
  if (score >= 650) return 'var(--neon-gold)';
  if (score >= 600) return '#f39c12';
  return 'var(--neon-pink)';
}

function getCreditScoreLabel(score) {
  if (score >= 800) return 'Excelente';
  if (score >= 750) return 'Muy Bueno';
  if (score >= 700) return 'Bueno';
  if (score >= 650) return 'Regular';
  if (score >= 600) return 'Bajo';
  return 'Muy Bajo';
}

function isUserSuspended() {
  if (!appState.loanSuspensionUntil) return false;
  const now = Date.now();
  const suspensionTime = parseInt(appState.loanSuspensionUntil, 10);
  if (isNaN(suspensionTime)) return false;
  if (now < suspensionTime) {
    return true;
  } else {
    appState.loanSuspensionUntil = null;
    localStorage.removeItem('sabi_loan_suspension_until');
    return false;
  }
}

function isUserBlockedForCredit() {
  // Verificar si está bloqueado por 2 strikes (2 años de bloqueo)
  if (!appState.creditBlockedUntil) return false;
  const now = Date.now();
  const blockedTime = parseInt(appState.creditBlockedUntil, 10);
  if (isNaN(blockedTime)) return false;
  if (now < blockedTime) {
    return true;
  } else {
    // El bloqueo expiró, limpiar
    appState.creditBlockedUntil = null;
    localStorage.removeItem('sabi_credit_blocked_until');
    return false;
  }
}

function getBlockedTimeRemaining() {
  if (!appState.creditBlockedUntil) return null;
  const remaining = parseInt(appState.creditBlockedUntil, 10) - Date.now();
  if (remaining <= 0) return null;
  const days = Math.floor(remaining / (24 * 60 * 60 * 1000));
  return days;
}

function getStrikeHistory() {
  return JSON.parse(localStorage.getItem('sabi_strike_history') || '[]');
}

function formatStrikeDate(isoString) {
  const d = new Date(isoString);
  return d.toLocaleDateString('es-AR', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

