async function searchArubaCompanies() {
  const queryText = document.getElementById("directory-comercial-search-input").value.trim();
  const districtFilter = document.getElementById("directory-comercial-district-filter").value;
  const resultsContainer = document.getElementById("directory-comercial-results-container");

  if (!resultsContainer) return;

  if (queryText.length < 2 && districtFilter === 'all') {
    resultsContainer.innerHTML = `<p class="text-muted small text-center">Disculpas, por favor escribe al menos 2 letras para iniciar la búsqueda.</p>`;
    return;
  }

  try {
    resultsContainer.innerHTML = `<p class="text-center small" style="color: var(--neon-gold);">⏳ Consultando registro de empresas activas...</p>`;

    if (!supabaseClient) {
      setTimeout(() => {
        const mockCompanies = [
          { company_name: "Noord Delight Bakery", district: "Noord", kvk_number: "K-12345", legal_form: "Eenmanszaak", is_active: true, phone: "+297 586-1234" },
          { company_name: "Oranjestad Pharmacy / Botica", district: "Oranjestad", kvk_number: "K-67890", legal_form: "N.V.", is_active: true, phone: "+297 582-5678" },
          { company_name: "Santa Cruz Grill House", district: "Santa Cruz", kvk_number: "K-11223", legal_form: "V.O.F.", is_active: true, phone: "+297 585-4321" },
          { company_name: "Savaneta Seafood Market", district: "Savaneta", kvk_number: "K-44556", legal_form: "N.V.", is_active: false, phone: "" }
        ];
        
        let filtered = mockCompanies;
        if (queryText.length >= 2) {
          filtered = filtered.filter(c => c.company_name.toLowerCase().includes(queryText.toLowerCase()));
        }
        if (districtFilter !== 'all') {
          filtered = filtered.filter(c => c.district === districtFilter);
        }
        
        if (filtered.length === 0) {
          resultsContainer.innerHTML = `<p class="text-muted small text-center">No se encontraron compañías activas que coincidan con la búsqueda.</p>`;
          return;
        }
        
        resultsContainer.innerHTML = filtered.map(company => `
          <div style="background: rgba(255,255,255,0.02); border: 1px solid var(--glass-border); padding: 0.85rem; border-radius: 12px; display: flex; justify-content: space-between; align-items: center; text-align: left;">
            <div>
              <h4 style="margin: 0 0 2px 0; font-size: 0.9rem; font-weight: 700; color: var(--text-light);">${company.company_name}</h4>
              <p style="margin: 0; font-size: 0.7rem; color: var(--text-muted);">
                📍 ${company.district} | KvK: <strong>${company.kvk_number}</strong> | Tipo: ${company.legal_form}
              </p>
            </div>
            <div style="text-align: right;">
              <span style="font-size: 0.65rem; padding: 4px 8px; border-radius: 20px; font-weight: bold; background: ${company.is_active ? 'rgba(0,255,128,0.1)' : 'rgba(255,51,102,0.1)'}; color: ${company.is_active ? '#00ff80' : '#ff3366'}; border: 1px solid ${company.is_active ? 'rgba(0,255,128,0.2)' : 'rgba(255,51,102,0.2)'};">
                ${company.is_active ? 'Activa' : 'Inactiva'}
              </span>
              ${company.phone ? `<a href="tel:${company.phone}" style="display:block; margin-top: 6px; font-size: 0.75rem; color: var(--neon-gold); text-decoration: none;">📞 ${company.phone}</a>` : ''}
            </div>
          </div>
        `).join('');
      }, 800);
      return;
    }

    let query = supabaseClient
      .from('aruba_companies_directory')
      .select('*');

    if (queryText.length >= 2) {
      query = query.ilike('company_name', `%${queryText}%`);
    }
    if (districtFilter !== 'all') {
      query = query.eq('district', districtFilter);
    }

    const { data: companies, error } = await query.limit(20);

    if (error) throw error;

    if (!companies || companies.length === 0) {
      resultsContainer.innerHTML = `<p class="text-muted small text-center">No se encontraron compañías activas que coincidan con la búsqueda.</p>`;
      return;
    }

    resultsContainer.innerHTML = companies.map(company => `
      <div style="background: rgba(255,255,255,0.02); border: 1px solid var(--glass-border); padding: 0.85rem; border-radius: 12px; display: flex; justify-content: space-between; align-items: center; text-align: left;">
        <div>
          <h4 style="margin: 0 0 2px 0; font-size: 0.9rem; font-weight: 700; color: var(--text-light);">${company.company_name}</h4>
          <p style="margin: 0; font-size: 0.7rem; color: var(--text-muted);">
            📍 ${company.district} | KvK: <strong>${company.kvk_number}</strong> | Tipo: ${company.legal_form}
          </p>
        </div>
        <div style="text-align: right;">
          <span style="font-size: 0.65rem; padding: 4px 8px; border-radius: 20px; font-weight: bold; background: ${company.is_active ? 'rgba(0,255,128,0.1)' : 'rgba(255,51,102,0.1)'}; color: ${company.is_active ? '#00ff80' : '#ff3366'}; border: 1px solid ${company.is_active ? 'rgba(0,255,128,0.2)' : 'rgba(255,51,102,0.2)'};">
            ${company.is_active ? 'Activa' : 'Inactiva'}
          </span>
          ${company.phone ? `<a href="tel:${company.phone}" style="display:block; margin-top: 6px; font-size: 0.75rem; color: var(--neon-gold); text-decoration: none;">📞 ${company.phone}</a>` : ''}
        </div>
      </div>
    `).join('');

  } catch (err) {
    console.error("Error al consultar el directorio de empresas:", err);
    resultsContainer.innerHTML = `<p class="text-center small" style="color: #ff3366;">Disculpas, ocurrió un error al consultar el registro comercial.</p>`;
  }
}

