function switchImportSubTab(subTab) {
  const panelAuto = document.getElementById("import-panel-auto");
  const panelChnAuto = document.getElementById("import-panel-china-auto");
  const panelUsa  = document.getElementById("import-panel-usa");
  const panelCol  = document.getElementById("import-panel-colombia");
  const panelChn  = document.getElementById("import-panel-china");
  const panelCalc = document.getElementById("import-panel-calc");

  const btnAuto = document.getElementById("import-subtab-btn-auto");
  const btnChnAuto = document.getElementById("import-subtab-btn-china-auto");
  const btnUsa  = document.getElementById("import-subtab-btn-usa");
  const btnCol  = document.getElementById("import-subtab-btn-colombia");
  const btnChn  = document.getElementById("import-subtab-btn-china");
  const btnCalc = document.getElementById("import-subtab-btn-calc");

  if (!panelAuto || !btnAuto) return;
  appState.activeImportSubTab = subTab;

  // Reset all panels
  if (panelAuto)    panelAuto.style.display    = "none";
  if (panelChnAuto) panelChnAuto.style.display = "none";
  if (panelUsa)     panelUsa.style.display     = "none";
  if (panelCol)     panelCol.style.display     = "none";
  if (panelChn)     panelChn.style.display     = "none";
  if (panelCalc)    panelCalc.style.display    = "none";

  // Reset all buttons styling
  const reset = (btn) => { if (btn) { btn.style.background = "transparent"; btn.style.color = "var(--text-muted)"; } };
  reset(btnAuto); reset(btnChnAuto); reset(btnUsa); reset(btnCol); reset(btnChn); reset(btnCalc);

  try {
    SoundEffects.playClick();
  } catch(e) {}

  if (subTab === 'china-auto') {
    if (panelChnAuto) panelChnAuto.style.display = "block";
    if (btnChnAuto) { btnChnAuto.style.background = "linear-gradient(135deg, var(--neon-purple), var(--neon-pink))"; btnChnAuto.style.color = "#fff"; }
    appState.activeImportCountry = 'china-auto';
    if (typeof window.renderChinaAutoImport === 'function') {
      window.renderChinaAutoImport();
    }
  } else if (subTab === 'auto') {
    if (panelAuto) panelAuto.style.display = "block";
    if (btnAuto) { btnAuto.style.background = "var(--neon-cyan)"; btnAuto.style.color = "#000"; }
  } else if (subTab === 'usa') {
    if (panelUsa) panelUsa.style.display = "block";
    if (btnUsa) { btnUsa.style.background = "var(--neon-cyan)"; btnUsa.style.color = "#000"; }
    appState.activeImportCountry = 'usa';
    renderSabiImportShop();
  } else if (subTab === 'colombia') {
    if (panelCol) panelCol.style.display = "block";
    if (btnCol) { btnCol.style.background = "var(--neon-cyan)"; btnCol.style.color = "#000"; }
    appState.activeImportCountry = 'colombia';
    renderSabiImportShop();
  } else if (subTab === 'china') {
    if (panelChn) panelChn.style.display = "block";
    if (btnChn) { btnChn.style.background = "var(--neon-cyan)"; btnChn.style.color = "#000"; }
    appState.activeImportCountry = 'china';
    renderSabiImportShop();
  } else if (subTab === 'calc') {
    if (panelCalc) panelCalc.style.display = "block";
    if (btnCalc) { btnCalc.style.background = "var(--neon-cyan)"; btnCalc.style.color = "#000"; }
  } else {
    // Default fallback to auto
    if (panelAuto) panelAuto.style.display = "block";
    if (btnAuto) { btnAuto.style.background = "var(--neon-cyan)"; btnAuto.style.color = "#000"; }
  }
}
window.switchImportSubTab = switchImportSubTab;

