  const country = appState.activeImportCountry || 'usa';
  let gridId = "sabi-shop-grid-usa";
  if (country === 'colombia') gridId = "sabi-shop-grid-colombia";
  if (country === 'china') gridId = "sabi-shop-grid-china";

  const container = document.getElementById(gridId);
  if (!container) return;

  const activeCat = window.activeShopCategory || "all";
  let html = "";

