function handleAmazonProductAction(productId) {
  const p = SABI_AMAZON_PRODUCTS.find(prod => prod.id === productId);
  if (!p) return;

  try {
    SoundEffects.playClick();
  } catch(e) {}

  // Sincronizar clic de USA con Supabase para analíticas
  if (supabaseClient) {
    const userId = appState.userProfile ? appState.userProfile.id : null;
    const priceAWG = (p.priceUSD || 0) * 1.79;
    supabaseClient.from('usa_clicks').insert({
      user_id: userId,
      product_id: p.id || p.asin || '',
      product_title: p.title || p.spec || '',
      price_awg: priceAWG
    }).then(({ error }) => {
      if (error) console.error("Error saving USA click to DB:", error);
    });
  }

  if (p.hasDirectShipping) {
    showToast("Redirigiendo a Amazon...", "Cargando producto con envío directo a Aruba y afiliación de Sabí.");
    setTimeout(() => {
      window.open(p.amazonUrl, "_blank");
    }, 1200);
  } else {
    const addressText = "Amaury Maduro - Sabí Box\n8400 NW 25th Street\nSuite SABI-8842\nMiami, FL 33198\nPhone: +1 (305) 555-0199";
    navigator.clipboard.writeText(addressText).then(() => {
      showToast("📋 Casillero Copiado", "Dirección de Miami copiada. Regístrala en Amazon. Abriendo web...");
      
      setTimeout(() => {
        const container = document.getElementById("import-tracking-container");
        if (container) {
          const trackingId = "SABI-" + Math.floor(100000 + Math.random() * 900000);
          const arubaTimeStr = new Date().toLocaleTimeString('es-ES', {
            timeZone: 'America/Curacao',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit'
          });

          const newTrackingHtml = `
            <div style="background: rgba(0,243,255,0.04); border: 1px solid var(--neon-cyan); padding: 1rem; border-radius: 12px; font-size: 0.8rem; text-align: left; animation: fadeIn 0.5s ease; margin-bottom: 0.5rem;">
              <div style="display: flex; justify-content: space-between; font-weight: 700; margin-bottom: 0.35rem;">
                <span style="color: var(--text-main);">📦 ${p.title} (Pre-alertado)</span>
                <span style="color: var(--neon-cyan);">En Miami 🏢</span>
              </div>
              <div style="width: 100%; height: 4px; background: rgba(255,255,255,0.05); border-radius: 10px; overflow: hidden; margin-bottom: 6px;">
                <div style="width: 25%; height: 100%; background: var(--neon-cyan); box-shadow: 0 0 8px var(--neon-cyan);"></div>
              </div>
              <div style="display:flex; justify-content:space-between; font-size: 0.65rem; color: var(--text-muted); margin-bottom: 4px;">
                <span>Casillero: SABI-8842</span>
                <span>Fulfillment: ${arubaTimeStr} (AST)</span>
              </div>
              <div style="display:flex; justify-content:space-between; font-size: 0.65rem; color: var(--text-muted);">
                <span>ID: ${trackingId}</span>
                <span>Est. Entrega: 5-7 días</span>
              </div>
            </div>
          `;
          container.insertAdjacentHTML('afterbegin', newTrackingHtml);
        }
        window.open(p.amazonUrl, "_blank");
      }, 1500);
    }).catch(err => {
      showToast("Redirigiendo a Amazon...", "Carga el producto para comprar con tu casillero en Miami.");
      window.open(p.amazonUrl, "_blank");
    });
  }
}
window.handleAmazonProductAction = handleAmazonProductAction;

async function handleChinaProductAction(productId) {
  const p = (appState.cjProductsRegistry && appState.cjProductsRegistry[productId]) || SABI_CHINA_PRODUCTS.find(prod => prod.id === productId);
  if (!p) return;

  const price = calculateChinaAWG(p.priceUSD, p.weightLbs, p.shippingCostUSD);

  if (appState.userWallet < price.total) {
    if (typeof SoundEffects !== 'undefined' && SoundEffects.playAlert) {
      SoundEffects.playAlert();
    }
    showToast("Saldo Insuficiente", "Recarga fondos en tu billetera Sabí-Pay para procesar tu orden directa de China.");
    return;
  }

  // Deduct wallet balance
  appState.userWallet -= price.total;
  localStorage.setItem('sabi_wallet_balance', appState.userWallet.toFixed(2));
  
  const walletVal = document.getElementById("wallet-balance-val");
  if (walletVal) walletVal.innerText = `Afl. ${appState.userWallet.toFixed(2)} AWG`;

  // Point 3: Sync platform markup to Admin earnings in real time (converted to AWG using 1.79 rate)
  const markupAWG = price.markupUSD * 1.79;
  appState.adminEarnings = (appState.adminEarnings || 0) + markupAWG;
  localStorage.setItem('sabi_admin_earnings', appState.adminEarnings.toFixed(2));

  if (typeof SoundEffects !== 'undefined' && SoundEffects.playJingle) {
    SoundEffects.playJingle();
  }
  
  showToast("Procesando...", "Conectando con CJ Dropshipping API...", 2500);

  // Call CJ API order creation (Sandbox)
  const orderRes = await createCJOrder(p.title, p.sku, p.variantId, p.priceUSD);
  const trackingId = orderRes && orderRes.cjOrderId ? orderRes.cjOrderId : ("CJ-" + Math.floor(10000000 + Math.random() * 90000000) + "-CN");

  showToast("¡Pedido Recibido!", `Tu pedido de '${p.title}' ha sido procesado mediante CJ Auto-Order en China.`);

  // Point 1: Get current time converted to Aruba AST (UTC-4)
  const arubaTimeStr = new Date().toLocaleTimeString('es-ES', {
    timeZone: 'America/Curacao',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  });

  setTimeout(() => {
    const container = document.getElementById("import-tracking-container");
    if (container) {
      const isSandboxOrder = orderRes && orderRes.status === "success";
      const statusBadge = isSandboxOrder ? "Procesado CJ (Sandbox) 🤖" : "En Tránsito ✈️";
      const courierName = isSandboxOrder ? "CJ Dropshipping API Fulfillment" : "CJ Logistics (Asia)";
      
      const newTrackingHtml = `
        <div style="background: rgba(0, 255, 128, 0.04); border: 1px solid #00ff80; padding: 1rem; border-radius: 12px; font-size: 0.8rem; text-align: left; animation: fadeIn 0.5s ease; margin-bottom: 0.5rem;">
          <div style="display: flex; justify-content: space-between; font-weight: 700; margin-bottom: 0.35rem;">
            <span style="color: var(--text-main); display:inline-block; max-width:70%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">🇨🇳 ${p.title}</span>
            <span style="color: #00ff80;">${statusBadge}</span>
          </div>
          <div style="width: 100%; height: 4px; background: rgba(255,255,255,0.05); border-radius: 10px; overflow: hidden; margin-bottom: 6px;">
            <div style="width: 50%; height: 100%; background: #00ff80; box-shadow: 0 0 8px #00ff80;"></div>
          </div>
          <div style="display:flex; justify-content:space-between; font-size: 0.65rem; color: var(--text-muted); margin-bottom: 4px;">
            <span>Courier: ${courierName}</span>
            <span>Fulfillment: ${arubaTimeStr} (AST)</span>
          </div>
          <div style="display:flex; justify-content:space-between; font-size: 0.65rem; color: var(--text-muted);">
            <span>Seguimiento: ${trackingId}</span>
            <span>Est. Entrega: 12-15 días</span>
          </div>
        </div>
      `;
      container.insertAdjacentHTML('afterbegin', newTrackingHtml);
    }
  }, 1000);
}
window.handleChinaProductAction = handleChinaProductAction;

// --- Colombia Pre-Order & Sizing Flow ---
window.activeColombiaProductId = null;

function openColombiaOrderModal(productId) {
  const p = SABI_COLOMBIA_PRODUCTS.find(prod => prod.id === productId);
  if (!p) return;

  window.activeColombiaProductId = productId;
  const price = calculateColombiaAWG(p.priceCostCOP, p.weightLbs);
  
  const detailEl = document.getElementById("colombia-modal-product-details");
  if (detailEl) {
    detailEl.innerHTML = `
      <div style="display:flex; gap:0.75rem; align-items:center">
        <span style="font-size:2.5rem">${p.image}</span>
        <div>
          <h4 style="margin:0; font-weight:800; color:white">${p.title}</h4>
          <p style="margin:2px 0 0 0; font-size:0.75rem; color:var(--text-muted)">Precio: <strong style="color:var(--neon-cyan)">Afl. ${price.total.toFixed(2)} AWG</strong></p>
        </div>
      </div>
    `;
  }

  const modal = document.getElementById("colombia-order-modal");
  if (modal) {
    modal.style.display = "flex";
  }
}
window.openColombiaOrderModal = openColombiaOrderModal;

function closeColombiaOrderModal() {
  const modal = document.getElementById("colombia-order-modal");
  if (modal) {
    modal.style.display = "none";
  }
}
window.closeColombiaOrderModal = closeColombiaOrderModal;

function submitColombiaPreOrder() {
  const productId = window.activeColombiaProductId;
  const p = SABI_COLOMBIA_PRODUCTS.find(prod => prod.id === productId);
  if (!p) return;

  const size = document.getElementById("colombia-modal-size").value;
  const quantity = parseInt(document.getElementById("colombia-modal-quantity").value) || 1;
  const price = calculateColombiaAWG(p.priceCostCOP, p.weightLbs);
  const totalAWG = price.total * quantity;

  if (appState.userWallet < totalAWG) {
    SoundEffects.playAlert();
    showToast("Saldo Insuficiente", "Recarga fondos en tu billetera Sabí-Pay para pre-autorizar esta compra.");
    return;
  }

  // Pre-authorize payment (Stripe Hold Simulation)
  appState.userWallet -= totalAWG;
  localStorage.setItem('sabi_wallet_balance', appState.userWallet.toFixed(2));
  
  const walletVal = document.getElementById("wallet-balance-val");
  if (walletVal) walletVal.innerText = `Afl. ${appState.userWallet.toFixed(2)} AWG`;

  // Create Pre-order
  const supplier = SABI_COLOMBIA_SUPPLIERS.find(s => s.id === p.supplierId) || SABI_COLOMBIA_SUPPLIERS[0];
  const orderId = "COL-" + Math.floor(100000 + Math.random() * 900000);
  const stripeHoldId = "ch_hold_" + Math.floor(10000000 + Math.random() * 90000000);
  
  // Get current time converted to Aruba AST (UTC-4)
  const arubaTimeStr = new Date().toLocaleTimeString('es-ES', {
    timeZone: 'America/Curacao',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  });

  const newOrder = {
    id: orderId,
    productId: p.id,
    title: p.title,
    image: p.image,
    priceCostCOP: p.priceCostCOP,
    totalAWG: totalAWG,
    size: size,
    quantity: quantity,
    status: "esperando_confirmacion_fab",
    supplierId: supplier.id,
    supplierName: supplier.brandName,
    supplierPhone: supplier.phone,
    stripeHoldId: stripeHoldId,
    date: new Date().toLocaleDateString(),
    createdAtStr: arubaTimeStr
  };

  appState.colombiaPreOrders.push(newOrder);
  localStorage.setItem('sabi_colombia_preorders', JSON.stringify(appState.colombiaPreOrders));

  SoundEffects.playJingle();
  showToast("Pre-Orden Registrada", "Fondos retenidos con Stripe Hold. Esperando confirmación de bodega.");

  renderImportTrackingList();

  closeColombiaOrderModal();
  renderAdminDashboard();
}
window.submitColombiaPreOrder = submitColombiaPreOrder;

// --- Colombia Admin Action Handlers ---
function adminUploadColProduct() {
  const title = document.getElementById("admin-col-title").value.trim();
  const desc = document.getElementById("admin-col-desc").value.trim();
  const cat = document.getElementById("admin-col-cat").value;
  const supId = document.getElementById("admin-col-sup").value;
  const priceCOP = parseFloat(document.getElementById("admin-col-cop").value) || 0;
  const emoji = document.getElementById("admin-col-emoji").value.trim() || "📦";

  if (!title || !desc || priceCOP <= 0) return;

  if (!validateProductIntellectualProperty(title, desc)) {
    return;
  }

  const newProd = {
    id: "col-prod-" + (SABI_COLOMBIA_PRODUCTS.length + 1),
    supplierId: supId,
    category: cat,
    title: title,
    description: desc,
    priceCostCOP: priceCOP,
    weightLbs: 1.2,
    image: emoji,
    status_disponibilidad: true
  };

  SABI_COLOMBIA_PRODUCTS.push(newProd);
  localStorage.setItem('sabi_col_products', JSON.stringify(SABI_COLOMBIA_PRODUCTS));

  // Reset inputs
  document.getElementById("admin-col-title").value = "";
  document.getElementById("admin-col-desc").value = "";
  document.getElementById("admin-col-cop").value = "";
  document.getElementById("admin-col-emoji").value = "";

  SoundEffects.playJingle();
  showToast("Producto Cargado", "El producto ha sido inyectado en el catálogo y está disponible en la app.");

  renderAdminDashboard();
  renderSabiImportShop();
}
window.adminUploadColProduct = adminUploadColProduct;

function dispatchWhatsAppAlert(orderId) {
  const ord = appState.colombiaPreOrders.find(o => o.id === orderId);
  if (!ord) return;

  const text = encodeURIComponent(`Hola ${ord.supplierName}, tengo esta pre-orden de Sabí Super-App (Aruba) lista para reservar:\n\n📦 ${ord.title}\nTalla: ${ord.size}\nCantidad: ${ord.quantity}\nID Pedido: ${ord.id}\n\n¿Tienes disponibilidad en bodega física para confirmar despacho?`);
  
  showToast("Ficha Copiada", "Mensaje de WhatsApp abierto. Pegándolo en el chat con el fabricante...");
  
  setTimeout(() => {
    window.open(`https://wa.me/${ord.supplierPhone}?text=${text}`, "_blank");
  }, 1000);
}
window.dispatchWhatsAppAlert = dispatchWhatsAppAlert;

function confirmSupplierStock(orderId) {
  const ord = appState.colombiaPreOrders.find(o => o.id === orderId);
  if (!ord) return;

  ord.status = "ready_for_local_consolidation";
  localStorage.setItem('sabi_colombia_preorders', JSON.stringify(appState.colombiaPreOrders));

  const currentBal = appState.supplierBalances[ord.supplierId] || 0;
  appState.supplierBalances[ord.supplierId] = currentBal + (ord.priceCostCOP * ord.quantity);
  localStorage.setItem('sabi_supplier_balances', JSON.stringify(appState.supplierBalances));

  SoundEffects.playJingle();
  showToast("Hold Stripe Cobrado", `Fondo de Afl. ${ord.totalAWG.toFixed(2)} cobrado. Pedido listo para consolidación marítima.`);

  const statusEl = document.getElementById(`tracking-status-${orderId}`);
  const progressEl = document.getElementById(`tracking-progress-${orderId}`);
  if (statusEl) {
    statusEl.innerHTML = "Cobrado & Consolidado 📦";
    statusEl.style.color = "var(--neon-cyan)";
  }
  if (progressEl) {
    progressEl.style.width = "75%";
  }

  renderAdminDashboard();
}
window.confirmSupplierStock = confirmSupplierStock;

function cancelSupplierOrder(orderId) {
  const ord = appState.colombiaPreOrders.find(o => o.id === orderId);
  if (!ord) return;

  ord.status = "cancelled_no_stock";
  localStorage.setItem('sabi_colombia_preorders', JSON.stringify(appState.colombiaPreOrders));

  appState.userWallet += ord.totalAWG;
  localStorage.setItem('sabi_wallet_balance', appState.userWallet.toFixed(2));
  
  const walletVal = document.getElementById("wallet-balance-val");
  if (walletVal) walletVal.innerText = `Afl. ${appState.userWallet.toFixed(2)} AWG`;

  SoundEffects.playAlert();
  showToast("Orden Cancelada", `Hold de Stripe liberado. Fondos desbloqueados e ingresados de vuelta en la billetera.`);

  const statusEl = document.getElementById(`tracking-status-${orderId}`);
  const progressEl = document.getElementById(`tracking-progress-${orderId}`);
  if (statusEl) {
    statusEl.innerHTML = "Sin Stock (Cancelado) ❌";
    statusEl.style.color = "var(--neon-pink)";
  }
  if (progressEl) {
    progressEl.style.width = "100%";
    progressEl.style.background = "var(--neon-pink)";
  }

  renderAdminDashboard();
}
window.cancelSupplierOrder = cancelSupplierOrder;

