function getChinaAutoQuotes() {
  try {
    return JSON.parse(localStorage.getItem('sabi_china_auto_quotes') || '{}');
  } catch(e) {
    return {};
  }
}

function saveChinaAutoQuotes(quotes) {
  localStorage.setItem('sabi_china_auto_quotes', JSON.stringify(quotes));
}

function calculateChinaAutoLanded(car) {
  const rateUSD_AWG = 1.80;
  const cifUSD = car.fobUSD + car.inspectionUSD + car.oceanUSD;
  const cifAWG = cifUSD * rateUSD_AWG;
  const dutyAWG = cifAWG * (car.arubaDutyPct || 0.12);
  const bboAWG = (cifAWG + dutyAWG) * (car.bboPct || 0.07);
  const sabiFeeAWG = cifAWG * (car.sabiFeePct || 0.04);
  const gbtAdapterAWG = car.gbtAdapterUSD * rateUSD_AWG;
  const totalAWG = cifAWG + dutyAWG + bboAWG + sabiFeeAWG + gbtAdapterAWG;
  const totalUSD = totalAWG / rateUSD_AWG;

  return {
    cifUSD, cifAWG, dutyAWG, bboAWG, sabiFeeAWG, gbtAdapterAWG, totalAWG, totalUSD,
    fobAWG: car.fobUSD * rateUSD_AWG,
    inspectionAWG: car.inspectionUSD * rateUSD_AWG,
    oceanAWG: car.oceanUSD * rateUSD_AWG
  };
}

function renderChinaAutoImport() {
  const container = document.getElementById('sabi-shop-grid-china-auto');
  if (!container) return;

  const quotes = getChinaAutoQuotes();

  let html = '';
  SABI_CHINA_AUTO_MODELS.forEach(car => {
    const calc = calculateChinaAutoLanded(car);
    const quote = quotes[car.id] || { status: 'initial' };

    let buttonHtml = '';
    let statusNotice = '';

    if (quote.status === 'initial') {
      buttonHtml = `
        <button onclick="window.openChinaAutoQuoteModal('${car.id}')" class="btn" style="width:100%; padding:0.65rem 1rem; border-radius:12px; font-weight:800; font-size:0.85rem; border:none; cursor:pointer; background:linear-gradient(135deg, var(--neon-purple), var(--neon-pink)); color:white; box-shadow:0 4px 14px rgba(255,0,128,0.3); transition:all 0.2s;">
          📝 Cotizar y Verificar Disponibilidad
        </button>`;
      statusNotice = `<span style="font-size:0.7rem; color:var(--text-muted); display:block; text-align:center; margin-top:4px;">⏱️ Verificación directa con fabricante (2 a 48h)</span>`;
    } else if (quote.status === 'verificando') {
      buttonHtml = `
        <button disabled class="btn" style="width:100%; padding:0.65rem 1rem; border-radius:12px; font-weight:800; font-size:0.82rem; border:1px solid var(--neon-gold); cursor:not-allowed; background:rgba(255,188,5,0.15); color:var(--neon-gold);">
          ⏳ Verificando Disponibilidad (2 - 48h)
        </button>`;
      statusNotice = `
        <div style="font-size:0.7rem; color:var(--neon-gold); text-align:center; margin-top:6px; background:rgba(255,188,5,0.08); padding:4px 8px; border-radius:8px">
          🔍 Solicitud enviada (${quote.date || 'reciente'}). Consultando cupo de fábrica y buque.
        </div>`;
    } else if (quote.status === 'disponible') {
      buttonHtml = `
        <button onclick="window.openChinaAutoCheckoutModal('${car.id}')" class="btn" style="width:100%; padding:0.7rem 1rem; border-radius:12px; font-weight:800; font-size:0.9rem; border:none; cursor:pointer; background:linear-gradient(135deg, #00ff87, #60efff); color:#000; box-shadow:0 4px 18px rgba(0,255,135,0.4);">
          ⚡ COMPRAR AHORA — Afl. ${calc.totalAWG.toLocaleString('en-US', {maximumFractionDigits:0})} AWG
        </button>`;
      statusNotice = `
        <div style="font-size:0.72rem; color:var(--neon-cyan); text-align:center; margin-top:6px; font-weight:700; background:rgba(0,243,255,0.1); padding:4px 8px; border-radius:8px">
          ✅ ¡Fábrica confirmada! Unidad lista para reserva en custodia.
        </div>`;
    } else if (quote.status === 'comprado') {
      buttonHtml = `
        <button onclick="window.openChinaAutoTrackerModal('${car.id}')" class="btn" style="width:100%; padding:0.65rem 1rem; border-radius:12px; font-weight:800; font-size:0.85rem; border:none; cursor:pointer; background:linear-gradient(135deg, var(--neon-purple), var(--neon-cyan)); color:#000; box-shadow:0 4px 14px rgba(0,243,255,0.3);">
          🚢 Ver Seguimiento & Onboarding (#${quote.orderId || 'SABI-CN'})
        </button>`;
      statusNotice = `<span style="font-size:0.7rem; color:var(--neon-cyan); display:block; text-align:center; margin-top:4px;">📄 Documentación KYC & Rastro de Buque activo</span>`;
    }

    const specsList = car.specs.map(s => `<span style="font-size:0.7rem; background:rgba(255,255,255,0.06); padding:2px 8px; border-radius:10px; color:var(--text-muted); border:1px solid rgba(255,255,255,0.08)">${s}</span>`).join(' ');

    html += `
      <div class="card" style="background:rgba(20, 15, 45, 0.7); border:1px solid var(--glass-border); border-radius:16px; overflow:hidden; display:flex; flex-direction:column; justify-content:space-between; transition:transform 0.2s;" onmouseover="this.style.transform='translateY(-3px)'" onmouseout="this.style.transform=''">
        <div>
          <div style="position:relative; width:100%; height:170px; overflow:hidden">
            <img src="${car.image}" alt="${car.title}" style="width:100%; height:100%; object-fit:cover">
            <span style="position:absolute; top:10px; left:10px; background:rgba(0,0,0,0.75); color:var(--neon-cyan); font-weight:800; font-size:0.7rem; padding:3px 10px; border-radius:12px; backdrop-filter:blur(4px); border:1px solid var(--neon-cyan)">${car.tag}</span>
            <span style="position:absolute; top:10px; right:10px; background:rgba(0,0,0,0.75); color:var(--neon-gold); font-weight:800; font-size:0.7rem; padding:3px 10px; border-radius:12px; backdrop-filter:blur(4px); border:1px solid var(--neon-gold)">⚡ ${car.range}</span>
          </div>

          <div style="padding:1rem">
            <div style="font-size:0.68rem; color:#00ff87; background:rgba(0,255,135,0.08); padding:3px 8px; border-radius:6px; margin-bottom:8px; font-weight:800; display:inline-block; border:1px solid rgba(0,255,135,0.2)">
              ✓ Auditado &amp; Verificado por Sabí
            </div>
            <h4 style="margin:0 0 0.4rem 0; font-size:1rem; font-weight:800; color:white; line-height:1.3">${car.title}</h4>
            <p style="margin:0 0 0.75rem 0; font-size:0.78rem; color:var(--text-muted); line-height:1.4">${car.description}</p>
            <div style="display:flex; flex-wrap:wrap; gap:4px; margin-bottom:1rem">${specsList}</div>

            <div style="background:rgba(0,0,0,0.3); border:1px solid rgba(255,255,255,0.08); padding:0.75rem; border-radius:12px; margin-bottom:1rem">
              <div style="font-size:0.7rem; color:var(--text-muted); font-weight:700">PRECIO LANDED TOTAL EN ARUBA:</div>
              <div style="display:flex; justify-content:space-between; align-items:baseline; margin-top:2px">
                <span style="font-size:1.3rem; font-weight:900; color:var(--neon-cyan)">Afl. ${calc.totalAWG.toLocaleString('en-US', {maximumFractionDigits:0})} <small style="font-size:0.75rem">AWG</small></span>
                <span style="font-size:0.85rem; color:var(--text-muted); font-weight:700">~$${calc.totalUSD.toLocaleString('en-US', {maximumFractionDigits:0})} USD</span>
              </div>
              <div style="font-size:0.68rem; color:var(--neon-gold); margin-top:4px; display:flex; justify-content:space-between;">
                <span>FOB $${car.fobUSD.toLocaleString()} + Flete & Aduana EV 12%</span>
                <span style="cursor:pointer; text-decoration:underline" onclick="alert('Desglose Desembarcado (${car.title}):\\n\\n• Vehículo FOB: $${car.fobUSD} USD (Afl. ${calc.fobAWG.toFixed(2)})\\n• Inspección Privada CCIC: $${car.inspectionUSD} USD (Afl. ${calc.inspectionAWG.toFixed(2)})\\n• Flete Marítimo Barcadera: $${car.oceanUSD} USD (Afl. ${calc.oceanAWG.toFixed(2)})\\n• Impuesto Aduana EV (12%): Afl. ${calc.dutyAWG.toFixed(2)}\\n• BBO (7%): Afl. ${calc.bboAWG.toFixed(2)}\\n• Adaptador Electrolineras GB/T: Afl. ${calc.gbtAdapterAWG.toFixed(2)}\\n• Asesoría Sabí (4%): Afl. ${calc.sabiFeeAWG.toFixed(2)}\\n----------------------------------\\nTOTAL LANDED: Afl. ${calc.totalAWG.toFixed(2)} AWG')">Ver Desglose ℹ️</span>
              </div>
              <div style="background:rgba(0,255,135,0.06); border:1px dashed rgba(0,255,135,0.3); padding:4px 8px; border-radius:8px; margin-top:6px; font-size:0.68rem; color:#00ff87; text-align:center; font-weight:800">
                💡 Ahorro Estimado vs Concesionario Local: ~Afl. ${Math.round(calc.totalAWG * 0.45).toLocaleString('en-US')} AWG
              </div>
            </div>
          </div>
        </div>

        <div style="padding:0 1rem 1rem 1rem">
          ${buttonHtml}
          ${statusNotice}
        </div>
      </div>`;
  });

  container.innerHTML = html;
}

window.openChinaAutoQuoteModal = function(carId) {
  const car = SABI_CHINA_AUTO_MODELS.find(c => c.id === carId);
  if (!car) return;
  const calc = calculateChinaAutoLanded(car);

  document.getElementById('ca-quote-car-id').value = car.id;
  document.getElementById('ca-quote-img').src = car.image;
  document.getElementById('ca-quote-title').textContent = car.title;
  document.getElementById('ca-quote-price').textContent = `Landed Aruba: Afl. ${calc.totalAWG.toLocaleString('en-US', {maximumFractionDigits:0})} AWG (~$${calc.totalUSD.toLocaleString('en-US', {maximumFractionDigits:0})} USD)`;

  const modal = document.getElementById('china-auto-quote-modal');
  if (modal) modal.style.display = 'flex';
};

window.closeChinaAutoQuoteModal = function() {
  const modal = document.getElementById('china-auto-quote-modal');
  if (modal) modal.style.display = 'none';
};

window.submitChinaAutoQuote = function() {
  const carId = document.getElementById('ca-quote-car-id').value;
  const name = document.getElementById('ca-quote-name').value;
  const phone = document.getElementById('ca-quote-phone').value;
  const options = document.getElementById('ca-quote-options').value;

  if (!carId || !name || !phone) return;

  const quotes = getChinaAutoQuotes();
  const dateStr = new Date().toLocaleDateString('es-ES', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });

  quotes[carId] = {
    status: 'verificando',
    name, phone, options, date: dateStr, timestamp: Date.now()
  };

  saveChinaAutoQuotes(quotes);
  window.closeChinaAutoQuoteModal();

  try { SoundEffects.playJingle(); } catch(e) {}
  if (typeof showToast === 'function') {
    showToast("Solicitud Registrada", "Enviando ficha al fabricante. Verificando disponibilidad (2 a 48h).");
  }

  renderChinaAutoImport();
};

window.toggleDemoChinaAutoStatus = function(carId) {
  const quotes = getChinaAutoQuotes();
  if (!quotes[carId]) {
    quotes[carId] = { status: 'verificando', date: 'Demo' };
  } else if (quotes[carId].status === 'verificando') {
    quotes[carId].status = 'disponible';
  } else if (quotes[carId].status === 'disponible') {
    quotes[carId].status = 'initial';
  } else {
    quotes[carId].status = 'verificando';
  }
  saveChinaAutoQuotes(quotes);
  renderChinaAutoImport();
};

window.toggleAllChinaAutoDemoStatus = function() {
  const quotes = getChinaAutoQuotes();
  let hasVerificando = false;
  SABI_CHINA_AUTO_MODELS.forEach(car => {
    if (quotes[car.id] && quotes[car.id].status === 'verificando') {
      hasVerificando = true;
    }
  });

  SABI_CHINA_AUTO_MODELS.forEach(car => {
    if (!quotes[car.id]) {
      quotes[car.id] = { status: hasVerificando ? 'disponible' : 'verificando', date: 'Demo' };
    } else if (hasVerificando) {
      quotes[car.id].status = 'disponible';
    } else {
      quotes[car.id].status = 'verificando';
    }
  });

  saveChinaAutoQuotes(quotes);
  if (typeof showToast === 'function') {
    showToast("Demo Admin", hasVerificando ? "Modelos actualizados a 'DISPONIBLE' (Comprar Ahora)." : "Modelos actualizados a 'VERIFICANDO'.");
  }
  renderChinaAutoImport();
};

