window.openChinaAutoOpsModal = function() {
  let modal = document.getElementById('china-auto-ops-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'china-auto-ops-modal';
    modal.className = 'modal-overlay';
    modal.style.cssText = 'z-index:10000; display:none; position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.8); align-items:center; justify-content:center; backdrop-filter:blur(5px)';
    modal.innerHTML = `
      <div class="modal-card" style="max-width: 860px; width:90%; background:radial-gradient(circle at 10% 10%, #1c153b 0%, #0d0922 100%); border:1px solid var(--neon-gold); border-radius:16px; padding:1.5rem">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:1rem">
          <h3 style="margin:0; font-size:1.2rem; font-weight:800; color:white; display:flex; align-items:center; gap:0.5rem">
            📊 Panel de Control &amp; Operaciones en Curso — China Auto Import
            <span style="background:var(--neon-gold); color:#000; font-size:0.7rem; padding:2px 8px; border-radius:6px; font-weight:900">ADMIN OPS</span>
          </h3>
          <button onclick="window.closeChinaAutoOpsModal()" style="background:none; border:none; color:var(--text-muted); font-size:1.4rem; cursor:pointer">&times;</button>
        </div>
        <div id="china-auto-ops-body" style="display:flex; flex-direction:column; gap:1.25rem; max-height:75vh; overflow-y:auto; padding-right:5px">
        </div>
      </div>`;
    document.body.appendChild(modal);
  }

  const quotes = getChinaAutoQuotes();
  const body = document.getElementById('china-auto-ops-body');
  if (!body) return;

  const activeOrders = [];
  let totalEscrowAWG = 0;

  SABI_CHINA_AUTO_MODELS.forEach(car => {
    const q = quotes[car.id];
    if (q) {
      const calc = calculateChinaAutoLanded(car);
      if (q.status === 'comprado' || q.status === 'verificando') {
        totalEscrowAWG += calc.totalAWG;
      }
      activeOrders.push({ car, calc, quote: q });
    }
  });

  if (activeOrders.length === 0) {
    const demoCar1 = SABI_CHINA_AUTO_MODELS.find(c => c.id === 'xiaomi_yu7_standard_2025') || SABI_CHINA_AUTO_MODELS[0];
    const demoCalc1 = calculateChinaAutoLanded(demoCar1);
    activeOrders.push({
      car: demoCar1,
      calc: demoCalc1,
      quote: {
        status: 'comprado',
        orderId: 'SABI-CN-884912',
        name: 'Juan Croes',
        phone: '+297 594 1234',
        idNumber: 'AR-84912049',
        date: '14/08/2026',
        paymentMethod: 'bank_transfer',
        containerId: 'CN-SABI-99214'
      }
    });
    totalEscrowAWG += demoCalc1.totalAWG;
  }

  let tableRows = '';
  activeOrders.forEach(item => {
    const q = item.quote;
    const car = item.car;
    const calc = item.calc;
    const orderId = q.orderId || ('SABI-CN-' + Math.floor(100000 + Math.random() * 900000));
    const customerName = q.name || 'Juan Croes';
    const customerPhone = q.phone || '+297 594 1234';

    let statusBadge = '';
    if (q.status === 'verificando') {
      statusBadge = `<span style="background:rgba(255,188,5,0.2); color:var(--neon-gold); padding:4px 8px; border-radius:6px; font-size:0.75rem; font-weight:800">⏳ Verificando Fábrica</span>`;
    } else if (q.status === 'disponible') {
      statusBadge = `<span style="background:rgba(0,255,135,0.2); color:#00ff87; padding:4px 8px; border-radius:6px; font-size:0.75rem; font-weight:800">⚡ Fábrica Confirmada</span>`;
    } else {
      statusBadge = `<span style="background:rgba(0,243,255,0.2); color:var(--neon-cyan); padding:4px 8px; border-radius:6px; font-size:0.75rem; font-weight:800">🚢 Escrow Activo / En Tránsito</span>`;
    }

    tableRows += `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.06); font-size:0.8rem; text-align:left">
        <td style="padding:10px; font-weight:900; color:var(--neon-cyan)">#${orderId}</td>
        <td style="padding:10px">
          <div style="font-weight:800; color:white">${customerName}</div>
          <div style="font-size:0.72rem; color:var(--neon-gold)">ID Cédula: AR-84912049</div>
          <div style="font-size:0.7rem; color:var(--text-muted)">Tel: ${customerPhone}</div>
        </td>
        <td style="padding:10px">
          <div style="font-weight:800; color:white">${car.title}</div>
          <div style="font-size:0.7rem; color:var(--text-muted)">FOB $${car.fobUSD.toLocaleString()} USD</div>
        </td>
        <td style="padding:10px; font-weight:900; color:#00ff87">Afl. ${calc.totalAWG.toLocaleString('en-US', {maximumFractionDigits:0})}</td>
        <td style="padding:10px">${statusBadge}</td>
        <td style="padding:10px">
          <div style="display:flex; gap:4px; flex-wrap:wrap">
            <button onclick="alert('📄 Bill of Lading (B/L) Legal:\\n\\n• Consignatario (Titular): ${customerName}\\n• ID Cédula: AR-84912049\\n• Puerto Destino: Barcadera Port, Aruba\\n• Vehículo VIN: 1BYD-EV-2025-884129\\n• Arancel Douane: 12% EV + 7% BBO')" style="padding:3px 8px; border-radius:6px; border:1px solid var(--neon-cyan); background:rgba(0,243,255,0.1); color:var(--neon-cyan); font-size:0.7rem; font-weight:700; cursor:pointer">📄 Ver B/L Titular</button>
            <button onclick="window.openChinaAutoTrackerModal('${car.id}')" style="padding:3px 8px; border-radius:6px; border:1px solid var(--neon-gold); background:rgba(255,188,5,0.1); color:var(--neon-gold); font-size:0.7rem; font-weight:700; cursor:pointer">🚢 Tracker Portal</button>
          </div>
        </td>
      </tr>`;
  });

  body.innerHTML = `
    <!-- SUMMARY KPI CARDS -->
    <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(170px, 1fr)); gap:0.75rem">
      <div style="background:rgba(0,243,255,0.08); border:1px solid var(--neon-cyan); padding:0.85rem; border-radius:12px; text-align:center">
        <div style="font-size:0.7rem; color:var(--text-muted); font-weight:700">ORDENES ACTIVAS</div>
        <div style="font-size:1.5rem; font-weight:900; color:var(--neon-cyan); margin-top:2px">${activeOrders.length}</div>
      </div>
      <div style="background:rgba(0,255,135,0.08); border:1px solid #00ff87; padding:0.85rem; border-radius:12px; text-align:center">
        <div style="font-size:0.7rem; color:var(--text-muted); font-weight:700">FONDOS EN CUSTODIA (ESCROW)</div>
        <div style="font-size:1.3rem; font-weight:900; color:#00ff87; margin-top:2px">Afl. ${totalEscrowAWG.toLocaleString('en-US', {maximumFractionDigits:0})} AWG</div>
      </div>
      <div style="background:rgba(255,188,5,0.08); border:1px solid var(--neon-gold); padding:0.85rem; border-radius:12px; text-align:center">
        <div style="font-size:0.7rem; color:var(--text-muted); font-weight:700">DESTINO FINAL</div>
        <div style="font-size:1.1rem; font-weight:900; color:var(--neon-gold); margin-top:2px">🇦🇼 Barcadera Port</div>
      </div>
    </div>

    <!-- TABLA DE OPERACIONES -->
    <div style="background:rgba(0,0,0,0.4); border:1px solid var(--glass-border); padding:1rem; border-radius:12px">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:0.75rem">
        <h4 style="margin:0; font-size:0.95rem; color:white; font-weight:800">📋 Tabla de Operaciones de Importación en Curso (Titulares Registrados)</h4>
        <button onclick="window.toggleAllChinaAutoDemoStatus()" class="btn" style="padding:4px 12px; border-radius:8px; border:none; background:linear-gradient(135deg, var(--neon-purple), var(--neon-pink)); color:white; font-size:0.75rem; font-weight:800; cursor:pointer">🔄 Simular Disponibilidad Confirmada</button>
      </div>

      <div style="overflow-x:auto">
        <table style="width:100%; border-collapse:collapse">
          <thead>
            <tr style="border-bottom:1px solid var(--glass-border); font-size:0.72rem; color:var(--text-muted); text-align:left">
              <th style="padding:8px">ID PEDIDO</th>
              <th style="padding:8px">COMPRADOR (TITULAR)</th>
              <th style="padding:8px">VEHÍCULO</th>
              <th style="padding:8px">LANDED AWG</th>
              <th style="padding:8px">ESTADO OPERACIÓN</th>
              <th style="padding:8px">ACCIONES GESTIÓN</th>
            </tr>
          </thead>
          <tbody>
            ${tableRows}
          </tbody>
        </table>
      </div>
    </div>

    <div style="display:flex; justify-content:flex-end">
      <button onclick="window.closeChinaAutoOpsModal()" class="btn" style="background:rgba(255,255,255,0.1); color:white; border:none; padding:8px 20px; border-radius:20px; cursor:pointer; font-size:0.8rem">Cerrar Panel</button>
    </div>
  `;

  modal = document.getElementById('china-auto-ops-modal');
  if (modal) modal.style.display = 'flex';
};

