function processWisePayouts() {
  let totalCOPPaid = 0;
  let paidSuppliersCount = 0;

  for (const supId in appState.supplierBalances) {
    if (appState.supplierBalances[supId] > 0) {
      totalCOPPaid += appState.supplierBalances[supId];
      appState.supplierBalances[supId] = 0;
      paidSuppliersCount++;
    }
  }

  if (totalCOPPaid === 0) {
    SoundEffects.playAlert();
    showToast("Sin Fondos", "No hay balances pendientes por pagar a ningún fabricante de Colombia.");
    return;
  }

  localStorage.setItem('sabi_supplier_balances', JSON.stringify(appState.supplierBalances));
  
  SoundEffects.playJingle();
  showToast("Wise Batch Payout", `Corte semanal realizado con éxito. Dispersados $${totalCOPPaid.toLocaleString()} COP mediante transferencia ACH a ${paidSuppliersCount} proveedores.`);

  renderAdminDashboard();
}
window.processWisePayouts = processWisePayouts;

