// --- Switch between sub-tabs (calc / tracker / budget / advisor) -------
function switchAutoSubTab(subTab) {
  try { SoundEffects.playClick(); } catch(e) {}

  const panelCalc    = document.getElementById('auto-subtab-calc');
  const panelTracker = document.getElementById('auto-subtab-tracker');
  const panelBudget  = document.getElementById('auto-subtab-budget');
  const panelAdvisor = document.getElementById('auto-subtab-advisor');
  const panelMarket  = document.getElementById('auto-subtab-market');
  const panelBroker  = document.getElementById('auto-subtab-broker');
  const btnCalc    = document.getElementById('auto-subtab-btn-calc');
  const btnTracker = document.getElementById('auto-subtab-btn-tracker');
  const btnBudget  = document.getElementById('auto-subtab-btn-budget');
  const btnAdvisor = document.getElementById('auto-subtab-btn-advisor');
  const btnMarket  = document.getElementById('auto-subtab-btn-market');
  const btnBroker  = document.getElementById('auto-subtab-btn-broker');

  // Reset all
  const allPanels = [panelCalc, panelTracker, panelBudget, panelAdvisor, panelMarket, panelBroker];
  const allBtns = [btnCalc, btnTracker, btnBudget, btnAdvisor, btnMarket, btnBroker];
  allPanels.forEach(p => { if (p) p.style.display = 'none'; });
  const resetBtn = (b) => { if (b) { b.style.background = 'transparent'; b.style.color = 'var(--text-muted)'; } };
  allBtns.forEach(resetBtn);

  // === PARTE 4: Paywall para Advisor y Broker ===
  // Si el usuario intenta entrar al Asesor Sabí o Guía Broker sin haber pagado
  // el 4% upfront, interceptamos el cambio y mostramos un layout bloqueado.
  if (subTab === 'advisor' || subTab === 'broker') {
    if (!appState.autoImportFeePaid) {
      renderAutoImportPaywall(subTab, btnAdvisor, btnBroker, panelAdvisor, panelBroker);
      return; // Detenemos la navegación normal
    }
  }

  if (subTab === 'tracker') {
    if (panelTracker) panelTracker.style.display = 'block';
    if (btnTracker) { btnTracker.style.background = 'var(--neon-cyan)'; btnTracker.style.color = '#000'; }
    renderVehicleListMockup();
  } else if (subTab === 'budget') {
    if (panelBudget) panelBudget.style.display = 'block';
    if (btnBudget) { btnBudget.style.background = 'var(--neon-gold, gold)'; btnBudget.style.color = '#000'; }
  } else if (subTab === 'advisor') {
    if (panelAdvisor) panelAdvisor.style.display = 'block';
    if (btnAdvisor) { btnAdvisor.style.background = 'var(--neon-cyan)'; btnAdvisor.style.color = '#000'; }
  } else if (subTab === 'market') {
    if (panelMarket) panelMarket.style.display = 'block';
    if (btnMarket) { btnMarket.style.background = 'var(--neon-gold, gold)'; btnMarket.style.color = '#000'; }
    renderMarketComparison('all');
  } else if (subTab === 'broker') {
    if (panelBroker) panelBroker.style.display = 'block';
    if (btnBroker) { btnBroker.style.background = 'var(--neon-emerald)'; btnBroker.style.color = '#000'; }
  } else {
    // Default: calc
    if (panelCalc) panelCalc.style.display = 'block';
    if (btnCalc) { btnCalc.style.background = 'var(--neon-cyan)'; btnCalc.style.color = '#000'; }
  }
}

