let vehicleImportSteps = {}; // { 'vehicle-id': currentStep }

function renderProgressBar(vehicleId) {
  const bar = document.getElementById('sabi-progress-bar');
  const current = vehicleImportSteps[vehicleId] || 1;
  currentImportStep = current;
  
  bar.innerHTML = SABI_IMPORT_STEPS.map(step => {
    let cls = 'sabi-progress-step';
    if (step.id === current) cls += ' active';
    else if (step.id < current) cls += ' completed';
    else cls += ' pending';
    return `<div class="${cls}" onclick="window.selectImportStep('${vehicleId}', ${step.id})">${step.id}</div>`;
  }).join('');
}

function selectImportStep(vehicleId, stepId) {
  vehicleImportSteps[vehicleId] = stepId;
  currentImportStep = stepId;
  renderProgressBar(vehicleId);
  renderStepDetail(vehicleId, stepId);
  updateTrackerHeader(vehicleId);
}

function renderStepDetail(vehicleId, stepId) {
  const detail = document.getElementById('sabi-step-detail');
  const step = SABI_IMPORT_STEPS.find(s => s.id === stepId);
  if (!step) return;
  
  // Get all statuses from vehicle
  const statuses = vehicleImportSteps[vehicleId] ? vehicleImportSteps[vehicleId] : 1;
  const stepStatus = stepId < statuses ? 'completed' : (stepId === statuses ? 'in-progress' : 'pending');
  const statusLabel = stepStatus === 'completed' ? '✅ Completado' : (stepStatus === 'in-progress' ? '🔄 En proceso' : '⏳ Pendiente');
  
  detail.innerHTML = `
    <div class="sabi-step-detail">
      <div class="sabi-step-detail-header">
        <div class="sabi-step-detail-number">${step.id}</div>
        <div class="sabi-step-detail-title">${step.title}</div>
      </div>
      <div class="sabi-step-detail-desc">${step.desc}</div>
      <div class="sabi-step-detail-status ${stepStatus}">${statusLabel}</div>
    </div>
  `;
}

function updateTrackerHeader(vehicleId) {
  const currentEl = document.getElementById('tracker-current-step');
  const step = SABI_IMPORT_STEPS.find(s => s.id === currentImportStep);
  if (currentEl && step) {
    currentEl.innerText = step.title;
  }
}

function initProgressBarForVehicle(vehicleId, startStep) {
  vehicleImportSteps[vehicleId] = startStep;
  renderProgressBar(vehicleId);
  renderStepDetail(vehicleId, startStep);
  updateTrackerHeader(vehicleId);
}

// --- Render vehicle list (3 mockups) ------------------------------------
function renderVehicleListMockup() {
  const target = document.getElementById('vehicle-list-mockup');
  if (!target) return;

  const statusColors = { 1: '#888', 2: '#00aaff', 3: '#00aaff', 4: '#00ff88', 5: '#00ff88', 6: '#ffaa00', 7: '#ffaa00', 8: '#00ff88', 9: '#00ff88' };
  const fuelIcon = { hybrid: '🌿', ev: '⚡', gas: '⛽' };
  const fuelLabel = { hybrid: 'Híbrido', ev: 'Eléctrico', gas: 'Gasolina' };

  target.innerHTML = SABI_VEHICLES_MOCKUP.map(v => {
    const color = statusColors[v.currentStep] || '#888';
    return `
      <div class="sabi-auto-vehicle-card" onclick="loadVehicleTracker('${v.id}')">
        <div class="vc-header">
          <div class="vc-name">${fuelIcon[v.fuelType]} ${v.name}</div>
          <span class="sabi-auto-step-badge" style="background:${color}">Paso ${v.currentStep}/9</span>
        </div>
        <div class="vc-vin">${v.vin}</div>
        <div class="vc-meta">
          <span>Bid: <strong>$${v.bid.toLocaleString()}</strong></span>
          <span>${fuelLabel[v.fuelType]}</span>
        </div>
        <div class="vc-status" style="color:${color}">${v.stepLabel}</div>
      </div>
    `;
  }).join('');
}

// --- Load tracker for selected vehicle ----------------------------------
function loadVehicleTracker(vehicleId) {
  const v = SABI_VEHICLES_MOCKUP.find(x => x.id === vehicleId);
  if (!v) return;

  // Update header
  document.getElementById('tracker-vehicle-name').innerText = v.name;
  document.getElementById('tracker-vin').innerText = v.vin;
  document.getElementById('tracker-bid').innerText = `$${v.bid.toLocaleString()} USD`;
  document.getElementById('tracker-eta').innerText = v.eta;
  
  // Init progress bar with 13 steps (new workflow)
  initProgressBarForVehicle(vehicleId, v.currentStep);
  
  // Show timeline section (legacy, ahora es la barra de progreso)
  const tlSection = document.getElementById('tracker-timeline-section');
  const tlTarget = document.getElementById('tracker-timeline');
  if (tlSection) tlSection.style.display = 'block';

  if (tlTarget) {
    tlTarget.innerHTML = SABI_AUTO_STEPS.map(step => {
      const isCompleted = step.num < v.currentStep;
      const isActive = step.num === v.currentStep;
      const isPending = step.num > v.currentStep;

      let stateStyle, iconStyle, statusBadge;
      if (isCompleted) {
        stateStyle = 'opacity:0.7';
        iconStyle = 'background:#00cc66; color:#000; box-shadow:0 0 12px rgba(0,255,100,0.3)';
        statusBadge = '<span style="background:#00cc66; color:#000; font-size:0.7rem; padding:2px 8px; border-radius:10px; font-weight:700">✅ COMPLETADO</span>';
      } else if (isActive) {
        stateStyle = 'background:rgba(0,255,200,0.08); border-left:4px solid var(--neon-cyan); padding:14px; margin-left:-14px';
        iconStyle = 'background:var(--neon-cyan); color:#000; box-shadow:0 0 16px rgba(0,255,200,0.6); animation:pulse 1.5s infinite';
        statusBadge = '<span style="background:var(--neon-cyan); color:#000; font-size:0.7rem; padding:2px 8px; border-radius:10px; font-weight:700">▶ EN CURSO</span>';
      } else {
        stateStyle = 'opacity:0.45';
        iconStyle = 'background:#333; color:#888';
        statusBadge = '<span style="background:#333; color:#888; font-size:0.7rem; padding:2px 8px; border-radius:10px; font-weight:700">⏳ PENDIENTE</span>';
      }

      // Step-specific extra data
      let extraHtml = '';
      if (step.num === 2) {
        extraHtml = `<div style="margin-top:8px; font-size:0.8rem; color:var(--text-muted)">
          ${v.carfaxOk === true ? '✅' : v.carfaxOk === false ? '❌' : '⏳'} CARFAX verificado · Título: <strong>${v.titleType}</strong>
        </div>`;
      } else if (step.num === 3) {
        extraHtml = `<div style="margin-top:8px; font-size:0.8rem; color:var(--text-muted)">
          ${v.partsNeeded.length === 0 ? '✅ Sin repuestos necesarios' : `🔧 Piezas: ${v.partsNeeded.join(', ')} (~$ ${v.partsCost})`}
        </div>`;
      } else if (step.num === 4) {
        if (v.inspectionDate) {
          extraHtml = `<div style="margin-top:8px; font-size:0.8rem; color:var(--text-muted)">
            ${v.batteryHealth !== '—' ? `🔋 Batería: ${v.batteryHealth}` : ''}
            ${v.airbagsOk === true ? '· ✅ Airbags OK' : v.airbagsOk === false ? '· ❌ Airbags estallados' : ''}
            ${v.chassisOk === true ? '· ✅ Chasis OK' : v.chassisOk === false ? '· ❌ Chasis dañado' : ''}
          </div>`;
        }
      } else if (step.num === 5) {
        if (v.bidLimit) {
          extraHtml = `<div style="margin-top:8px; font-size:0.8rem; color:var(--text-muted)">
            Límite de puja: <strong>$${v.bidLimit.toLocaleString()}</strong> · Ganado a: <strong style="color:var(--neon-cyan)">$${v.bid.toLocaleString()}</strong>
          </div>`;
        }
      } else if (step.num === 6) {
        if (v.shipDate) {
          extraHtml = `<div style="margin-top:8px; font-size:0.8rem; color:var(--text-muted)">
            📅 Embarcado: ${v.shipDate} · Patio origen: <strong>${v.yard}</strong>
          </div>`;
        }
      }

      return `
        <div class="sabi-auto-step-row ${isCompleted ? 'completed' : (isActive ? 'active' : 'pending')}">
          <div class="sabi-auto-step-icon ${isCompleted ? 'completed' : (isActive ? 'active' : 'pending')}">
            ${isCompleted ? '✓' : step.icon}
          </div>
          <div class="sabi-auto-step-content">
            <div class="sabi-auto-step-title">
              <strong>${step.num}. ${step.title}</strong>
              ${statusBadge}
            </div>
            <div class="sabi-auto-step-desc">${step.desc}</div>
            ${extraHtml}
          </div>
        </div>
      `;
    }).join('');
  }

  // Smooth scroll to timeline
  if (tlSection) {
    setTimeout(() => tlSection.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
  }

  try { SoundEffects.playClick(); } catch(e) {}
}

// --- Wizard Presupuesto — Embudo de conversión blindado -----------------
// Modelo: Cobra 4% upfront sobre el Presupuesto Seguro del cliente.
// Reconstruye cuánto le queda al cliente para pujar en subasta
// después de los costos logísticos/aduaneros, y deja explícita la
// cláusula de protección del 20% sobrebudget.
function calculateBudgetWizard() {
  try { SoundEffects.playClick(); } catch(e) {}

  const lang = appState.language || 'es';
  const dict = SABI_TRANSLATIONS[lang] || {};

  const budgetAWG = parseFloat(document.getElementById('wiz-budget-awg').value);
  const fuelType  = document.getElementById('wiz-fuel-type').value;
  const strategy  = document.getElementById('wiz-strategy').value;

  if (!budgetAWG || budgetAWG <= 0) {
    showToast(
      dict['toast_invalid_amount_title'] || 'Monto inválido', 
      dict['toast_invalid_amount_desc'] || 'Ingresa un Presupuesto Seguro válido.',
      'error'
    );
    return;
  }

  const RATE_USD_AWG = 1.80;
  const SABI_FEE_PCT = 0.04;             // 4% upfront
  const OVERBUDGET_PCT = 0.20;          // cláusula 20%

  const feeAWG = budgetAWG * SABI_FEE_PCT;
  const feeUSD = feeAWG / RATE_USD_AWG;

  const inlandFreightUSD = 350;          // Yard → puerto (inland)
  const oceanFreightUSD = 1800;         // Miami → Barcadera (sea)
  const inspectionUSD    = 200;          // Revisión pre-bid por experto
  const totalLogisticsUSD = inlandFreightUSD + oceanFreightUSD + inspectionUSD;
  const totalLogisticsAWG = totalLogisticsUSD * RATE_USD_AWG;

  const dutyMap = { ev: 0.12, hybrid: 0.19, gas: 0.39 };
  const dutyRate = dutyMap[fuelType] || 0.19;
  const dutyLabel = dict['auto_budget_opt_' + fuelType] || { ev: 'Eléctrico (12%)', hybrid: 'Híbrido (19%)', gas: 'Gasolina (39%)' }[fuelType];

  const marginMap = { conservative: 0.25, balanced: 0.15, aggressive: 0.05 };
  const safetyMargin = marginMap[strategy] || 0.15;
  const stratLabel = dict['auto_budget_opt_' + strategy] || { conservative: '🛡️ Conservador (25%)', balanced: '⚖️ Balanceado (15%)', aggressive: '🎯 Agresivo (5%)' }[strategy];

  const budgetUSD = budgetAWG / RATE_USD_AWG;

  const marginUSD = budgetUSD * safetyMargin;
  const availableForBidUSD = budgetUSD - feeUSD - totalLogisticsUSD - marginUSD;
  const dutyMultiplier = 1 + dutyRate;
  const maxBidUSD = availableForBidUSD / dutyMultiplier;
  const maxBidAWG = maxBidUSD * RATE_USD_AWG;

  const customsAWG = (maxBidUSD * dutyRate) * RATE_USD_AWG;

  if (maxBidUSD <= 0) {
    showToast(
      dict['toast_insufficient_budget_title'] || 'Presupuesto insuficiente', 
      dict['toast_insufficient_budget_desc'] || 'Tu Presupuesto Seguro no alcanza para cubrir logística + 4% + margen. Auméntalo.',
      'error'
    );
  }

  const overbudgetThresholdAWG = budgetAWG * (1 + OVERBUDGET_PCT);
  const clauseProtection = {
    enabled: true,
    thresholdPct: OVERBUDGET_PCT * 100,           // 20
    thresholdAWG: overbudgetThresholdAWG,          // monto máximo permitido sin recargo
    description: (dict['auto_calc_protection_clause_desc'] || `Si los gastos reales cierran por encima de Fl. {threshold} AWG, Sabí recalcula la asesoría al 4% sobre el costo real y factura el ajuste antes de las placas.`)
      .replace('{pct}', (OVERBUDGET_PCT * 100).toFixed(0))
      .replace('{threshold}', overbudgetThresholdAWG.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})),
  };

  appState.autoImportBudget = {
    budgetAWG,
    feeAWG,
    feeUSD,
    maxBidUSD,
    maxBidAWG,
    fuelType,
    dutyRate,
    customsAWG,
    totalLogisticsAWG,
    safetyMargin,
    clauseProtection,
    strategy,
    createdAt: new Date().toISOString(),
  };

  const target = document.getElementById('wizard-results-section');
  if (!target) return;
  target.style.display = 'block';

  const fmtAWG = (n) => 'Afl. ' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtUSD = (n) => '$' + n.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 }) + ' USD';

  const titleText = dict['auto_calc_result_title'] || "🎯 Planificación de Presupuesto Seguro";
  const strategyLbl = dict['auto_calc_strategy_lbl'] || "Estrategia";
  const engineLbl = dict['auto_calc_engine_lbl'] || "Motor";
  const budgetDeclaredLbl = dict['auto_calc_budget_declared'] || "Presupuesto Seguro Declarado";
  const maxBidLbl = dict['auto_calc_max_bid'] || "Puja Máxima Sugerida en Subasta";
  const customsEstLbl = dict['auto_calc_customs_est'] || "Costo Est. Aduana Douane Aruba";
  const logisticsLbl = dict['auto_calc_logistics'] || "Logística y Fletes Consolidados";
  const sabiFeeLbl = dict['auto_calc_sabi_fee_lbl'] || "Comisión de Asesoría Sabí (4% Upfront)";
  const sabiFeeRefundableLbl = dict['auto_calc_sabi_fee_refundable'] || "Reembolsable 100% si no ganás la subasta";
  const protectionTitle = dict['auto_calc_protection_clause_title'] || "Términos de Margen de Variación (Cláusula de Protección)";
  const btnReserveLbl = (dict['auto_calc_btn_reserve'] || "Validar Presupuesto y Reservar Asesoría (Pagar {fee})").replace('{fee}', fmtAWG(feeAWG));

  target.innerHTML = `
    <div class="sabi-auto-highlight-box success" style="margin-top:1rem">
      <div class="hl-label">${titleText}</div>
      <p style="margin:0.65rem 0 0.85rem 0; color:var(--text-muted); font-size:0.85rem">
        ${strategyLbl}: <strong>${stratLabel}</strong> · ${engineLbl}: <strong>${dutyLabel}</strong>
      </p>

      <div class="sabi-row" style="display:flex; justify-content:space-between; align-items:center; padding:0.55rem 0; border-bottom:1px solid var(--glass-border, rgba(255,255,255,0.08)); font-size:0.92rem">
        <span>${budgetDeclaredLbl}</span>
        <strong style="color:var(--text-main)">${fmtAWG(budgetAWG)}</strong>
      </div>
      <div class="sabi-row" style="display:flex; justify-content:space-between; align-items:center; padding:0.55rem 0; border-bottom:1px solid var(--glass-border, rgba(255,255,255,0.08)); font-size:0.92rem">
        <span>${maxBidLbl}</span>
        <strong style="color:var(--neon-gold, gold)">${fmtUSD(maxBidUSD)} <span style="font-size:0.78rem; color:var(--text-muted)">= ${fmtAWG(maxBidAWG)}</span></strong>
      </div>
      <div class="sabi-row" style="display:flex; justify-content:space-between; align-items:center; padding:0.55rem 0; border-bottom:1px solid var(--glass-border, rgba(255,255,255,0.08)); font-size:0.92rem">
        <span>${customsEstLbl} (${(dutyRate * 100).toFixed(0)}%)</span>
        <strong>${fmtAWG(customsAWG)}</strong>
      </div>
      <div class="sabi-row" style="display:flex; justify-content:space-between; align-items:center; padding:0.55rem 0; font-size:0.92rem">
        <span>${logisticsLbl}</span>
        <strong>${fmtAWG(totalLogisticsAWG)} <span style="font-size:0.78rem; color:var(--text-muted)">(inland ${fmtUSD(inlandFreightUSD)} + ocean ${fmtUSD(oceanFreightUSD)} + inspección ${fmtUSD(inspectionUSD)})</span></strong>
      </div>

      <!-- Caja del fee obligatorio (4% upfront) -->
      <div style="margin-top:1.25rem; padding:0.95rem 1.1rem; background:rgba(0,245,212,0.10); border:1px solid var(--neon-cyan); border-radius:10px">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:0.5rem">
          <div>
            <div style="font-size:0.78rem; color:var(--neon-cyan); text-transform:uppercase; letter-spacing:1px; font-weight:700">${sabiFeeLbl}</div>
            <div style="font-size:0.78rem; color:var(--text-muted); margin-top:4px">${sabiFeeRefundableLbl}</div>
          </div>
          <strong style="font-size:1.45rem; color:var(--neon-cyan); font-weight:800">${fmtAWG(feeAWG)}</strong>
        </div>
      </div>

      <!-- Cláusula de protección -->
      <div style="margin-top:1rem; padding:0.85rem 1rem; background:rgba(255,188,5,0.08); border-left:3px solid var(--neon-gold, gold); border-radius:8px; font-size:0.82rem; line-height:1.5">
        ⚠️ <strong>${protectionTitle}:</strong>
        ${clauseProtection.description}
      </div>

      <!-- Botón de pago -->
      <button type="button" onclick="window.pagarAsesoriaAutoImport()" class="sabi-auto-submit" style="width:100%; margin-top:1.25rem; background:var(--neon-cyan); border-color:var(--neon-cyan); color:#000; font-weight:800; font-size:1.05rem; padding:0.9rem 1.5rem">
        ${btnReserveLbl}
      </button>
    </div>
  `;

  target.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// === Paywall: renderiza layout bloqueado para Advisor / Broker sin pago 4% ===
function renderAutoImportPaywall(subTab, btnAdvisor, btnBroker, panelAdvisor, panelBroker) {
  const lang = appState.language || 'es';
  const dict = SABI_TRANSLATIONS[lang] || {};

  // Mantener visualmente el botón "activo" en el que el usuario hizo click
  const activeBtn = subTab === 'advisor' ? btnAdvisor : btnBroker;
  if (activeBtn) {
    activeBtn.style.background = 'var(--neon-cyan)';
    activeBtn.style.color = '#000';
  }

  // Construimos la lista de paneles a "bloquear": el actual + el otro
  const panelsToShow = [panelAdvisor, panelBroker].filter(Boolean);

  // Si hay presupuesto previo en appState, lo mostramos en la caja de contexto
  const b = appState.autoImportBudget;
  const feeFromBudget = b ? b.feeAWG : null;
  const feeDisplay = feeFromBudget != null
    ? `Afl. ${feeFromBudget.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
    : (dict['auto_pw_btn_calc'] || 'Ir a 🎯 Presupuesto para calcular').replace('Ir a ', '').replace(' para calcular', '');

  // Seleccionamos el panel del subtab clickeado para inyectar el bloqueo
  const targetPanel = subTab === 'advisor' ? panelAdvisor : panelBroker;
  if (!targetPanel) return;

  // Limpiamos el otro panel y mostramos el paywall en el actual
  const otherPanel = subTab === 'advisor' ? panelBroker : panelAdvisor;
  if (otherPanel) otherPanel.innerHTML = '';

  // Aseguramos que el panel clickeado esté visible
  targetPanel.style.display = 'block';

  const exclusiveTitle = dict['auto_pw_exclusive_title'] || "Acceso Exclusivo — Asesoría Pagada";
  const tabName = subTab === 'advisor' ? (dict['auto_tab_advisor'] || '🤖 Asesor Sabí') : (dict['auto_tab_broker'] || '📚 Guía Broker');
  const protectedText = (dict['auto_pw_protected'] || "{tab} está protegido").replace('{tab}', tabName);
  const descText = subTab === 'advisor'
    ? (dict['auto_pw_desc_advisor'] || 'El reporte completo de VIN, predicción de puja y recomendaciones de Copart/IAAI es exclusivo de clientes con asesoría pagada. Invertí en tu decisión, no a ciegas.')
    : (dict['auto_pw_desc_broker'] || 'La Guía Broker (crear cuenta AutoBidMaster, configurar poderes, planta de revisión) es exclusiva de clientes con asesoría pagada. No vayas a la subasta con información incompleta.');

  const whyTitle = dict['auto_pw_why_title'] || "💡 ¿Por qué se paga el 4% upfront?";
  const why1 = dict['auto_pw_why_1'] || "Protege tu inversión: te asegura que la asesoría está calibrada a tu presupuesto";
  const why2 = dict['auto_pw_why_2'] || "Reservamos el cupo en nuestro equipo para guiarte paso a paso";
  const why3 = dict['auto_pw_why_3'] || "<strong>100% reembolsable</strong> si no ganás la subasta";
  
  const sabiFeeLbl = dict['auto_calc_sabi_fee_lbl'] || "Comisión de Asesoría Sabí (4% Upfront)";
  const sabiFeeRefundableLbl = dict['auto_calc_sabi_fee_refundable'] || "Reembolsable 100% si no ganás la subasta";
  
  const btnText = b 
    ? (dict['auto_pw_btn_pay'] || 'Activar Asesoría y Pagar 4%') 
    : (dict['auto_pw_btn_calc'] || 'Ir a 🎯 Presupuesto para calcular');

  const clauseWarnText = dict['auto_pw_clause_warn'] || "⚠️ Cláusula de Protección: si los gastos reales cierran por encima de tu presupuesto seguro en más del 20%, recalculamos la asesoría al 4% sobre el costo real y facturamos el ajuste antes de las placas.";

  targetPanel.innerHTML = `
    <div class="sabi-auto-highlight-box success" style="text-align:center; padding:2.5rem 1.5rem; margin-top:1.5rem">
      <div style="font-size:3.5rem; margin-bottom:0.75rem">🔒</div>
      <div class="hl-label" style="font-size:1.05rem; margin-bottom:0.85rem">${exclusiveTitle}</div>

      <h3 style="font-size:1.4rem; color:var(--text-main); font-weight:800; margin:0.5rem 0 0.85rem 0">
        ${protectedText}
      </h3>

      <p style="color:var(--text-muted); font-size:0.95rem; max-width:540px; margin:0 auto 1.25rem auto; line-height:1.55">
        ${descText}
      </p>

      <section class="sabi-auto-highlight-box gold" style="margin:0 auto 1.25rem auto; max-width:520px; text-align:left">
        <div class="hl-label">${whyTitle}</div>
        <ul class="sabi-auto-list" style="margin:0.5rem 0 0 0; padding-left:1.2rem">
          <li>${why1}</li>
          <li>${why2}</li>
          <li>${why3}</li>
        </ul>
      </section>

      <div style="background:rgba(0,245,212,0.10); border:1px solid var(--neon-cyan); border-radius:10px; padding:0.95rem 1.1rem; max-width:520px; margin:0 auto 1.5rem auto">
        <div style="font-size:0.78rem; color:var(--neon-cyan); text-transform:uppercase; letter-spacing:1px; font-weight:700">${sabiFeeLbl}</div>
        <div style="font-size:1.6rem; font-weight:800; color:var(--neon-cyan); margin-top:6px">${feeDisplay}</div>
        <div style="font-size:0.78rem; color:var(--text-muted); margin-top:4px">${sabiFeeRefundableLbl}</div>
      </div>

      <button type="button" onclick="window.switchAutoSubTab('budget')" class="sabi-auto-submit" style="background:var(--neon-cyan); border-color:var(--neon-cyan); color:#000; font-weight:800; font-size:1.05rem; padding:0.9rem 1.5rem; max-width:320px; margin:0 auto">
        💳 ${btnText}
      </button>

      <p style="font-size:0.78rem; color:var(--text-muted); margin-top:1.5rem; max-width:540px; margin-left:auto; margin-right:auto">
        ${clauseWarnText}
      </p>
    </div>
  `;

  // Ocultar el otro panel
  if (otherPanel) otherPanel.style.display = 'none';

  showToast(
    dict['toast_locked_access_title'] || '🔒 Acceso bloqueado',
    subTab === 'advisor'
      ? (dict['toast_locked_access_desc_advisor'] || 'El Asesor Sabí requiere el pago del 4% upfront para evitar abuso del simulador.')
      : (dict['toast_locked_access_desc_broker'] || 'La Guía Broker requiere el pago del 4% upfront.'),
    'info'
  );
}

// Cobro del 4% upfront. Marca appState.autoImportFeePaid = true
// y permite el acceso al Asesor Sabí y Guía Broker.
function pagarAsesoriaAutoImport() {
  const lang = appState.language || 'es';
  const dict = SABI_TRANSLATIONS[lang] || {};

  const b = appState.autoImportBudget;
  if (!b) {
    showToast(
      dict['toast_no_budget_title'] || 'Sin presupuesto', 
      dict['toast_no_budget_desc'] || 'Primero calcula tu Presupuesto Seguro.', 
      'error'
    );
    return;
  }
  // Aquí podrías llamar a Stripe Checkout (la EF stripe-payments ya existe)
  // Por ahora: simulación del pago. Reemplazar por fetch a stripe-payments EF.
  appState.autoImportFeePaid = true;
  appState.autoImportPaidAt = new Date().toISOString();

  const successTitle = dict['toast_paid_success_title'] || '✅ Asesoría reservada';
  const successDesc = (dict['toast_paid_success_desc'] || 'Comisión Sabí {fee} AWG cobrada. Ahora puedes usar el Asesor Sabí y la Guía Broker.')
    .replace('{fee}', (b.feeAWG).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));

  showToast(successTitle, successDesc);

  // Re-render del wizard con estado "Activo" + CTA hacia el Asesor
  const target = document.getElementById('wizard-results-section');
  if (target) {
    const actTitle = dict['auto_calc_activated_title'] || "✅ Asesoría Activada";
    const actDesc = dict['auto_calc_activated_desc'] || "Tu comisión del <strong>4% upfront</strong> fue cobrada. Ahora puedes acceder al <strong>🤖 Asesor Sabí</strong> y a la <strong>📚 Guía Broker</strong> sin restricciones.";
    const btnGoAdvisor = dict['auto_calc_btn_go_advisor'] || "🤖 Ir al Asesor Sabí";
    const btnGoBroker = dict['auto_calc_btn_go_broker'] || "📚 Guía Broker";

    const activated = `
      <div class="sabi-auto-highlight-box success" style="margin-top:1rem">
        <div class="hl-label">${actTitle}</div>
        <p style="margin:0.65rem 0 0.85rem 0; color:var(--text-main); font-size:0.9rem">
          ${actDesc}
        </p>
        <div style="display:flex; gap:0.6rem; flex-wrap:wrap">
          <button type="button" onclick="window.switchAutoSubTab('advisor')" class="sabi-auto-submit" style="flex:1; min-width:180px">${btnGoAdvisor}</button>
          <button type="button" onclick="window.switchAutoSubTab('broker')" class="sabi-auto-submit" style="flex:1; min-width:180px; background:var(--neon-purple); border-color:var(--neon-purple); color:#fff">${btnGoBroker}</button>
        </div>
      </div>
    `;
    target.innerHTML = activated;
  }

  // Si el usuario está en un panel bloqueado, refrescarlo
  const advPanel = document.getElementById('auto-subtab-advisor');
  if (advPanel && advPanel.style.display !== 'none') {
    setTimeout(() => switchAutoSubTab('advisor'), 200);
  }
  const brokerPanel = document.getElementById('auto-subtab-broker');
  if (brokerPanel && brokerPanel.style.display !== 'none') {
    setTimeout(() => switchAutoSubTab('broker'), 200);
  }
}

// Reset de pago (para testing o cuando el admin lo solicita)
function resetAsesoriaAutoImport() {
  appState.autoImportFeePaid = false;
  appState.autoImportPaidAt = null;
  showToast('Asesoría reiniciada', 'Tu estado de pago fue reseteado.');
  if (typeof renderImportTrackingList === 'function') renderImportTrackingList();
}

