function loadAdvisorFromMarket(vehicleId) {
  const v = SABI_MARKET_DATA.find(x => x.id === vehicleId);
  if (!v) return;

  // Switch to advisor tab
  switchAutoSubTab('advisor');

  // Pre-fill the form
  setTimeout(() => {
    document.getElementById('adv-lot-link').value = `[Sabí Market] ${v.name} ${v.year}`;
    document.getElementById('adv-year').value = v.year;
    document.getElementById('adv-model').value = v.name;
    document.getElementById('adv-mileage').value = '';
    document.getElementById('adv-fuel').value = v.fuel;
    document.getElementById('adv-title').value = 'salvage';
    document.getElementById('adv-yard').value = 'Miami, FL';
    document.getElementById('adv-budget').value = v.dealerAWG;

    // Auto-analyze
    setTimeout(runLotAdvisor, 200);
  }, 100);
  try { SoundEffects.playClick(); } catch(e) {}
}

window.renderMarketComparison = renderMarketComparison;
