// ==================== SABI — MÓDULO DE CONTABILIDAD (Solo Admin) ====================
// Estas funciones solo son invocables por usuarios con appState.isAdmin === true.
// La lista de admins se mantiene en la constante SABI_ADMIN_EMAILS y/o en la
// tabla supabase 'sabi_admins' (configurable).

const SABI_ADMIN_EMAILS = ['amauryrojas@gmail.com'];
const SABI_ACCOUNTING_FN_BASE = '/functions/v1/accounting-';

// 1. Inicialización: muestra la pestaña de Contabilidad siempre.
// Por ahora solo Amaury (owner) tiene acceso al panel. El backend (Edge Functions)
// también valida con amaury@gmail.com como fallback.
function initContabilidad() {
  // El rol de administrador se basa únicamente en el rol del perfil autenticado
  const isAdmin = appState.userProfile && appState.userProfile.role === 'admin';

  appState.isAdmin = isAdmin;
  appState.adminEmail = isAdmin ? appState.userProfile.email : null;

  // El botón solo es visible si es administrador
  const navBtn = document.getElementById('main-tab-btn-contabilidad');
  if (navBtn) {
    navBtn.style.display = isAdmin ? '' : 'none';
    navBtn.title = isAdmin
      ? 'Panel de Contabilidad (admin: ' + appState.adminEmail + ')'
      : 'Solo administradores — no tienes permisos de admin';
  }

  if (isAdmin) {
    // Auto-switch a contabilidad si viene por deep-link
    try {
      const params = new URLSearchParams(window.location.search);
      if (params.get('tab') === 'contabilidad') {
        switchMainTab('contabilidad');
      }
    } catch (e) { /* ignore */ }
    // Cargar último estado en background
    setTimeout(cargarContabilidad, 500);
  }
}

// 2. Llama a la EF accounting-{type} para forzar un cierre AHORA.
async function cerrarContabilidadAhora(reportType) {
  if (!appState.isAdmin) {
    showToast('🔒 Acceso denegado', 'Solo administradores pueden generar cierres.', 'error');
    return;
  }
  const type = String(reportType || '').toLowerCase();
  if (['daily', 'weekly', 'monthly', 'annual'].indexOf(type) === -1) {
    showToast('Tipo inválido', 'daily/weekly/monthly/annual', 'error');
    return;
  }
  setContabilidadStatus('⏳ Ejecutando cierre ' + type + '...');
  try {
    // Llamamos a la EF wrapper (accounting-{type}) que internamente llama
    // a accounting-close. La auth se hace con el token JWT de la sesión del usuario.
    const fnUrl = (window.SUPABASE_URL || 'https://bfbqiocegzjqbogvjlux.supabase.co') + SABI_ACCOUNTING_FN_BASE + type;

    let authToken = SUPABASE_KEY;
    if (supabaseClient) {
      try {
        const sessionRes = await supabaseClient.auth.getSession();
        if (sessionRes.data?.session?.access_token) {
          authToken = sessionRes.data.session.access_token;
        }
      } catch (e) {}
    }

    const resp = await fetch(fnUrl, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${authToken}`
      },
      body: JSON.stringify({}),
    });
    const body = await resp.json();
    if (!resp.ok || !body.success) {
      setContabilidadStatus('❌ Error: ' + (body && body.error ? body.error : ('HTTP ' + resp.status)));
      showToast('Error', body && body.error ? body.error : 'Cierre falló', 'error');
      return;
    }
    showToast('✅ Cierre ' + type + ' OK', 'GMV Afl. ' + (body.totals && body.totals.gmv_awg ? body.totals.gmv_awg.toFixed(2) : '0.00'), 'info');
    setContabilidadStatus('✅ Cierre ' + type + ' OK — ID ' + body.report_id);
    await cargarContabilidad();
  } catch (e) {
    setContabilidadStatus('❌ Excepción: ' + String(e));
    showToast('Error', String(e), 'error');
  }
}

// 3. Lee los últimos reportes de la tabla accounting_reports (vía cliente supabase).
async function cargarContabilidad() {
  if (!appState.isAdmin) return;
  setContabilidadStatus('Cargando cierres...');
  try {
    let supabase = (typeof window.supabaseAdminClient !== 'undefined' && window.supabaseAdminClient) ||
                   (typeof supabaseAdminClient !== 'undefined' && supabaseAdminClient) ||
                   (typeof window.supabaseClient !== 'undefined' && window.supabaseClient) ||
                   (typeof supabaseClient !== 'undefined' && supabaseClient) ||
                   null;

    if (!supabase) {
      // Si no hay cliente admin, hacemos fetch directo con el token JWT de la sesión del usuario.
      let userToken = window.SUPABASE_ANON_KEY || '';
      if (supabaseClient) {
        try {
          const sessionRes = await supabaseClient.auth.getSession();
          if (sessionRes.data?.session?.access_token) {
            userToken = sessionRes.data.session.access_token;
          }
        } catch (e) {}
      }
      const sbUrl = (window.SUPABASE_URL || 'https://bfbqiocegzjqbogvjlux.supabase.co') + '/rest/v1/accounting_reports?order=generated_at.desc&limit=30';
      const headers = {
        'apikey': window.SUPABASE_ANON_KEY || '',
        'Authorization': 'Bearer ' + userToken,
      };
      const resp = await fetch(sbUrl, { headers });
      if (!resp.ok) {
        setContabilidadStatus('❌ Error cargando cierres: HTTP ' + resp.status);
        return;
      }
      const data = await resp.json();
      renderContabilidadCards(data);
      return;
    }

    const { data, error } = await supabase
      .from('accounting_reports')
      .select('*')
      .order('generated_at', { ascending: false })
      .limit(30);
    if (error) {
      setContabilidadStatus('❌ ' + error.message);
      return;
    }
    renderContabilidadCards(data || []);
  } catch (e) {
    setContabilidadStatus('❌ Excepción: ' + String(e));
  }
}

// 4. Renderiza las 4 cards y la tabla histórica.
function renderContabilidadCards(reports) {
  reports = reports || [];
  // Cachear
  appState.sabiAccountingCache.history = reports.slice(0, 30);
  appState.sabiAccountingCache.lastSync = new Date().toISOString();

  // 1. Por cada tipo, encontrar el último
  const latest = { daily: null, weekly: null, monthly: null, annual: null };
  for (let i = 0; i < reports.length; i++) {
    const r = reports[i];
    if (!latest[r.report_type]) latest[r.report_type] = r;
  }
  for (const t of ['daily', 'weekly', 'monthly', 'annual']) {
    appState.sabiAccountingCache[t] = latest[t];
  }

  // 2. Extraer el último reporte diario y compararlo con el anterior
  // Para que el delta y sparkline tengan datos
  const dailyReports = reports.filter(r => r.report_type === 'daily');
  const prevDaily = dailyReports.length > 1 ? dailyReports[1] : null;
  const currentDaily = latest.daily;

  // 3. Calcular 8 KPIs con valor y delta
  // Def: KPI = { key, icon, label, value, prevValue, caption, color }
  const kpis = [];

  // KPI 1: Revenue hoy
  const rev = (currentDaily && currentDaily.totals && currentDaily.totals.total_revenue_awg) || 0;
  const revPrev = (prevDaily && prevDaily.totals && prevDaily.totals.total_revenue_awg) || 0;
  kpis.push({
    key: 'revenue',
    icon: '💰',
    label: 'Revenue hoy',
    value: rev,
    prevValue: revPrev,
    color: '#06d6a0',
    caption: 'Comisión total Sabí del cierre diario',
    spark: extractSparkFromHistory(dailyReports, 'total_revenue_awg'),
  });

  // KPI 2: GMV hoy
  const gmv = (currentDaily && currentDaily.totals && currentDaily.totals.gmv_awg) || 0;
  const gmvPrev = (prevDaily && prevDaily.totals && prevDaily.totals.gmv_awg) || 0;
  kpis.push({
    key: 'gmv',
    icon: '📊',
    label: 'GMV hoy',
    value: gmv,
    prevValue: gmvPrev,
    color: '#00f5d4',
    caption: 'Volumen total de transacciones (AWG)',
    spark: extractSparkFromHistory(dailyReports, 'gmv_awg'),
  });

  // KPI 3: Comisiones hoy
  const com = (currentDaily && currentDaily.totals && currentDaily.totals.total_commission_awg) || 0;
  const comPrev = (prevDaily && prevDaily.totals && prevDaily.totals.total_commission_awg) || 0;
  kpis.push({
    key: 'commission',
    icon: '💳',
    label: 'Comisiones hoy',
    value: com,
    prevValue: comPrev,
    color: '#ffd700',
    caption: 'Total comisiones Sabí cobradas',
    spark: extractSparkFromHistory(dailyReports, 'total_commission_awg'),
  });

  // KPI 4: Auto Import fee cobrada
  const autoFee = (currentDaily && currentDaily.totals && currentDaily.totals.auto_import_fee_awg) || 0;
  const autoFeePrev = (prevDaily && prevDaily.totals && prevDaily.totals.auto_import_fee_awg) || 0;
  kpis.push({
    key: 'auto_import',
    icon: '🚗',
    label: 'Auto Import fee',
    value: autoFee,
    prevValue: autoFeePrev,
    color: '#ff6b6b',
    caption: 'Comisión 4% upfront vehículos',
    spark: extractSparkFromHistory(dailyReports, 'auto_import_fee_awg'),
  });

  // KPI 5: Marketplace orders
  const mkt = (currentDaily && currentDaily.breakdown && currentDaily.breakdown.marketplace) ? currentDaily.breakdown.marketplace.orders : 0;
  const mktPrev = (prevDaily && prevDaily.breakdown && prevDaily.breakdown.marketplace) ? prevDaily.breakdown.marketplace.orders : 0;
  kpis.push({
    key: 'marketplace',
    icon: '📦',
    label: 'Órdenes Marketplace',
    value: mkt,
    prevValue: mktPrev,
    color: '#9b87f5',
    caption: 'Ventas de la tienda de la comunidad',
    spark: extractSparkFromHistory(dailyReports, 'marketplace.orders'),
  });

  // KPI 6: Lotería wagers — ENGAGEMENT, NO REVENUE.
    // La lotería no genera ingresos para Sabí. Es contenido de enganche
    // que empuja a usuarios hacia marketplace, delivery e importaciones.
    // Se reporta en una sección aparte del panel ("📣 Engagement") y
    // NUNCA se suma a GMV/Revenue/Commission.
    const lot = (currentDaily && currentDaily.breakdown && currentDaily.breakdown.lottery) ? currentDaily.breakdown.lottery.wagers : 0;
    const lotPrev = (prevDaily && prevDaily.breakdown && prevDaily.breakdown.lottery) ? prevDaily.breakdown.lottery.wagers : 0;
    kpis.push({
      key: 'lottery',
      kind: 'informational',
      icon: '🎰',
      label: 'Wagers Suerte',
      value: lot,
      prevValue: lotPrev,
      color: '#ff9bff',
      caption: 'Apuestas realizadas · Engagement (no es revenue)',
      spark: extractSparkFromHistory(dailyReports, 'lottery.wagers'),
    });

  // KPI 7: Suscripciones nuevas
  const subs = (currentDaily && currentDaily.breakdown && currentDaily.breakdown.subscriptions) ? currentDaily.breakdown.subscriptions.new_subs : 0;
  const subsPrev = (prevDaily && prevDaily.breakdown && prevDaily.breakdown.subscriptions) ? prevDaily.breakdown.subscriptions.new_subs : 0;
  kpis.push({
    key: 'subscriptions',
    icon: '👥',
    label: 'Suscripciones nuevas',
    value: subs,
    prevValue: subsPrev,
    color: '#06d6a0',
    caption: 'Nuevas altas Premium del día',
    spark: extractSparkFromHistory(dailyReports, 'subscriptions.new_subs'),
  });

  // KPI 8: Canales monetarios con datos (9 totales: marketplace, subscriptions,
    // delivery, china, amazon, auto_import, credit, manual_payments, realtime_hits)
    const ch = (currentDaily && currentDaily.totals && currentDaily.totals.channels_with_data) || 0;
    const chTotal = (currentDaily && currentDaily.totals && currentDaily.totals.channels_total) || 9;
    const chPrev = (prevDaily && prevDaily.totals && prevDaily.totals.channels_with_data) || 0;
  kpis.push({
    key: 'channels',
    icon: '🌐',
    label: 'Canales con datos',
    value: ch,
    valueSecondary: chTotal,
    prevValue: chPrev,
    color: '#ffd700',
    caption: 'De 10 canales posibles reportando',
    isRatio: true,
    spark: extractSparkFromHistory(dailyReports, 'channels_with_data'),
  });

  // 4. Render del KPI grid — separa monetarios de engagement
    const grid = document.getElementById('contabilidad-kpi-grid');
    const engagementGrid = document.getElementById('contabilidad-kpi-engagement');
    if (grid) {
      let htmlMonetary = '';
      let htmlEngagement = '';
      for (let i = 0; i < kpis.length; i++) {
        const k = kpis[i];
        const isZero = !k.value || k.value === 0;
        const isInformational = k.kind === 'informational';
        const delta = computeDelta(k.value, k.prevValue);
        const valueDisplay = k.isRatio
          ? k.value + ' <span style="font-size:0.85rem; opacity:0.6">/ ' + (k.valueSecondary || 0) + '</span>'
          : (isZero
            ? '<span style="opacity:0.5">Afl. 0.00</span>'
            : fmtAWG(k.value));
        const deltaDisplay = isZero
          ? '<span class="sabi-kpi-delta flat">— sin datos</span>'
          : '<span class="sabi-kpi-delta ' + delta.cls + '">' + delta.symbol + ' ' + delta.text + '</span>';
        const sparkDisplay = isZero
          ? '<div class="sabi-kpi-spark-empty"><div class="dash-track"></div></div>'
          : renderSparkline(k.spark || [], k.color);

        const cardHtml = '<div class="sabi-kpi-card' + (isInformational ? ' sabi-kpi-card-informational' : '') + '" data-kpi-key="' + k.key + '">' +
          '  <div class="sabi-kpi-label">' + k.label + '<span class="sabi-kpi-icon">' + k.icon + '</span></div>' +
          '  <div class="sabi-kpi-value' + (isZero ? ' is-zero' : '') + '">' + valueDisplay + '</div>' +
          '  ' + deltaDisplay +
          '  ' + sparkDisplay +
          '  <div class="sabi-kpi-caption">' + k.caption + '</div>' +
          '</div>';
        if (isInformational) {
          htmlEngagement += cardHtml;
        } else {
          htmlMonetary += cardHtml;
        }
      }
      grid.innerHTML = htmlMonetary;
      if (engagementGrid) engagementGrid.innerHTML = htmlEngagement;
      // Disparar el flash en KPIs que cambiaron (animation re-trigger)
      requestAnimationFrame(() => flashChangedKpis(kpis));
    }

  // 5. Render de la tabla histórica.
  // Si NO hay cierres aún (BD vacía), mostramos la ESTRUCTURA de cierres
  // esperada como placeholders con ceros reales. NO son datos simulados,
  // son metadatos: filas virtuales que representan el período que el sistema
  // va a cerrar. Cada cierre real desde la EF reemplazará su fila.
  const tbody = document.getElementById('contabilidad-history-body');
  if (!tbody) return;
  if (!reports.length) {
    // Sin cierres aún → mostrar estructura de cierres esperados
    const placeholderRows = buildPlaceholderRows();
    tbody.innerHTML = placeholderRows;
    setContabilidadStatus('0 cierres generados · mostrando ' + placeholderRows.match(/<tr/g).length + ' períodos esperados');
    updateLastSyncLabel();
    return;
  }
  let rows = '';
  for (let i = 0; i < reports.length; i++) {
    const r = reports[i];
    const period = new Date(r.period_start).toISOString().slice(0, 10) + ' → ' + new Date(r.period_end).toISOString().slice(0, 10);
    const gmvR = (r.totals && r.totals.gmv_awg) || 0;
    const revR = (r.totals && r.totals.total_revenue_awg) || 0;
    const comR = (r.totals && r.totals.total_commission_awg) || 0;
    const channelsR = (r.totals && r.totals.channels_with_data) || 0;
    const gen = new Date(r.generated_at).toLocaleString();
    rows += '<tr>';
    rows += '<td><span style="background:rgba(0,245,212,0.12); padding:2px 8px; border-radius:6px; font-size:0.8rem; font-weight:700">' + r.report_type.toUpperCase() + '</span></td>';
    rows += '<td style="font-size:0.8rem">' + period + '</td>';
    rows += '<td>' + fmtAWG(gmvR) + '</td>';
    rows += '<td>' + fmtAWG(revR) + '</td>';
    rows += '<td>' + fmtAWG(comR) + '</td>';
    rows += '<td style="text-align:center">' + channelsR + '/10</td>';
    rows += '<td style="font-size:0.78rem">' + gen + '</td>';
    rows += '<td><button type="button" data-rid="' + r.id + '" data-rtype="' + r.report_type + '" data-rstart="' + (r.period_start || '') + '" onclick="window.descargarReporteContabilidadJSON(this.dataset.rid, this.dataset.rtype, this.dataset.rstart)" class="sabi-auto-submit" style="padding:0.3rem 0.6rem; font-size:0.75rem">📥 JSON</button></td>';
    rows += '</tr>';
  }
  tbody.innerHTML = rows;
  setContabilidadStatus('Cargados ' + reports.length + ' cierres · ' + ch + '/' + chTotal + ' canales con datos');
  updateLastSyncLabel();
}

// === Helpers de Sabí Contabilidad ===

// Genera filas "placeholder" para la tabla histórica cuando no hay cierres
// aún en la BD. NO son datos simulados ni inventados: solo representan la
// ESTRUCTURA del esquema (períodos que el cron job va a cerrar) con ceros
// reales. Cada fila tiene:
//   - Tipo (DAILY / WEEKLY / MONTHLY / ANNUAL) con badge dimmed
//   - Período (ej: "2026-07-14 → 2026-07-15" para el día siguiente)
//   - GMV, Revenue, Comisiones: Afl. 0.00 (real, no inventado)
//   - Canales: 0 / 9 (real)
//   - Generado: "— (pendiente)" + badge dimmed
// Cuando llegue un cierre real desde la EF, la fila se reemplaza por la real.
function buildPlaceholderRows() {
  const rows = [];
  const PLACEHOLDER_BADGE = 'background:rgba(255,255,255,0.05); color:var(--text-muted); padding:2px 8px; border-radius:6px; font-size:0.7rem; font-weight:700; font-style:italic';
  const PLACEHOLDER_TD = 'color:var(--text-muted); font-style:italic; opacity:0.65';
  const NOW = new Date();

  // Estructura esperada:
  //   - 30 cierres diarios (los últimos 30 días)
  //   - 4 cierres semanales (las últimas 4 semanas)
  //   - 3 cierres mensuales (los últimos 3 meses)
  //   - 1 cierre anual (el último año)

  function fmtEmptyDate(d) { return d.toISOString().slice(0, 10); }

  function makeRow(type, start, end, label) {
    const periodStr = fmtEmptyDate(start) + ' → ' + fmtEmptyDate(end);
    return '<tr style="opacity:0.55">' +
      '<td><span style="' + PLACEHOLDER_BADGE + '">' + type + '</span></td>' +
      '<td style="font-size:0.8rem; ' + PLACEHOLDER_TD + '">' + periodStr + '<br><span style="font-size:0.65rem; opacity:0.7">' + label + '</span></td>' +
      '<td style="' + PLACEHOLDER_TD + '">Afl. 0.00</td>' +
      '<td style="' + PLACEHOLDER_TD + '">Afl. 0.00</td>' +
      '<td style="' + PLACEHOLDER_TD + '">Afl. 0.00</td>' +
      '<td style="text-align:center; ' + PLACEHOLDER_TD + '">0 / 9</td>' +
      '<td style="font-size:0.78rem; ' + PLACEHOLDER_TD + '">— (pendiente)</td>' +
      '<td><span style="font-size:0.7rem; color:var(--text-muted); font-style:italic">espera cierre</span></td>' +
      '</tr>';
  }

  // 30 cierres diarios esperados (los últimos 30 días, empezando por hoy)
  for (let i = 0; i < 30; i++) {
    const end = new Date(NOW);
    end.setUTCDate(end.getUTCDate() - i);
    end.setUTCHours(0, 0, 0, 0);
    const start = new Date(end);
    start.setUTCDate(start.getUTCDate() - 1);
    if (i === 0) {
      rows.push(makeRow('DAILY', start, end, 'cierre al final del día'));
    } else {
      rows.push(makeRow('DAILY', start, end, 'cierre diario esperado'));
    }
  }

  // 4 cierres semanales esperados
  const lastSunday = new Date(NOW);
  lastSunday.setUTCHours(0, 0, 0, 0);
  const dow = lastSunday.getUTCDay();
  lastSunday.setUTCDate(lastSunday.getUTCDate() - dow);
  for (let i = 0; i < 4; i++) {
    const end = new Date(lastSunday);
    end.setUTCDate(end.getUTCDate() - i * 7);
    const start = new Date(end);
    start.setUTCDate(start.getUTCDate() - 7);
    rows.push(makeRow('WEEKLY', start, end, 'cierre semanal domingo 00:00'));
  }

  // 3 cierres mensuales esperados
  for (let i = 0; i < 3; i++) {
    const monthEnd = new Date(Date.UTC(NOW.getUTCFullYear(), NOW.getUTCMonth() - i, 1, 0, 0, 0, 0));
    const monthStart = new Date(Date.UTC(NOW.getUTCFullYear(), NOW.getUTCMonth() - i - 1, 1, 0, 0, 0, 0));
    rows.push(makeRow('MONTHLY', monthStart, monthEnd, 'cierre mensual día 1 00:00'));
  }

  // 1 cierre anual esperado
  const yearEnd = new Date(Date.UTC(NOW.getUTCFullYear(), 0, 1, 0, 0, 0, 0));
  const yearStart = new Date(Date.UTC(NOW.getUTCFullYear() - 1, 0, 1, 0, 0, 0, 0));
  rows.push(makeRow('ANNUAL', yearStart, yearEnd, 'cierre anual 1 enero 00:00'));

  return rows.join('');
}

// Extrae un array de valores históricos para un path tipo 'totals.gmv_awg' o 'breakdown.marketplace.orders'
function extractSparkFromHistory(reports, dotPath) {
  // Devuelve array de últimos 30 valores (números) en orden cronológico
  const out = [];
  if (!reports || !reports.length) return out;
  // Reports vienen en orden DESC (más reciente primero), los invertimos
  const sorted = reports.slice(0, 30).slice().reverse();
  for (let i = 0; i < sorted.length; i++) {
    const r = sorted[i];
    if (!r) continue;
    const parts = dotPath.split('.');
    let v = r;
    for (let j = 0; j < parts.length; j++) {
      v = v && v[parts[j]];
    }
    if (typeof v === 'number' && !isNaN(v)) out.push(v);
  }
  return out;
}

// Calcula delta % entre current y previous. Devuelve {cls, symbol, text}
function computeDelta(current, previous) {
  if (!previous || previous === 0) {
    return { cls: 'up', symbol: '↑', text: 'inicio' };
  }
  if (!current || current === 0) {
    return { cls: 'down', symbol: '↓', text: '—' };
  }
  const diff = current - previous;
  const pct = (diff / previous) * 100;
  const absPct = Math.abs(pct);
  if (absPct < 1) {
    return { cls: 'flat', symbol: '→', text: '0.0%' };
  }
  if (pct > 0) {
    return { cls: 'up', symbol: '↑', text: '+' + absPct.toFixed(1) + '%' };
  }
  return { cls: 'down', symbol: '↓', text: '-' + absPct.toFixed(1) + '%' };
}

// Renderiza un sparkline SVG inline para un array de valores
function renderSparkline(values, color) {
  if (!values || values.length < 1) {
    return '<div class="sabi-kpi-spark-empty"><div class="dash-track"></div></div>';
  }
  if (values.length < 2) {
    // Un solo punto, dibujamos un dot centrado
    return '<svg class="sabi-kpi-spark" viewBox="0 0 100 28" preserveAspectRatio="none"><circle cx="50" cy="14" r="2.5" class="spark-dot" /></svg>';
  }
  const W = 100, H = 28, PAD = 2;
  const minV = Math.min.apply(null, values);
  const maxV = Math.max.apply(null, values);
  const range = (maxV - minV) || 1;
  const stepX = (W - 2 * PAD) / (values.length - 1);
  const points = [];
  for (let i = 0; i < values.length; i++) {
    const x = PAD + i * stepX;
    const y = PAD + (1 - (values[i] - minV) / range) * (H - 2 * PAD);
    points.push(x.toFixed(1) + ',' + y.toFixed(1));
  }
  const polyline = points.join(' ');
  const lastVal = values[values.length - 1];
  const lastX = PAD + (values.length - 1) * stepX;
  const lastY = PAD + (1 - (lastVal - minV) / range) * (H - 2 * PAD);
  // Fill area under the line
  const fillPath = 'M ' + PAD + ',' + H + ' L ' + polyline.replace(/,/g, ' ').split(' ').map((v, i) => i % 2 === 0 ? v : '').filter(Boolean).join(' L ').replace('L  L ', 'L ') + ' L ' + (W - PAD) + ',' + H + ' Z';
  // Simpler: build area path
  const areaPath = 'M ' + PAD + ',' + H + ' L ' + polyline.replace(/,/g, ' L') + ' L ' + (W - PAD) + ',' + H + ' Z';
  return '<svg class="sabi-kpi-spark" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none">' +
    '<path d="' + areaPath + '" class="spark-fill" />' +
    '<polyline points="' + polyline + '" class="spark-line" />' +
    '<circle cx="' + lastX.toFixed(1) + '" cy="' + lastY.toFixed(1) + '" r="2.5" class="spark-dot" />' +
    '</svg>';
}

// Dispara el flash en KPIs cuyo valor cambió respecto a la última renderización.
// Usa el cache en memoria para detectar cambios.
function flashChangedKpis(kpis) {
  const prev = appState.sabiAccountingCache._kpiValues || {};
  const next = {};
  for (let i = 0; i < kpis.length; i++) {
    const k = kpis[i];
    next[k.key] = k.value;
    const oldVal = prev[k.key];
    if (oldVal !== undefined && oldVal !== k.value && k.value !== 0) {
      // Disparar la animación
      const card = document.querySelector('[data-kpi-key="' + k.key + '"]');
      if (card) {
        card.classList.remove('kpi-flash');
        // Force reflow para reiniciar la animación
        void card.offsetWidth;
        card.classList.add('kpi-flash');
      }
    }
  }
  appState.sabiAccountingCache._kpiValues = next;
}

// Actualiza el label de "Última sync" y "Próxima sync"
function updateLastSyncLabel() {
  const lastEl = document.getElementById('contabilidad-last-sync');
  if (lastEl && appState.sabiAccountingCache.lastSync) {
    lastEl.textContent = new Date(appState.sabiAccountingCache.lastSync).toLocaleTimeString();
  }
  // Próxima sync: countdown de 30s
  if (window.sabiContabNextSyncAt) {
    const remaining = Math.max(0, Math.round((window.sabiContabNextSyncAt - Date.now()) / 1000));
    const nextEl = document.getElementById('contabilidad-next-sync');
    if (nextEl) nextEl.textContent = remaining + 's';
  }
}

// === Auto-refresh ===
let sabiContabInterval = null;
let sabiContabPause = false;

function startContabAutoRefresh() {
  if (sabiContabInterval) return;
  const tick = () => {
    if (sabiContabPause) return;
    // Solo refrescar si el panel es visible
    const contab = document.getElementById('contabilidad-section');
    if (contab && contab.style.display !== 'none' && appState.isAdmin) {
      cargarContabilidad();
    }
    window.sabiContabNextSyncAt = Date.now() + 30000;
    updateLastSyncLabel();
  };
  // Primer tick en 5s, luego cada 30s
  window.sabiContabNextSyncAt = Date.now() + 30000;
  sabiContabInterval = setInterval(tick, 30000);
  setTimeout(tick, 5000);
  // El toggle Auto on/off
  setTimeout(() => {
    const toggle = document.getElementById('contabilidad-autorefresh');
    if (toggle) {
      sabiContabPause = !toggle.checked;
      toggle.addEventListener('change', () => {
        sabiContabPause = !toggle.checked;
        if (toggle.checked) {
          cargarContabilidad();
        }
        // Animar el dot
        const dot = document.querySelector('.sabi-pulse-dot');
        if (dot) dot.classList.toggle('paused', sabiContabPause);
      });
    }
  }, 1000);
}

function stopContabAutoRefresh() {
  if (sabiContabInterval) {
    clearInterval(sabiContabInterval);
    sabiContabInterval = null;
  }
}

// Hook: arrancar el auto-refresh al inicializar
(function patchContabInit() {
  const origInit = initContabilidad;
  // Envolver para arrancar auto-refresh al final
  if (origInit && !origInit._sabiContabPatched) {
    initContabilidad = function () {
      const r = origInit.apply(this, arguments);
      if (appState.isAdmin) {
        setTimeout(startContabAutoRefresh, 1500);
      }
      return r;
    };
    initContabilidad._sabiContabPatched = true;
  }
})();

