// 5. Descarga el último cierre de un tipo dado (si hay) en JSON.
function descargarReporteContabilidad(reportType) {
  if (!appState.isAdmin) {
    showToast('🔒 Acceso denegado', 'Solo administradores pueden descargar reportes.', 'error');
    return;
  }
  const r = appState.sabiAccountingCache[reportType];
  if (!r) {
    showToast('Sin cierre', 'No hay un cierre ' + reportType + ' aún. Genera uno con "🔄 Cerrar".', 'info');
    return;
  }
  descargarReporteContabilidadJSON(r.id, r.report_type, r.period_start, r.period_end);
}

// 5b. Descarga un reporte específico de la BD.
async function descargarReporteContabilidadJSON(reportId, reportType, periodStart, periodEnd) {
  if (!appState.isAdmin) {
    showToast('🔒 Acceso denegado', 'Solo administradores pueden descargar reportes.', 'error');
    return;
  }
  try {
    // Hacemos fetch directo para obtener el JSON completo (todos los campos)
    const sbUrl = (window.SUPABASE_URL || 'https://bfbqiocegzjqbogvjlux.supabase.co') + '/rest/v1/accounting_reports?id=eq.' + encodeURIComponent(reportId) + '&limit=1';
    const headers = {
      'apikey': window.SUPABASE_ANON_KEY || '',
      'Authorization': 'Bearer ' + (window.SUPABASE_ANON_KEY || ''),
    };
    const resp = await fetch(sbUrl, { headers });
    if (!resp.ok) {
      showToast('Error', 'No se pudo descargar el cierre (HTTP ' + resp.status + ')', 'error');
      return;
    }
    const arr = await resp.json();
    if (!arr.length) {
      showToast('Error', 'Cierre no encontrado en la BD', 'error');
      return;
    }
    const r = arr[0];
    const filename = 'sabi_accounting_' + r.report_type + '_' + (r.period_start || '').slice(0, 10) + '.json';
    const blob = new Blob([JSON.stringify(r, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
    showToast('📥 Descargado', filename, 'info');
  } catch (e) {
    showToast('Error', String(e), 'error');
  }
}

// Helper: formato AWG
function fmtAWG(n) {
  const v = Number(n) || 0;
  return 'Afl. ' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Helper: status de la UI de contabilidad
function setContabilidadStatus(text) {
  const el = document.getElementById('contabilidad-status');
  if (el) el.textContent = text;
}

// Sobrescribe switchMainTab para que 'contabilidad' y 'chat' funcionen
(function patchSwitchMainTab() {
  if (typeof window.switchMainTab !== 'function') return;
  // El switchMainTab actual ya itera data-main-tab, solo tenemos que asegurarnos
  // que la sección se muestre y se inicialicen los datos cuando el usuario hace click.
  const orig = window.switchMainTab;
  if (orig && !orig._sabiContabilidadPatched) {
    window.switchMainTab = function(tab) {
      orig(tab);
      if (tab === 'contabilidad') {
        // El switch normal ya muestra la sección; cargamos los datos
        if (typeof cargarContabilidad === 'function' && appState.isAdmin) {
          cargarContabilidad();
        }
      }
      if (tab === 'chat') {
        if (typeof initChat === 'function') {
          initChat();
        }
      }
    };
    window.switchMainTab._sabiContabilidadPatched = true;
  }
})();

