const SABI_ASSURANCE_CONTACT_PATTERNS = [
  /\b[\w.+-]+@[\w-]+\.[\w.-]+\b/i, // email
  /\b(?:https?:\/\/|www\.)\S+/i, // links
  /(?:\+?\d[\d\s().-]{6,}\d)/, // phone numbers
  /\b(?:whatsapp|telegram|instagram|facebook|tiktok|correo|e-?mail|tel[eé]fono|ll[aá]mame|cont[aá]ctame)\b/i,
  /(^|\s)@[a-z0-9_.-]{2,}/i // social handles
];

function containsContactInfo(text) {
  return SABI_ASSURANCE_CONTACT_PATTERNS.some(pattern => pattern.test(text));
}

