function selectChatThread(contactId) {
  activeContactId = contactId;
  const thread = chats.find(c => c.contactId === contactId);
  if (!thread) return;
  
  // Actualizar cabecera activa
  const photoEl = document.getElementById("chat-contact-photo");
  if (photoEl) {
    photoEl.src = thread.contactPhoto;
    photoEl.style.display = "block";
  }
  document.getElementById("chat-contact-name").innerText = thread.contactName;
  
  const badge = document.getElementById("chat-contact-role-badge");
  if (thread.contactRole === 'merchant') {
    badge.innerText = "COMERCIO";
    badge.style.background = "var(--neon-gold)";
    badge.style.display = "inline";
  } else {
    badge.style.display = "none";
  }
  
  // Renderizar resumen de reseñas
  const reviewsSummary = document.getElementById("chat-contact-reviews-summary");
  const count = userReviews[contactId] ? userReviews[contactId].length : 0;
  const avg = getAverageRating(contactId);
  reviewsSummary.innerHTML = `${getRatingStarsHtml(contactId)} <span style="color:var(--text-muted); font-size:0.65rem">(${avg} • ${count} reseñas)</span>`;
  reviewsSummary.onclick = () => openUserReviewsModalFor(contactId);
  
  const policyBtn = document.getElementById("chat-mediation-policy-btn");
  if (policyBtn) policyBtn.style.display = "flex";
  document.getElementById("chat-input-container").style.display = "flex";
  
  // Renderizar burbujas de mensajes
  renderChatMessages();
  renderChatThreads(); // Refrescar selección
  
  // Scroll al final
  const historyDiv = document.getElementById("chat-messages-history");
  setTimeout(() => {
    historyDiv.scrollTop = historyDiv.scrollHeight;
  }, 50);
}

