function updateHeaderProfileButton() {
  const photoEl = document.getElementById("header-profile-photo");
  const nameEl = document.getElementById("header-profile-name");
  const starsEl = document.getElementById("header-profile-stars");
  
  if (!appState || !appState.userProfile) return;

  if (photoEl && appState.userProfile.photo) {
    photoEl.src = appState.userProfile.photo;
  }
  if (nameEl && appState.userProfile.name) {
    nameEl.innerText = appState.userProfile.name;
  }
  if (starsEl && typeof getRatingStarsHtml === 'function') {
    starsEl.innerHTML = getRatingStarsHtml('amaury_rojas');
  }
}
window.updateHeaderProfileButton = updateHeaderProfileButton;

function startInAppChat(userName, contactPhoto) {
  // Switch to chat tab
  if (typeof switchMainTab === 'function') {
    switchMainTab('chat');
  } else if (typeof window.switchMainTab === 'function') {
    window.switchMainTab('chat');
  }
  
  // Find if thread already exists
  const contactId = userName.toLowerCase().replace(/\s+/g, '_');
  let existing = chats.find(c => c.contactId === contactId);
  
  if (!existing) {
    // Create new thread
    existing = {
      contactId: contactId,
      contactName: userName,
      contactPhoto: contactPhoto || "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80",
      contactRating: 5.0,
      contactRole: "user",
      messages: [
        { sender: contactId, text: `Hola, estoy interesado en tu publicación.`, timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) }
      ]
    };
    chats.unshift(existing);
  }
  
  // Initialize chat view
  if (typeof initChat === 'function') {
    initChat();
  }
  
  // Select thread
  if (typeof selectChatThread === 'function') {
    selectChatThread(contactId);
  }
}
window.startInAppChat = startInAppChat;

